ARCHIVOS_JSON = ("reportes.json", "usuarios.json", "configuracion.json", "ajustes_operaciones.json")


def carpeta_json_de(base):
    """Carpeta donde estan los JSON de una instalacion: base\\Json, o la misma carpeta si los JSON
    estan sueltos junto al script."""
    base = Path(base)
    for d in (base / "Json", base):
        try:
            if (d / "reportes.json").is_file():
                return d
        except OSError:
            pass
    return base / "Json"


def _es_base(c):
    """Una carpeta sirve si tiene los JSON (basta reportes.json; los demas tienen valores por defecto)."""
    try:
        return c is not None and (carpeta_json_de(c) / "reportes.json").is_file()
    except OSError:
        return False


def _archivo_base_recordada():
    """Donde se recuerda la carpeta Colaterales de este usuario (una linea con la ruta)."""
    if os.environ.get("LOCALAPPDATA"):
        return Path(os.environ["LOCALAPPDATA"]) / "Colaterales" / "carpeta_base.txt"
    return Path.home() / ".colaterales" / "carpeta_base.txt"


def _leer_base_recordada():
    try:
        t = _archivo_base_recordada().read_text(encoding="utf-8").strip().strip('"')
        return Path(t) if t else None
    except OSError:
        return None


def _recordar_base(base):
    try:
        f = _archivo_base_recordada()
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_text(str(base), encoding="utf-8")
    except OSError:
        pass


_NO_ENTRAR = {"descargas", "pruebas", "logs", "_respaldos", "01_originales", "02_para_cargar", "03_revisar",
              "node_modules", "appdata", "$recycle.bin", "__pycache__", ".git"}


def _buscar_base_sincronizada(home, limite_segundos=20):
    r"""Busca la carpeta Colaterales (con Json\configuracion.json) en las bibliotecas de SharePoint/OneDrive
    sincronizadas del usuario. Cada persona puede tenerla con otro nombre, por ejemplo:
      C:\Users\x\Principal Financial Group\Gerencia Finanzas AFP - Automatizaciones Back Office\...
      C:\Users\x\Principal Financial Group\Gerencia Finanzas AFP - Automatizaciones Back Office - Documentos\...
      C:\Users\x\OneDrive - Principal Financial Group\Gerencia Finanzas AFP - ...\... (acceso directo)"""
    raices = []
    try:
        for e in os.scandir(str(home)):
            n = e.name.lower()
            if e.is_dir() and (n.startswith("principal") or n.startswith("onedrive") or "colaterales" in n
                               or "automatizaciones" in n):
                raices.append((Path(e.path), 7))
            elif e.is_dir() and n in ("documents", "documentos", "desktop", "escritorio"):
                raices.append((Path(e.path), 4))
    except OSError:
        pass
    limite = time.time() + limite_segundos
    encontrados = []
    for raiz, profundidad in raices:
        pila = [(raiz, 0)]
        while pila and time.time() < limite:
            d, nivel = pila.pop()
            if d.name.lower() == "colaterales" and _es_base(d):
                encontrados.append(d)
                continue
            if nivel >= profundidad:
                continue
            try:
                hijos = [Path(e.path) for e in os.scandir(str(d)) if e.is_dir(follow_symlinks=False)]
            except OSError:
                continue
            for h in hijos:
                n = h.name.lower()
                if n.startswith((".", "~")) or n in _NO_ENTRAR or re.fullmatch(r"\d{4}-\d{2}-\d{2}", n):
                    continue
                pila.append((h, nivel + 1))
    # primero las que estan en ...\Control Colaterales\Diario (la instalacion compartida)
    encontrados.sort(key=lambda p: (0 if "control colaterales" in str(p).lower() else 1, len(str(p))))
    return encontrados


def _junto_al_script(aqui):
    r"""Carpetas donde puede estar la copia local completa, segun como se copio:
       <carpeta>\colaterales.py + <carpeta>\Json\          (o los JSON sueltos en la misma carpeta)
       <carpeta>\Script\colaterales.py + <carpeta>\Json\  (estructura del instalador)
       <carpeta>\Colaterales\Json\ u otra subcarpeta        (se copio la carpeta dentro de otra)"""
    yield aqui
    yield aqui.parent
    try:
        hijos = sorted(Path(e.path) for e in os.scandir(str(aqui)) if e.is_dir())
    except OSError:
        hijos = []
    for h in hijos:
        if h.name.lower() in _NO_ENTRAR or re.fullmatch(r"\d{4}-\d{2}-\d{2}", h.name):
            continue
        yield h
        try:
            nietos = sorted(Path(e.path) for e in os.scandir(str(h)) if e.is_dir())
        except OSError:
            nietos = []
        for n in nietos:
            if n.name.lower() not in _NO_ENTRAR:
                yield n


def _es_compartida(base):
    return "control colaterales" in str(base).lower()


def ubicar_carpeta_base(ruta_forzada=None, interactivo=True):
    r"""Encuentra la carpeta Colaterales con los JSON (usuarios, reportes, ajustes, configuracion).
    Los JSON viven en un solo lugar, la carpeta compartida; cada persona puede tener el script donde
    quiera. Orden:
      1. --base o la variable COLATERALES_HOME
      2. la ruta recordada de este usuario (%LOCALAPPDATA%\Colaterales\carpeta_base.txt)
      3. la ruta estandar C:\Users\<usuario>\Principal Financial Group\...\Diario\Colaterales
      4. la carpeta compartida desde donde se ejecuta el script (si se ejecuta ahi mismo)
      5. busqueda en las bibliotecas de SharePoint/OneDrive sincronizadas en el equipo
      6. si no hay carpeta compartida: los JSON que esten junto al script (con aviso)
      7. si nada sirve, pide la ruta una vez y la recuerda."""
    revisadas = []

    def probar(c, origen):
        if c is None:
            return None
        c = Path(c)
        revisadas.append(str(c))
        cands = [c.parent, c] if c.name.lower() == "json" else [c, c / "Colaterales"]
        for cand in cands:
            if _es_base(cand):
                return Path(os.path.abspath(str(cand))), origen
        return None

    aqui = Path(__file__).resolve().parent
    pasos = [
        (Path(ruta_forzada) if ruta_forzada else None, "--base"),
        (Path(os.environ["COLATERALES_HOME"]) if os.environ.get("COLATERALES_HOME") else None, "variable COLATERALES_HOME"),
        (_leer_base_recordada(), "carpeta compartida, ruta recordada"),
        (Path.home() / RUTA_RELATIVA_BASE, "carpeta compartida, ruta estandar"),
    ]
    for c, origen in pasos:
        r = probar(c, origen)
        if r:
            return r
    for c in (aqui, aqui.parent):
        if _es_compartida(c):
            r = probar(c, "carpeta compartida (se ejecuta desde ahi)")
            if r:
                return r
    for c in _buscar_base_sincronizada(Path.home()):
        r = probar(c, "carpeta compartida, encontrada en tus carpetas sincronizadas")
        if r:
            _recordar_base(r[0])
            return r
    for c in _junto_al_script(aqui):
        r = probar(c, "COPIA LOCAL junto al script (no encontre la carpeta compartida)")
        if r:
            return r
    print("No encontre la carpeta compartida Colaterales (la que tiene la carpeta Json).")
    print("Para leerla, la biblioteca compartida tiene que estar sincronizada en este equipo")
    print("(abrirla solo en el navegador o en Teams no basta).")
    print("Rutas revisadas:\n  " + "\n  ".join(revisadas[:12]))
    if interactivo:
        resp = preguntar("Tienes sincronizada en este equipo la carpeta compartida 'Gerencia Finanzas AFP - "
                         "Automatizaciones Back Office'? (s/n): ", True, "n").lower()
        if not resp.startswith("s"):
            print("")
            print("Para sincronizarla:")
            print("  1. Abre la biblioteca en SharePoint o Teams (Archivos).")
            print("  2. Presiona 'Sincronizar' (o 'Agregar acceso directo a Mis archivos').")
            print("  3. Espera a que aparezca en el Explorador de archivos, a la izquierda.")
            print("Si no la ves o no tienes acceso, pidele permiso a quien administra la carpeta.")
            preguntar("Cuando este sincronizada presiona Enter para buscarla de nuevo (o cierra esta ventana): ",
                      True, "")
            for c in _buscar_base_sincronizada(Path.home()):
                r = probar(c, "carpeta compartida, encontrada en tus carpetas sincronizadas")
                if r:
                    _recordar_base(r[0])
                    return r
            for c in [Path.home() / RUTA_RELATIVA_BASE]:
                r = probar(c, "carpeta compartida, ruta estandar")
                if r:
                    return r
            print("Todavia no la encuentro.")
        print("Si ya esta sincronizada, abrela en el Explorador de archivos, copia la ruta de la barra de")
        print("direcciones (ej. C:\\Users\\...\\Control Colaterales\\Diario\\Colaterales) y pegala aqui.")
        print("Se recuerda para las proximas veces.")
        for _ in range(3):
            try:
                texto = preguntar("Ruta (Enter para salir): ", True, "").strip('"').strip("'")
            except Exception:
                texto = ""
            if not texto:
                break
            if texto.startswith("&") or ".exe" in texto.lower() or texto.lower().endswith(".py"):
                print("Eso es el comando para ejecutar el script, no una carpeta. Pega la ruta de la carpeta.")
                continue
            if texto.lower().startswith(("http:", "https:")):
                print("Esa es la direccion web de SharePoint. Primero sincroniza la biblioteca (boton Sincronizar o")
                print("'Agregar acceso directo a Mis archivos') y pega la ruta que aparece en el Explorador.")
                continue
            r = probar(Path(os.path.expandvars(os.path.expanduser(texto))), "carpeta compartida, ruta indicada")
            if r:
                _recordar_base(r[0])
                return r
            print("En esa carpeta no hay Json\\reportes.json. Intenta de nuevo.")
    raise SystemExit(
        "Sin la carpeta compartida no puedo seguir. Sincroniza la biblioteca de SharePoint "
        "(Gerencia Finanzas AFP - Automatizaciones Back Office) en este equipo y vuelve a ejecutar, "
        "o usa --base \"ruta de la carpeta Colaterales\".")


def _elegir(titulo, opciones, por_defecto=1):
    """Muestra opciones numeradas y devuelve el indice elegido (0..n-1), o None si escribe otra cosa."""
    print(titulo)
    for k, o in enumerate(opciones, 1):
        print("   %d. %s" % (k, o))
    r = preguntar("Numero (Enter = %d): " % por_defecto, True, "").strip()
    if not r:
        return por_defecto - 1
    if r.isdigit() and 1 <= int(r) <= len(opciones):
        return int(r) - 1
    return None


def _ruta_outlook_de_texto(texto):
    """'Bandeja de entrada > Colaterales > Statement' -> ["{BANDEJA_DE_ENTRADA}", "Colaterales", "Statement"]"""
    partes = [x.strip() for x in re.split(r"[>\\/]", texto) if x.strip()]
    if partes and partes[0].lower() in ("bandeja de entrada", "inbox", "{bandeja_de_entrada}"):
        partes[0] = "{BANDEJA_DE_ENTRADA}"
    elif partes:
        partes = ["{BANDEJA_DE_ENTRADA}"] + partes
    return partes


def registrar_usuario(ctx):
    """Usuario nuevo (o con datos incompletos) en usuarios.json: le pregunta lo necesario y lo guarda
    en el usuarios.json de la carpeta compartida, con respaldo. Nada de esto cambia el script."""
    previo = dict(ctx.usuarios.get("usuarios", {}).get(ctx.login) or
                  next((v for k, v in ctx.usuarios.get("usuarios", {}).items() if k.lower() == ctx.login), {}) or {})
    faltan = [k for k in ("buzon", "carpetas_outlook", "carpeta_descargas") if k not in previo]
    if previo and not faltan:
        return False
    decir("")
    decir("=" * 78)
    decir("USUARIO %s: %s" % (ctx.login, "faltan datos en usuarios.json (%s)" % ", ".join(faltan) if previo
                              else "no esta registrado en usuarios.json"))
    decir("Te hago unas preguntas y lo dejo guardado en la carpeta compartida (solo esta vez).")
    decir("=" * 78)
    nuevo = dict(previo)
    if "nombre" not in nuevo:
        nuevo["nombre"] = preguntar("Tu nombre: ", True, ctx.login) or ctx.login
    # Buzon y carpetas de Outlook
    ol = None
    try:
        ol = Outlook()
    except Exception as e:
        decir("  (No pude abrir Outlook para mostrarte tus buzones: %s)" % e)
    if "buzon" not in nuevo:
        nombres = []
        if ol is not None:
            try:
                nombres = [ol.ns.Folders.Item(i).Name for i in range(1, ol.ns.Folders.Count + 1)]
            except Exception:
                nombres = []
        nombres = [n for n in nombres if "archivo" not in n.lower() and "archive" not in n.lower()] or nombres
        if nombres:
            k = _elegir("En que buzon de Outlook llegan los statements?", nombres + ["Mi buzon predeterminado"])
            nuevo["buzon"] = None if k is None or k >= len(nombres) else nombres[k]
        else:
            t = preguntar("Buzon de Outlook tal como aparece en Outlook (Enter = el predeterminado): ", True, "")
            nuevo["buzon"] = t or None
    if "carpetas_outlook" not in nuevo:
        print("En que carpeta de Outlook llegan los correos de las contrapartes?")
        print("Escribela como la ves en Outlook, separada con >. Ej: Bandeja de entrada > Colaterales > Statement")
        rutas = []
        for _ in range(3):
            t = preguntar("Carpeta (Enter = Bandeja de entrada > Colaterales > Statement): ", True, "")
            ruta = _ruta_outlook_de_texto(t) if t else ["{BANDEJA_DE_ENTRADA}", "Colaterales", "Statement"]
            ok = True
            if ol is not None:
                try:
                    ok = ol.carpeta(nuevo.get("buzon"), ruta) is not None
                except Exception:
                    ok = False
            if ok:
                rutas.append(ruta)
                break
            print("  No encontre esa carpeta en Outlook. Revisa el nombre e intenta de nuevo.")
        rutas.append(["{BANDEJA_DE_ENTRADA}"])          # respaldo: la bandeja de entrada
        nuevo["carpetas_outlook"] = rutas
    if "carpeta_descargas" not in nuevo:
        onedrive = next((p for p in sorted(Path.home().glob("OneDrive - *"))), None)
        sugerida = (onedrive / "Colaterales") if onedrive else (Path.home() / "Colaterales")
        print("Donde quieres que queden los archivos de cada dia? Tiene que ser una ruta corta")
        print("(Excel no abre rutas de mas de 259 caracteres).")
        for _ in range(3):
            t = preguntar("Carpeta (Enter = %s): " % sugerida, True, "").strip('"')
            destino = Path(os.path.expandvars(os.path.expanduser(t))) if t else sugerida
            if len(str(destino)) > 110:
                print("  Esa ruta es muy larga (%d caracteres). Usa una mas corta." % len(str(destino)))
                continue
            try:
                ruta_larga(destino).mkdir(parents=True, exist_ok=True)
            except OSError as e:
                print("  No pude crear esa carpeta (%s). Intenta con otra." % e)
                continue
            nuevo["carpeta_descargas"] = str(destino)
            break
        else:
            nuevo["carpeta_descargas"] = str(sugerida)
    if "credenciales_vmetrix" not in nuevo and (ctx.conf.get("vmetrix") or {}).get("activo", True):
        cred = pedir_credenciales_vmetrix(ctx.login, None)
        if cred:
            nuevo["credenciales_vmetrix"] = cred
    if ol is not None and preguntar("Crear ahora en Outlook la carpeta de los statements y las reglas por contraparte "
                                    "(si ya las tienes, Enter)? (s/n): ", True, "n").lower().startswith("s"):
        try:
            nuevo["carpetas_outlook"] = configurar_outlook(ctx.reportes, ctx.conf, nuevo.get("buzon"),
                                                           nuevo.get("carpetas_outlook"), ol)
        except Exception as e:
            decir("  No pude configurar Outlook (%s). Puedes hacerlo despues con ALTA_USUARIO_COLATERALES.bat." % e)
    nuevo["carpeta_compartida"] = str(ctx.base)
    nuevo["registrado"] = dt.datetime.now().strftime("%Y-%m-%d %H:%M")
    # Guardar en el usuarios.json compartido (releyendolo, por si otro lo cambio mientras tanto)
    ruta = ctx.dir_json / "usuarios.json"
    try:
        datos = cargar_json(ruta) if ruta.is_file() else {"usuarios": {}}
        datos.setdefault("usuarios", {})
        for k in [k for k in datos["usuarios"] if k.lower() == ctx.login]:
            del datos["usuarios"][k]
        datos["usuarios"][ctx.login] = nuevo
        respaldar(ruta, ctx.dir_json / "_respaldos")
        guardar_json(ruta, datos)
        decir("Listo: quedaste registrado en %s" % ruta)
    except Exception as e:
        decir("No pude guardar en %s (%s). Esta vez sigo con estos datos; pidele a quien administra la" % (ruta, e))
        decir("carpeta que agregue este bloque en usuarios.json:")
        decir(json.dumps({ctx.login: nuevo}, ensure_ascii=False, indent=2))
    ctx.usuarios.setdefault("usuarios", {})[ctx.login] = nuevo
    ctx.usuario = nuevo
    ctx.usuario_conocido = True
    return True


# =============================================================================
# v2.4: revision del bloque del usuario y alta de usuario (Outlook, carpetas, Vmetrix)
# =============================================================================
#   Al empezar, si en usuarios.json falta algo o no existe (carpeta de descargas, TXT de Vmetrix, buzon o
#   carpeta de Outlook), dice que y deja corregirlo pegando la ruta; lo guarda en usuarios.json.
#   --alta (ALTA_USUARIO_COLATERALES.bat): crea en Outlook la carpeta de los statements y una regla por
#   contraparte (remitentes y asuntos de reportes.json), la carpeta de descargas y el bloque del usuario.

CARPETA_OUTLOOK_DEFECTO = ["{BANDEJA_DE_ENTRADA}", "Colaterales", "Statement"]
LARGO_MAX_DESCARGAS = 110
ETIQUETA_USUARIO = {"carpeta_descargas": "Carpeta de descargas", "credenciales_vmetrix": "TXT de Vmetrix",
                    "buzon": "Buzon de Outlook", "carpetas_outlook": "Carpeta de Outlook"}


def _expandir(texto, login, base=None):
    t = str(texto or "").replace("{USUARIO}", login)
    if base is not None:
        t = t.replace("{BASE}", str(base))
    if os.sep == "/":
        t = t.replace("\\", "/")        # solo para pruebas fuera de Windows
    return Path(os.path.expandvars(os.path.expanduser(t)))


def _ruta_pegada(texto):
    return str(texto or "").strip().strip('"').strip("'").strip()


def _onedrive():
    return next((p for p in sorted(Path.home().glob("OneDrive - *")) if p.is_dir()), None)


def _de_otro_usuario(p, login):
    """'C:\\Users\\p669213\\...' en el PC de otra persona: la ruta es de otro usuario."""
    partes = [x.lower() for x in Path(p).parts]
    if "users" in partes:
        k = partes.index("users")
        if k + 1 < len(partes) and partes[k + 1] not in (login.lower(), "public", "default"):
            return Path(p).parts[k + 1]
    return None


def _ruta_outlook_txt(ruta):
    return " > ".join("Bandeja de entrada" if x.upper() == "{BANDEJA_DE_ENTRADA}" else x for x in (ruta or []))


def problema_descargas(texto, login, base):
    """Que le falta a carpeta_descargas (texto) o None si sirve. Si no existe, intenta crearla."""
    if not texto:
        return "no esta configurada"
    p = _expandir(texto, login, base)
    if not p.is_absolute():
        p = Path(base) / p
    if len(str(p)) > LARGO_MAX_DESCARGAS:
        return "%s es muy larga (%d caracteres; maximo %d, Excel no abre rutas largas)" % (
            p, len(str(p)), LARGO_MAX_DESCARGAS)
    otro = _de_otro_usuario(p, login)
    if otro and not p.is_dir():
        return "%s es de otro usuario (%s)" % (p, otro)
    try:
        ruta_larga(p).mkdir(parents=True, exist_ok=True)
    except OSError as e:
        return "%s no existe y no la pude crear (%s)" % (p, e)
    return None


def problema_credenciales(texto, login):
    if not texto:
        return "no esta configurado el TXT con tu usuario y clave de Vmetrix (sin el no se parea con Vmetrix)"
    p = _expandir(texto, login)
    otro = _de_otro_usuario(p, login)
    if not p.is_file():
        return "no existe %s%s" % (p, " (es de otro usuario: %s)" % otro if otro else "")
    try:
        datos = {}
        for linea in p.read_text(encoding="utf-8-sig", errors="replace").splitlines():
            if "=" in linea:
                k, v = linea.split("=", 1)
                datos[k.strip().upper()] = v.strip()
    except OSError as e:
        return "no pude leer %s (%s)" % (p, e)
    if not datos.get("LOGIN") or not (datos.get("PASS") or datos.get("PASSWORD")):
        return "%s debe tener dos lineas: LOGIN=tu_usuario y PASS=tu_clave" % p.name
    return None


def problemas_outlook(usuario, ol):
    probs = []
    buzon = usuario.get("buzon")
    nombres = ol.buzones()
    if buzon and str(buzon).strip().lower() not in [n.strip().lower() for n in nombres]:
        probs.append(("buzon", "el buzon '%s' no esta en tu Outlook (tienes: %s)" % (buzon, ", ".join(nombres))))
        buzon = None
    for ruta in usuario.get("carpetas_outlook") or []:
        if not ruta or [x.upper() for x in ruta] == ["{BANDEJA_DE_ENTRADA}"]:
            continue
        if ol.carpeta_exacta(buzon, ruta) is None:
            probs.append(("carpetas_outlook", "no existe la carpeta de Outlook '%s'" % _ruta_outlook_txt(ruta)))
        break
    return probs


def guardar_bloque_usuario(dir_json, login, nuevo, base):
    """Guarda el bloque del usuario en el usuarios.json compartido (releyendolo y con respaldo)."""
    ruta = dir_json / "usuarios.json"
    nuevo = dict(nuevo, carpeta_compartida=str(base), actualizado=dt.datetime.now().strftime("%Y-%m-%d %H:%M"))
    try:
        datos = cargar_json(ruta) if ruta.is_file() else {"usuarios": {}}
        datos.setdefault("usuarios", {})
        for k in [k for k in datos["usuarios"] if k.lower() == login]:
            del datos["usuarios"][k]
        datos["usuarios"][login] = nuevo
        respaldar(ruta, dir_json / "_respaldos")
        guardar_json(ruta, datos)
        decir("Guardado en %s (respaldo en Json\\_respaldos)." % ruta)
        return nuevo
    except Exception as e:
        decir("No pude guardar en %s (%s). Pidele a quien administra la carpeta que agregue este bloque en"
              " usuarios.json:" % (ruta, e))
        decir(json.dumps({login: nuevo}, ensure_ascii=False, indent=2))
        return nuevo


def pedir_carpeta_descargas(login, actual=None, base=None):
    """Pide (pegando la ruta) la carpeta donde quedan los archivos de cada dia; la crea. None = no cambia."""
    od = _onedrive()
    sugerida = (od / "Colaterales") if od else (Path.home() / "Colaterales")
    if actual and problema_descargas(actual, login, base or Path.home()) is None:
        sugerida = _expandir(actual, login, base)
    print("Pega la ruta de la carpeta donde quieres que queden los archivos de cada dia (01_Originales,")
    print("02_Para_Cargar, 04_Comparaciones...). Ruta corta: Excel no abre rutas de mas de 259 caracteres.")
    for _ in range(3):
        t = _ruta_pegada(preguntar("Carpeta (Enter = %s): " % sugerida, True, ""))
        destino = _expandir(t, login) if t else sugerida
        if t.lower().startswith(("http:", "https:")):
            print("  Esa es una direccion web. Pega la ruta que ves en el Explorador de archivos.")
            continue
        prob = problema_descargas(str(destino), login, base or Path.home())
        if prob:
            print("  " + prob + ". Intenta con otra.")
            continue
        return str(destino)
    return None


def pedir_credenciales_vmetrix(login, actual=None):
    """Pide la ruta del TXT de Vmetrix (LOGIN=... / PASS=...) o lo crea. None = sigue sin pareo."""
    od = _onedrive()
    sugerida = (od or Path.home()) / "Claves TXT" / "Claves Vmetrix.txt"
    existe = problema_credenciales(str(sugerida), login) is None
    print("Archivo con tu usuario y clave de Vmetrix (TXT con dos lineas: LOGIN=tu_usuario y PASS=tu_clave).")
    print("  Pega la ruta del TXT, escribe c para crearlo ahora%s, o n para seguir sin pareo con Vmetrix." %
          (" (Enter = %s)" % sugerida if existe else ""))
    for _ in range(3):
        t = _ruta_pegada(preguntar("TXT de Vmetrix: ", True, "n"))
        if not t:
            if existe:
                return str(sugerida)
            continue
        if t.lower() == "n":
            print("  Sigo sin pareo con Vmetrix (puedes configurarlo despues con ALTA_USUARIO_COLATERALES.bat).")
            return None
        if t.lower() == "c":
            usuario_vm = preguntar("  Usuario de Vmetrix: ", True, "")
            try:
                clave = getpass.getpass("  Clave de Vmetrix (no se ve al escribir): ")
            except Exception:
                clave = preguntar("  Clave de Vmetrix: ", True, "")
            if not usuario_vm or not clave:
                print("  Sin usuario o clave no lo creo.")
                continue
            try:
                sugerida.parent.mkdir(parents=True, exist_ok=True)
                sugerida.write_text("LOGIN=%s\nPASS=%s\n" % (usuario_vm, clave), encoding="utf-8")
            except OSError as e:
                print("  No pude crearlo (%s)." % e)
                continue
            print("  Creado: %s (lo lee solo el script; la clave no queda en los JSON)." % sugerida)
            return str(sugerida)
        p = _expandir(t, login)
        if p.is_dir():
            print("  Eso es una carpeta: pega la ruta del archivo .txt (o c para crearlo).")
            continue
        prob = problema_credenciales(str(p), login)
        if prob:
            print("  " + prob)
            continue
        return str(p)
    return None


def _literal_asunto(patron, minimo=8):
    """Parte fija del comienzo del asunto (patron de reportes.json) para la regla de Outlook."""
    out, i = [], 0
    while i < len(patron or ""):
        ch = patron[i]
        if ch == "\\" and i + 1 < len(patron):
            sig = patron[i + 1]
            if sig.isalnum():
                break                       # \d, \s, \b...: aqui termina la parte fija
            out.append(sig)
            i += 2
            continue
        if ch in ".^$*+?{}[]|()":
            if ch in "*+?{" and out:
                out.pop()                   # el cuantificador afecta al caracter anterior
            break
        out.append(ch)
        i += 1
    texto = "".join(out).strip(" -_,")
    return texto if len(texto) >= minimo else ""


def grupos_reglas_outlook(reportes):
    """[(contraparte, {"direcciones": [...], "asuntos": [...]})] desde reportes.json > correo. Si todos los
    reportes de la contraparte tienen remitente fijo, basta el remitente; si no, dominio + asunto."""
    grupos = OrderedDict()
    for rep in reportes:
        corr = rep.get("correo") or {}
        if not corr:
            continue
        g = grupos.setdefault(rep.get("contraparte") or rep["id"],
                              {"remitentes": [], "dominios": [], "asuntos": [], "sin_remitente": False})
        rem = [str(x).strip().lower() for x in corr.get("remitentes", []) if x]
        if not rem:
            g["sin_remitente"] = True
        for x in rem:
            if x not in g["remitentes"]:
                g["remitentes"].append(x)
        for d in corr.get("dominios", []):
            d = "@" + str(d).strip().lower().lstrip("@")
            if d not in g["dominios"]:
                g["dominios"].append(d)
        lit = _literal_asunto(corr.get("asunto", ""))
        if lit and lit not in g["asuntos"]:
            g["asuntos"].append(lit)
    salida = []
    for nombre, g in grupos.items():
        if g["remitentes"] and not g["sin_remitente"]:
            salida.append((nombre, {"direcciones": g["remitentes"], "asuntos": []}))
        elif g["dominios"] or g["remitentes"]:
            salida.append((nombre, {"direcciones": g["remitentes"] + g["dominios"], "asuntos": g["asuntos"]}))
    return salida


def configurar_outlook(reportes, conf, buzon, rutas_actuales, ol):
    """Crea (si no existe) la carpeta de Outlook de los statements y una regla por contraparte que mueve ahi
    sus correos. Devuelve carpetas_outlook para usuarios.json."""
    conf_alta = conf.get("alta_usuario") or {}
    defecto = next((r for r in (rutas_actuales or []) if r and [x.upper() for x in r] != ["{BANDEJA_DE_ENTRADA}"]),
                   None) or conf_alta.get("carpeta_outlook") or CARPETA_OUTLOOK_DEFECTO
    print("")
    print("Carpeta de Outlook donde quedan los statements (se crea si no existe).")
    print("Escribela separada con >, ej: Bandeja de entrada > Colaterales > Statement")
    t = preguntar("Carpeta (Enter = %s): " % _ruta_outlook_txt(defecto), True, "")
    ruta = _ruta_outlook_de_texto(t) if t else list(defecto)
    carpeta = ol.carpeta_exacta(buzon, ruta, crear=True)
    if carpeta is None:
        raise RuntimeError("no pude crear la carpeta '%s'" % _ruta_outlook_txt(ruta))
    decir("  Carpeta de Outlook lista: %s" % carpeta.FolderPath)
    grupos = grupos_reglas_outlook(reportes)
    prefijo = conf_alta.get("prefijo_reglas", "Colaterales - ")
    print("")
    print("Reglas de Outlook (una por contraparte; mueven sus correos a esa carpeta):")
    for nombre, g in grupos:
        print("  %s%s" % (prefijo, nombre))
        print("      remitente contiene: %s" % ", ".join(g["direcciones"]))
        if g["asuntos"]:
            print("      y asunto contiene: %s" % " | ".join(g["asuntos"]))
    if preguntar("Crear estas %d reglas? Si ya existen con ese nombre se reemplazan (s/n): " % len(grupos),
                 True, "s").lower().startswith("s"):
        mover = preguntar("Mover tambien los statements que ya estan en la Bandeja de entrada? (s/n): ",
                          True, "s").lower().startswith("s")
        creadas, errores = ol.crear_reglas(buzon, carpeta, grupos, prefijo, mover)
        if creadas:
            decir("  Reglas creadas: %d (Outlook > Reglas > Administrar reglas y alertas)." % len(creadas))
        for e in errores:
            decir("  Aviso: %s" % e)
        if errores and not creadas:
            decir("  Crealas a mano en Outlook (Reglas > Crear regla > remitente contiene...) con los datos de arriba.")
    return [ruta, ["{BANDEJA_DE_ENTRADA}"]]


def validar_usuario(ctx):
    """Al empezar: revisa el bloque del usuario en usuarios.json. Si algo falta o no existe, dice que y deja
    corregirlo (pegando la ruta o creando la carpeta y reglas de Outlook). Lo guarda en usuarios.json."""
    if not ctx.usuario_conocido:
        return
    u = dict(ctx.usuario or {})
    probs = []
    p = problema_descargas(u.get("carpeta_descargas"), ctx.login, ctx.base)
    if p:
        probs.append(("carpeta_descargas", p))
    conf_vm = ctx.conf.get("vmetrix") or {}
    if conf_vm.get("activo", True) and not getattr(ctx.args, "sin_vmetrix", False) and not getattr(ctx.args, "cartera", None):
        p = problema_credenciales(u.get("credenciales_vmetrix") or conf_vm.get("archivo_credenciales"), ctx.login)
        if p:
            probs.append(("credenciales_vmetrix", p))
    ol = None
    if not getattr(ctx.args, "sin_outlook", False) and not getattr(ctx.args, "plan_b", False):
        try:
            ol = Outlook()
            probs += problemas_outlook(u, ol)
        except Exception as e:
            LOG.warning("Revision de Outlook: %s", e)
    if not probs:
        return
    decir("")
    decir("=" * 78)
    decir("REVISION DE TU CONFIGURACION (Json\\usuarios.json, usuario %s)" % ctx.login)
    for clave, texto in probs:
        decir("  - %s: %s" % (ETIQUETA_USUARIO[clave], texto))
    decir("=" * 78)
    cambios = False
    for clave, texto in probs:
        print("")
        print("%s: %s" % (ETIQUETA_USUARIO[clave], texto))
        if clave == "carpeta_descargas":
            nueva = pedir_carpeta_descargas(ctx.login, None, ctx.base)
            if nueva:
                u[clave], cambios = nueva, True
        elif clave == "credenciales_vmetrix":
            nueva = pedir_credenciales_vmetrix(ctx.login, u.get(clave))
            if nueva:
                u[clave], cambios = nueva, True
        elif clave == "buzon" and ol is not None:
            nombres = ol.buzones()
            k = _elegir("En que buzon de Outlook llegan los statements?", nombres + ["Mi buzon predeterminado"])
            if k is not None:
                u["buzon"], cambios = (None if k >= len(nombres) else nombres[k]), True
        elif clave == "carpetas_outlook" and ol is not None:
            k = _elegir("Que hago?", ["Crear la carpeta y las reglas por contraparte en Outlook",
                                      "Escribir la carpeta de Outlook donde te llegan los statements",
                                      "Seguir igual (los busca en la Bandeja de entrada)"], 1)
            if k == 0:
                try:
                    u["carpetas_outlook"], cambios = configurar_outlook(ctx.reportes, ctx.conf, u.get("buzon"),
                                                                        u.get("carpetas_outlook"), ol), True
                except Exception as e:
                    decir("  No pude configurar Outlook (%s)." % e)
            elif k == 1:
                for _ in range(3):
                    t = preguntar("Carpeta (ej. Bandeja de entrada > Colaterales > Statement): ", True, "")
                    if not t:
                        break
                    ruta = _ruta_outlook_de_texto(t)
                    if ol.carpeta_exacta(u.get("buzon"), ruta) is not None:
                        u["carpetas_outlook"], cambios = [ruta, ["{BANDEJA_DE_ENTRADA}"]], True
                        break
                    print("  No encontre esa carpeta en Outlook. Revisa el nombre e intenta de nuevo.")
    if cambios:
        nuevo = guardar_bloque_usuario(ctx.dir_json, ctx.login, u, ctx.base)
        ctx.usuarios.setdefault("usuarios", {})[ctx.login] = nuevo
        ctx.usuario = nuevo
    else:
        decir("Sigo con lo que hay en usuarios.json.")


def modo_alta(args):
    """--alta: deja listo a un usuario nuevo (o revisa el actual): Outlook, carpeta de descargas, Vmetrix y
    usuarios.json. No cambia la script ni los demas JSON."""
    print("=" * 78)
    print("ALTA DE USUARIO - COLATERALES v%s" % VERSION)
    print("=" * 78)
    base, origen = ubicar_carpeta_base(args.base, True)
    dir_json = carpeta_json_de(base)
    avisos = []
    conf = dict(CONFIGURACION_POR_DEFECTO)
    conf.update(cargar_json_opcional(dir_json / "configuracion.json", {}, avisos))
    usuarios = cargar_json_opcional(dir_json / "usuarios.json", {"usuarios": {}}, avisos)
    reportes = [r for r in cargar_json(dir_json / "reportes.json").get("reportes", []) if r.get("activo", True)]
    login = getpass.getuser().lower()
    previo = next((v for k, v in usuarios.get("usuarios", {}).items() if k.lower() == login), None)
    print("Usuario de Windows: %s" % login)
    print("JSON: %s (%s)" % (dir_json, origen))
    if previo:
        print("Ya estas en usuarios.json; revisamos y completamos tus datos:")
        for k in ("nombre", "buzon", "carpetas_outlook", "carpeta_descargas", "credenciales_vmetrix"):
            v = previo.get(k)
            if k == "carpetas_outlook":
                v = " | ".join(_ruta_outlook_txt(r) for r in (v or []))
            print("  %-22s %s" % (k, v if v not in (None, "") else "(falta)"))
    u = dict(previo or {})
    print("")
    u["nombre"] = preguntar("Tu nombre (Enter = %s): " % (u.get("nombre") or login), True, "") or u.get("nombre") or login
    # 1) Outlook
    print("")
    print("1) OUTLOOK")
    ol = None
    try:
        ol = Outlook()
    except Exception as e:
        print("  No pude abrir Outlook (%s). Abre Outlook y vuelve a ejecutar el alta; sigo con lo demas." % e)
    if ol is not None:
        nombres = ol.buzones()
        defecto = next((k + 1 for k, n in enumerate(nombres) if u.get("buzon") and
                        n.strip().lower() == str(u["buzon"]).strip().lower()), len(nombres) + 1)
        k = _elegir("En que buzon de Outlook llegan los statements?", nombres + ["Mi buzon predeterminado"], defecto)
        if k is not None:
            u["buzon"] = None if k >= len(nombres) else nombres[k]
        try:
            u["carpetas_outlook"] = configurar_outlook(reportes, conf, u.get("buzon"), u.get("carpetas_outlook"), ol)
        except Exception as e:
            print("  No pude crear la carpeta o las reglas (%s)." % e)
            u.setdefault("carpetas_outlook", [list(CARPETA_OUTLOOK_DEFECTO), ["{BANDEJA_DE_ENTRADA}"]])
    else:
        u.setdefault("buzon", None)
        u.setdefault("carpetas_outlook", [list(CARPETA_OUTLOOK_DEFECTO), ["{BANDEJA_DE_ENTRADA}"]])
    # 2) Carpeta de descargas
    print("")
    print("2) CARPETA DE DESCARGAS")
    nueva = pedir_carpeta_descargas(login, u.get("carpeta_descargas"), base)
    if nueva:
        u["carpeta_descargas"] = nueva
    # 3) Vmetrix
    print("")
    print("3) VMETRIX (pareo con la cartera)")
    actual = u.get("credenciales_vmetrix")
    if actual and problema_credenciales(actual, login) is None:
        print("  Tu TXT de Vmetrix esta bien: %s" % actual)
    else:
        if actual:
            print("  " + problema_credenciales(actual, login))
        cred = pedir_credenciales_vmetrix(login, actual)
        if cred:
            u["credenciales_vmetrix"] = cred
    # 4) Guardar
    print("")
    print("4) GUARDAR")
    u = guardar_bloque_usuario(dir_json, login, u, base)
    print("")
    print("LISTO. Resumen de %s:" % login)
    for k in ("nombre", "buzon", "carpetas_outlook", "carpeta_descargas", "credenciales_vmetrix"):
        v = u.get(k)
        if k == "carpetas_outlook":
            v = " | ".join(_ruta_outlook_txt(r) for r in (v or []))
        print("  %-22s %s" % (k, v if v not in (None, "") else "(no configurado)"))
    print("")
    print("Ahora ejecuta EJECUTAR_COLATERALES.bat. Si el aplicativo deja contratos sin valor_banco, descarga las")
    print("Comparaciones en la carpeta del dia\\04_Comparaciones y ejecuta PLAN_B_COMPARACIONES.bat.")
    return 0


def _avisar_json_local(ctx):
    """Los JSON se leen de la carpeta compartida. Si junto al script hay otra carpeta Json, avisa que no
    se usa; si se uso una copia local porque no hay compartida, avisa que puede no estar vigente."""
    try:
        if ctx.origen_base.startswith("COPIA LOCAL"):
            decir("ATENCION: no encontre la carpeta compartida y uso los JSON de tu carpeta (%s). Pueden no ser los "
                  "vigentes: sincroniza la carpeta compartida para usar los de todos." % ctx.dir_json)
            return
        aqui = Path(__file__).resolve().parent
        for c in (aqui, aqui.parent):
            local = carpeta_json_de(c)
            if (local / "reportes.json").is_file() and local.resolve() != ctx.dir_json.resolve():
                decir("Nota: %s tiene una copia de los JSON que no se usa; se leen los de la carpeta compartida."
                      % local)
                return
    except OSError:
        pass


def cargar_json(ruta):
    try:
        with open(ruta, "r", encoding="utf-8-sig") as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        raise SystemExit(
            "El archivo %s tiene un error de formato en la linea %d, columna %d: %s\n"
            "Revisa comas, comillas y llaves cerca de esa linea." % (ruta.name, e.lineno, e.colno, e.msg)
        )


