class Correo:
    def __init__(self, item, recibido, remitentes, asunto, adjuntos):
        self.item = item
        self.recibido = recibido
        self.remitentes = remitentes
        self.asunto = asunto
        self.adjuntos = adjuntos      # lista de (indice, nombre)

    def html(self):
        """Cuerpo HTML del correo ('' si Outlook no lo entrega)."""
        try:
            return str(self.item.HTMLBody or "")
        except Exception as e:
            LOG.warning("No pude leer el HTML de '%s': %s", self.asunto[:80], e)
            return ""

    @property
    def remitente_principal(self):
        con_arroba = sorted(r for r in self.remitentes if "@" in r)
        return con_arroba[0] if con_arroba else (sorted(self.remitentes)[0] if self.remitentes else "?")

    def identificacion(self):
        """Datos para volver a encontrar este correo y responderle (bot_faltantes.py)."""
        datos = {"recibido": self.recibido.isoformat(timespec="seconds"), "asunto": self.asunto,
                 "remitentes": sorted(self.remitentes), "para": [], "cc": [], "responder_a": []}
        for clave, leer in (("entry_id", lambda: self.item.EntryID), ("store_id", lambda: self.item.Parent.StoreID),
                            ("conversacion", lambda: self.item.ConversationID)):
            try:
                datos[clave] = str(leer())
            except Exception:
                datos[clave] = ""
        try:
            for i in range(1, self.item.Recipients.Count + 1):
                r = self.item.Recipients.Item(i)
                d = _smtp_destinatario(r)
                if d:
                    datos["cc" if int(r.Type) == 2 else "para"].append(d)
        except Exception:
            pass
        try:
            for i in range(1, self.item.ReplyRecipients.Count + 1):
                d = _smtp_destinatario(self.item.ReplyRecipients.Item(i))
                if d:
                    datos["responder_a"].append(d)
        except Exception:
            pass
        return datos

    def guardar_adjunto(self, indice, destino):
        """Outlook no acepta rutas largas: guarda en una carpeta temporal corta y luego mueve."""
        tmp_dir = carpeta_temporal()
        tmp = tmp_dir / ("adjunto" + Path(destino).suffix)
        self.item.Attachments.Item(indice).SaveAsFile(str(tmp))
        shutil.move(str(tmp), str(destino))
        try:
            tmp_dir.rmdir()
        except OSError:
            pass


PR_SMTP_REPRESENTANTE = "http://schemas.microsoft.com/mapi/proptag/0x5D02001F"
PR_SMTP_ADDRESS = "http://schemas.microsoft.com/mapi/proptag/0x39FE001E"


def _smtp_destinatario(r):
    """Direccion SMTP de un destinatario de Outlook (las internas vienen como /o=ExchangeLabs/...)."""
    for leer in (lambda: r.PropertyAccessor.GetProperty(PR_SMTP_ADDRESS),
                 lambda: r.AddressEntry.GetExchangeUser().PrimarySmtpAddress,
                 lambda: r.Address):
        try:
            d = str(leer() or "").strip().lower()
        except Exception:
            continue
        if "@" in d:
            return d
    return ""
PR_SMTP_REMITENTE = "http://schemas.microsoft.com/mapi/proptag/0x5D01001F"


class Outlook:
    def __init__(self):
        import win32com.client
        self.app = win32com.client.Dispatch("Outlook.Application")
        self.ns = self.app.GetNamespace("MAPI")
        self._avisados = set()

    def _subcarpeta(self, padre, nombre):
        for i in range(1, padre.Folders.Count + 1):
            f = padre.Folders.Item(i)
            if f.Name.strip().lower() == nombre.strip().lower():
                return f
        return None

    def _buscar_recursivo(self, padre, nombre, profundidad=5):
        if profundidad < 0:
            return None
        directa = self._subcarpeta(padre, nombre)
        if directa is not None:
            return directa
        for i in range(1, padre.Folders.Count + 1):
            r = self._buscar_recursivo(padre.Folders.Item(i), nombre, profundidad - 1)
            if r is not None:
                return r
        return None

    def carpeta(self, buzon, ruta):
        """ruta: lista de nombres. '{BANDEJA_DE_ENTRADA}' = bandeja de entrada del buzon
        (sirve en Outlook en espanol o en ingles)."""
        if buzon:
            raiz = None
            for i in range(1, self.ns.Folders.Count + 1):
                f = self.ns.Folders.Item(i)
                if f.Name.strip().lower() == buzon.strip().lower():
                    raiz = f
                    break
            if raiz is None:
                # Usuario nuevo con el buzon mal escrito en usuarios.json: se usa su buzon predeterminado
                if buzon not in self._avisados:
                    self._avisados.add(buzon)
                    nombres = [self.ns.Folders.Item(i).Name for i in range(1, self.ns.Folders.Count + 1)]
                    decir("  Aviso: no encontre el buzon '%s' en Outlook (hay: %s). Uso tu buzon predeterminado; "
                          "corrige 'buzon' en Json\\usuarios.json." % (buzon, ", ".join(nombres)))
                buzon = None
        if buzon and raiz is not None:
            try:
                bandeja = raiz.Store.GetDefaultFolder(6)
            except Exception:
                bandeja = self._subcarpeta(raiz, "Bandeja de entrada") or self._subcarpeta(raiz, "Inbox")
        else:
            bandeja = self.ns.GetDefaultFolder(6)
            raiz = bandeja.Parent
        actual = None
        for k, nombre in enumerate(ruta):
            if k == 0 and nombre.strip().upper() in ("{BANDEJA_DE_ENTRADA}", "{INBOX}"):
                actual = bandeja
                continue
            base = raiz if k == 0 else actual
            siguiente = self._subcarpeta(base, nombre) if base is not None else None
            if siguiente is None:
                siguiente = self._buscar_recursivo(raiz, ruta[-1])
                if siguiente is not None:
                    decir("  Aviso: no encontre la ruta %s; uso la carpeta '%s' encontrada en el buzon."
                          % (" > ".join(ruta), siguiente.FolderPath))
                return siguiente
            actual = siguiente
        return actual

    # ------------------------------------------------------------------ v2.4: alta y validacion de usuario
    def buzones(self):
        return [self.ns.Folders.Item(i).Name for i in range(1, self.ns.Folders.Count + 1)]

    def raiz_y_bandeja(self, buzon):
        """(carpeta raiz, bandeja de entrada, encontrado) del buzon (None = el predeterminado)."""
        if buzon:
            for i in range(1, self.ns.Folders.Count + 1):
                f = self.ns.Folders.Item(i)
                if f.Name.strip().lower() == str(buzon).strip().lower():
                    try:
                        bandeja = f.Store.GetDefaultFolder(6)
                    except Exception:
                        bandeja = self._subcarpeta(f, "Bandeja de entrada") or self._subcarpeta(f, "Inbox")
                    return f, bandeja, True
        bandeja = self.ns.GetDefaultFolder(6)
        return bandeja.Parent, bandeja, not buzon

    def carpeta_exacta(self, buzon, ruta, crear=False):
        """La carpeta de esa ruta exacta (sin buscarla en otro lado). crear=True crea las que falten."""
        raiz, bandeja, _ = self.raiz_y_bandeja(buzon)
        actual = None
        for k, nombre in enumerate(ruta):
            if k == 0 and nombre.strip().upper() in ("{BANDEJA_DE_ENTRADA}", "{INBOX}"):
                actual = bandeja
                continue
            padre = raiz if k == 0 else actual
            if padre is None:
                return None
            sig = self._subcarpeta(padre, nombre)
            if sig is None:
                if not crear:
                    return None
                sig = padre.Folders.Add(nombre)
            actual = sig
        return actual

    def crear_reglas(self, buzon, destino, grupos, prefijo, mover_ahora=False):
        """Una regla de Outlook por contraparte: si el remitente (y el asunto, cuando no hay remitente fijo)
        calza, mueve el correo a 'destino'. Reemplaza las reglas con el mismo nombre.
        Devuelve (creadas, errores)."""
        raiz, bandeja, _ = self.raiz_y_bandeja(buzon)
        reglas = bandeja.Store.GetRules()
        nombres = {reglas.Item(i).Name: i for i in range(1, reglas.Count + 1)}
        creadas, errores, nuevas = [], [], []
        for nombre, g in grupos:
            nombre_regla = (prefijo + nombre)[:60]
            try:
                if nombre_regla in nombres:
                    reglas.Remove(nombre_regla)
                regla = reglas.Create(nombre_regla, 0)          # 0 = olRuleReceive
                cond = regla.Conditions.SenderAddress
                cond.Address = list(g["direcciones"])
                cond.Enabled = True
                if g.get("asuntos"):
                    cs = regla.Conditions.Subject
                    cs.Text = list(g["asuntos"])
                    cs.Enabled = True
                mover = regla.Actions.MoveToFolder
                mover.Folder = destino
                mover.Enabled = True
                regla.Enabled = True
                creadas.append(nombre_regla)
                nuevas.append(regla)
            except Exception as e:
                errores.append("%s: %s" % (nombre_regla, e))
        if creadas:
            try:
                reglas.Save(False)
            except Exception as e:
                return [], errores + ["no pude guardar las reglas en Outlook: %s" % e]
        if mover_ahora:
            for regla in nuevas:
                try:
                    regla.Execute(False, bandeja, False, 0)    # 0 = olRuleExecuteAllMessages
                except Exception as e:
                    errores.append("no pude aplicar %s a la Bandeja de entrada: %s" % (regla.Name, e))
        return creadas, errores


    @staticmethod
    def _remitentes(item):
        dirs = set()
        for obtener in (
            lambda: item.SenderEmailAddress,
            lambda: item.Sender.GetExchangeUser().PrimarySmtpAddress,
            lambda: item.PropertyAccessor.GetProperty(PR_SMTP_REMITENTE),
            lambda: item.PropertyAccessor.GetProperty(PR_SMTP_REPRESENTANTE),
            lambda: item.SentOnBehalfOfName,
            lambda: item.SenderName,
        ):
            try:
                v = obtener()
                if v:
                    dirs.add(str(v).strip().lower())
            except Exception:
                pass
        return dirs

    def correos(self, carpeta, desde, hasta):
        """Recorre la carpeta del mas nuevo al mas antiguo y para al salir de la ventana."""
        items = carpeta.Items
        items.Sort("[ReceivedTime]", True)
        item = items.GetFirst()
        while item is not None:
            try:
                if int(item.Class) == 43:          # 43 = MailItem
                    r = item.ReceivedTime
                    recibido = dt.datetime(r.year, r.month, r.day, r.hour, r.minute, r.second)
                    if recibido < desde:
                        break
                    if recibido <= hasta:
                        adjuntos = []
                        try:
                            for i in range(1, item.Attachments.Count + 1):
                                adjuntos.append((i, str(item.Attachments.Item(i).FileName)))
                        except Exception:
                            pass
                        yield Correo(item, recibido, self._remitentes(item), str(item.Subject or ""), adjuntos)
            except Exception as e:
                LOG.warning("Correo omitido: %s", e)
            item = items.GetNext()


