class Contexto:
    pass


def preparar_contexto(args):
    ctx = Contexto()
    ctx.args = args
    ctx.base, ctx.origen_base = ubicar_carpeta_base(args.base, not args.sin_pausa)
    carpeta_json = ctx.dir_json = carpeta_json_de(ctx.base)
    ctx.avisos_json = []
    ctx.conf = dict(CONFIGURACION_POR_DEFECTO)
    ctx.conf.update(cargar_json_opcional(carpeta_json / "configuracion.json", {}, ctx.avisos_json))
    ctx.usuarios = cargar_json_opcional(carpeta_json / "usuarios.json", {"usuarios": {}}, ctx.avisos_json)
    ctx.reportes = [r for r in cargar_json(carpeta_json / "reportes.json").get("reportes", [])
                    if r.get("activo", True)]
    datos_aj = cargar_json_opcional(carpeta_json / "ajustes_operaciones.json", {"ajustes": []}, ctx.avisos_json)
    ctx.ajustes = [a for a in datos_aj.get("ajustes", []) if isinstance(a, dict) and a.get("operacion")]
    ctx.login = getpass.getuser().lower()
    usuarios = {k.lower(): v for k, v in ctx.usuarios.get("usuarios", {}).items()}
    ctx.usuario = usuarios.get(ctx.login) or ctx.usuarios.get("por_defecto", {})
    ctx.usuario_conocido = ctx.login in usuarios
    if not args.sin_pausa and not getattr(args, "aprender", None):
        registrar_usuario(ctx)
        validar_usuario(ctx)
    ctx.feriados = {fecha_desde_texto(f) for f in ctx.conf.get("feriados", []) if fecha_desde_texto(f)}
    FERIADOS.clear()
    FERIADOS.update(ctx.feriados)
    cargar_sinonimos(ctx.conf)
    ctx.hoy = fecha_desde_texto(args.fecha) if args.fecha else dt.date.today()
    if ctx.hoy is None:
        raise SystemExit("Fecha invalida: %s (usa AAAA-MM-DD)" % args.fecha)
    ctx.cobs = fechas_cob_validas(ctx.hoy, ctx.feriados)
    carpetas = ctx.conf.get("carpetas", {})
    raiz_dia, ctx.origen_descargas = resolver_carpeta_descargas(ctx, args)
    ctx.raiz_descargas = ruta_larga(raiz_dia.resolve())
    sub = ctx.conf.get("subcarpetas_dia", {})
    ctx.dia = ctx.raiz_descargas / ctx.hoy.strftime("%Y-%m-%d")
    ctx.dir_orig = ctx.dia / sub.get("originales", "01_Originales")
    ctx.dir_cargar = ctx.dia / sub.get("para_cargar", "02_Para_Cargar")
    ctx.dir_revisar = ctx.dia / sub.get("revisar", "03_Revisar")
    ctx.dir_comp = ctx.dia / sub.get("comparaciones", "04_Comparaciones")
    ctx.plan_b = bool(getattr(args, "plan_b", False))
    ctx.dir_logs = ctx.base / carpetas.get("logs", "Logs")
    ctx.interactivo = not args.sin_pausa
    ctx.excel = ExcelCOM()
    ctx.no_usados = []
    ctx.hechos = set()        # ranuras preparadas en ESTA ejecucion
    ctx.preparados_ahora = 0  # archivos que esta ejecucion genero en 02_Para_Cargar (no los de antes)
    ctx.forzar = set()        # ranuras que hay que volver a preparar (llego el Excel que reemplaza al armado)
    ctx.pareo = None          # cartera de Vmetrix y resultado del pareo (cargar_cartera_vmetrix)
    ctx.resumen_ajustes = {}
    return ctx


def resolver_carpeta_descargas(ctx, args):
    """Carpeta donde se crean las carpetas de cada dia. Por defecto Colaterales\\Descargas;
    cada usuario puede definir la suya en usuarios.json ("carpeta_descargas")."""
    carpetas = ctx.conf.get("carpetas", {})
    defecto = Path.home() / "Colaterales"      # ruta corta: Excel no abre rutas de mas de 259 caracteres
    if args.prueba:
        raiz, _ = resolver_carpeta_descargas(ctx, argparse.Namespace(**dict(vars(args), prueba=False)))
        return raiz / carpetas.get("pruebas", "Pruebas"), "modo prueba"
    texto = (ctx.usuario or {}).get("carpeta_descargas")
    if not texto:
        return defecto, "por defecto"
    t = str(texto).replace("{BASE}", str(ctx.base)).replace("{USUARIO}", ctx.login)
    if os.sep == "/":
        t = t.replace("\\", "/")      # solo para pruebas fuera de Windows
    p = Path(os.path.expandvars(os.path.expanduser(t)))
    if not p.is_absolute():
        p = ctx.base / p
    try:
        ruta_larga(p).mkdir(parents=True, exist_ok=True)
        return p, "usuarios.json"
    except Exception as e:
        decir("Aviso: no pude usar la carpeta_descargas de usuarios.json (%s): %s. Uso la carpeta por defecto." % (t, e))
        return defecto, "por defecto (la de usuarios.json fallo)"


LARGO_MAX_RUTA = 259    # Excel y muchos programas de Windows no abren rutas mas largas


def aviso_largo_carpeta(ctx):
    """Antes de empezar: avisa si con esta carpeta de descargas algunos archivos quedaran
    con una ruta que Excel y el aplicativo no pueden abrir."""
    base = len(mostrar(ctx.dir_cargar)) + 1
    largos = [len((r.get("adjunto") or {}).get("ejemplo", "")) for r in ctx.reportes]
    malos = [x for x in largos if base + x > LARGO_MAX_RUTA]
    if not malos:
        return
    decir("")
    decir("ATENCION: la carpeta de descargas es muy larga (%d caracteres hasta 02_Para_Cargar)." % base)
    decir("  %d tipo(s) de archivo quedaran con rutas de hasta %d caracteres. Excel y el aplicativo no abren"
          % (len(malos), base + max(malos)))
    decir("  rutas de mas de %d. Cambia carpeta_descargas en Json\\usuarios.json por una ruta corta," % LARGO_MAX_RUTA)
    decir("  por ejemplo C:\\Users\\%s\\Colaterales (el script sigue igual, solo cambia donde deja los archivos)."
          % ctx.login)


def revisar_largo_rutas(ctx, ranuras):
    """Marca para revisar los archivos de 02_Para_Cargar cuya ruta completa pasa el maximo."""
    for r in ranuras.values():
        if r.salida is None:
            continue
        largo = len(mostrar(r.salida))
        if largo > LARGO_MAX_RUTA:
            msg = ("Ruta de %d caracteres (maximo %d): Excel y el aplicativo no pueden abrirlo. "
                   "Usa una carpeta_descargas mas corta en usuarios.json" % (largo, LARGO_MAX_RUTA))
            if msg not in r.observaciones:
                r.observaciones.append(msg)
            if r.estado in (ESTADO_OK, ESTADO_OBS):
                r.estado = ESTADO_REVISAR


def crear_ranuras(ctx):
    ranuras = {}
    for rep in ctx.reportes:
        for fondo in rep.get("fondos", ["UNICO"]):
            r = Ranura(rep, fondo)
            ranuras[r.clave] = r
    return ranuras


def cargar_manifiesto(ctx):
    ruta = ctx.dia / "manifiesto.json"
    if ruta.exists():
        try:
            return cargar_json(ruta)
        except SystemExit:
            pass
    return {"archivos": {}}


def guardar_manifiesto(ctx, manifiesto):
    try:
        guardar_json(ctx.dia / "manifiesto.json", manifiesto)
    except Exception as e:
        LOG.warning("No se pudo guardar el manifiesto: %s", e)


def asignar_existentes(ctx, ranuras, manifiesto):
    """Reconoce archivos que ya estan en 01_Originales (ejecucion anterior o manual)."""
    if not ctx.dir_orig.exists():
        return
    por_reporte = {r["id"]: r for r in ctx.reportes}
    for ruta in sorted(ctx.dir_orig.iterdir()):
        if not ruta.is_file() or ruta.name.startswith(("~$", ".")) or ruta.suffix == ".descargando":
            continue
        info = manifiesto["archivos"].get(ruta.name)
        problema = ""
        if info and info.get("reporte") in por_reporte:
            clave = (info["reporte"], info.get("fondo"))
            fecha_ok = True
        else:
            rep, fondo, tipo, fecha = identificar_archivo(ctx, ruta.name)
            if rep is None:
                ctx.no_usados.append("%s (no corresponde a ningun reporte)" % ruta.name)
                continue
            clave = (rep["id"], fondo)
            fecha_ok, problema = evaluar_fecha(tipo, fecha, ctx)
        r = ranuras.get(clave)
        if r is None or r.archivo is not None or fecha_ok is False:
            motivo = problema if fecha_ok is False else ("fondo no reconocido" if r is None else "duplicado")
            ctx.no_usados.append("%s (%s)" % (ruta.name, motivo))
            continue
        r.archivo = ruta
        r.estado = ESTADO_OK
        r.origen = (info or {}).get("origen", "ya estaba en 01_Originales")
        r.correo = (info or {}).get("correo", "")
        r.armado_html = r.origen == ORIGEN_HTML
        if r.origen == ORIGEN_CIERRE:
            if info.get("sha1") and sha1_archivo(ruta) != info["sha1"]:
                # Guardaste encima el statement de verdad (mismo nombre): se usa ese y se vuelve a preparar
                info.update({"origen": "manual", "reemplaza_cierre_anterior": info.pop("cierre_anterior", None),
                             "sha1": sha1_archivo(ruta)})
                r.origen = "manual"
                ctx.forzar.add(r.clave)
                r.observaciones.append("Guardaste el statement de hoy encima del armado con el cierre anterior: se "
                                       "usa el tuyo. Si ya cargaste el otro, vuelve a cargar el de 02_Para_Cargar")
                guardar_manifiesto(ctx, manifiesto)
            else:
                r.arrastre = info.get("cierre_anterior") or {}
                r.estado = ESTADO_OBS
                if r.arrastre.get("cob_base"):
                    r.observaciones.append(texto_cierre_anterior(r.arrastre, r.reporte.get("contraparte", "")))


def descargar_de_outlook(ctx, ranuras, manifiesto):
    con_correo = {r["id"] for r in ctx.reportes if r.get("correo")}
    # Si el original se armo con los correos HTML, se sigue buscando el Excel de verdad
    pendientes = [r for r in ranuras.values()
                  if (r.archivo is None or r.armado_html or r.arrastre) and r.reporte["id"] in con_correo]
    manuales_conf = [r for r in ctx.reportes if r.get("origen") == "manual" and r.get("correo")]
    alternas = alternativas_html(ctx, pendientes)
    correos_html = {}
    if not pendientes:
        decir("  Todo lo de Outlook ya estaba descargado.")
        return {}
    try:
        ol = Outlook()
    except Exception as e:
        decir("  No pude conectarme a Outlook (%s). Sigo con lo que haya en las carpetas." % e)
        return {}
    buzon = ctx.usuario.get("buzon")
    rutas = ctx.usuario.get("carpetas_outlook") or [["{BANDEJA_DE_ENTRADA}", "Colaterales", "Statement"]]
    desde = dt.datetime.combine(min(ctx.cobs + [ctx.hoy]), dt.time(0, 0))
    hasta = dt.datetime.combine(ctx.hoy, dt.time(23, 59, 59))
    decir("  Buzon: %s | ventana: %s a %s" % (buzon or "(predeterminado)", desde.strftime("%d-%m %H:%M"),
                                              hasta.strftime("%d-%m %H:%M")))
    vistos = set()
    candidatos = []
    avisos_manuales = {}
    for ruta in rutas:
        try:
            carpeta = ol.carpeta(buzon, ruta)
        except Exception as e:
            decir("  Aviso: %s" % e)
            continue
        if carpeta is None:
            decir("  Aviso: no encontre la carpeta %s" % " > ".join(ruta))
            continue
        n = 0
        try:
            for correo in ol.correos(carpeta, desde, hasta):
                clave = (correo.asunto, correo.recibido, correo.remitente_principal)
                if clave in vistos:
                    continue
                vistos.add(clave)
                n += 1
                try:
                    for rid, fondo_html, fecha_html in evaluar_html(alternas, correo):
                        correos_html.setdefault(rid, []).append((fondo_html, fecha_html, correo))
                    candidatos += evaluar_candidatos(ctx, correo)
                    # Correos de reportes manuales (encriptados): solo se avisa que llegaron
                    for rep in manuales_conf:
                        rx = compilar(rep["correo"].get("asunto"))
                        if rx and rx.search(correo.asunto or ""):
                            avisos_manuales.setdefault(rep["id"], []).append(correo)
                except Exception as e:
                    LOG.warning("No pude evaluar el correo '%s': %s", correo.asunto[:80], e)
        except Exception as e:
            decir("  Aviso: se interrumpio la lectura de %s (%s). Sigo con lo leido." % (" > ".join(ruta), e))
            LOG.error(traceback.format_exc())
        decir("  Carpeta %s: %d correos revisados" % (" > ".join(ruta), n))

    por_ranura = {}
    for c in candidatos:
        por_ranura.setdefault((c.reporte["id"], c.fondo), []).append(c)
    ctx.dir_orig.mkdir(parents=True, exist_ok=True)
    for r in pendientes:
        lista = por_ranura.get(r.clave, [])
        buenos = sorted([c for c in lista if c.clase == ESTADO_OK],
                        key=lambda c: (c.puntaje, c.correo.recibido), reverse=True)
        dudosos = sorted([c for c in lista if c.clase == ESTADO_REVISAR],
                         key=lambda c: (c.puntaje, c.correo.recibido), reverse=True)
        antiguos = [c for c in lista if c.clase == "ANTIGUO"]
        if r.reporte.get("origen") == "manual" and not buenos:
            continue    # lo resuelve el paso de archivos manuales
        if r.armado_html and not buenos:
            decir("  %s: el Excel aun no llega; sigue el armado desde los correos HTML (%s)."
                  % (r.reporte.get("contraparte"), r.archivo.name))
            continue
        if r.arrastre and not buenos:
            decir("  %s: el de hoy aun no llega; sigue el armado con el del cierre anterior (%s)."
                  % (r.reporte.get("contraparte"), r.archivo.name))
            continue
        if buenos:
            c = buenos[0]
            destino = ctx.dir_orig / nombre_seguro(c.nombre_destino or c.adjunto_nombre)
            if r.armado_html:
                armado = apartar_armado_html(ctx, r, manifiesto)
            elif r.arrastre:
                armado = apartar_armado_html(ctx, r, manifiesto, "_cierre_anterior_reemplazado", ORIGEN_CIERRE)
            else:
                armado = None
            try:
                guardar_adjunto_seguro(c, destino, ctx)
            except Exception as e:
                if armado is not None:
                    shutil.move(str(armado), str(r.archivo))    # se deja todo como estaba
                    manifiesto["archivos"][r.archivo.name] = r.info_armado
                    r.observaciones.append("Llego el Excel pero no se pudo guardar (%s); sigue el armado %s"
                                           % (e, "con el cierre anterior" if r.arrastre else "desde HTML"))
                    continue
                r.estado = ESTADO_ERROR
                r.observaciones.append("No se pudo guardar el adjunto: %s" % e)
                continue
            r.archivo = destino
            r.origen = "outlook"
            r.correo = "%s | %s" % (c.correo.recibido.strftime("%d-%m %H:%M"), c.correo.asunto[:120])
            r.estado = ESTADO_OBS if c.problemas else ESTADO_OK
            r.observaciones += c.problemas
            if len(buenos) > 1:
                r.observaciones.append("habia %d correos validos; use el de mayor puntaje/mas reciente" % len(buenos))
            manifiesto["archivos"][destino.name] = {
                "reporte": r.reporte["id"], "fondo": r.fondo, "origen": "outlook", "correo": r.correo,
                "remitente": c.correo.remitente_principal, "descargado": dt.datetime.now().isoformat(timespec="seconds"),
                "sha1": sha1_archivo(destino), "correo_id": c.correo.identificacion()}
            if armado is not None and r.arrastre:
                reemplazo_de_cierre_anterior(ctx, r, armado, destino, manifiesto)
            elif armado is not None:
                reemplazo_de_armado_html(ctx, r, armado, destino, manifiesto)
        elif dudosos:
            r.estado = ESTADO_REVISAR
            ctx.dir_revisar.mkdir(parents=True, exist_ok=True)
            for c in dudosos[:3]:
                destino = ctx.dir_revisar / nombre_seguro(c.adjunto_nombre)
                try:
                    if not destino.exists():
                        c.correo.guardar_adjunto(c.adjunto_idx, destino)
                except Exception as e:
                    LOG.warning("No se pudo guardar candidato: %s", e)
                r.candidatos_revisar.append(c.resumen())
            r.observaciones.append("Hay correos parecidos pero no cumplen todo; quedaron en 03_Revisar")
        elif antiguos:
            ult = max(antiguos, key=lambda c: c.correo.recibido)
            r.observaciones.append("Aun no llega el de hoy; el ultimo es del %s (%s)" % (
                ult.correo.recibido.strftime("%d-%m %H:%M"), ult.adjunto_nombre))
    # Sin Excel: ofrecer armarlo con los correos HTML (hoy solo Scotia)
    for r in pendientes:
        if r.archivo is None and r.reporte["id"] in alternas:
            try:
                ofrecer_armado_html(ctx, r, alternas[r.reporte["id"]], correos_html.get(r.reporte["id"], []), manifiesto)
            except Exception as e:
                r.observaciones.append("No pude armar el Excel desde los correos HTML: %s" % e)
                decir("  Aviso: no pude armar %s desde los correos HTML (%s)." % (r.reporte.get("contraparte"), e))
                LOG.error(traceback.format_exc())
    guardar_manifiesto(ctx, manifiesto)
    return avisos_manuales


def guardar_adjunto_seguro(cand, destino, ctx):
    """Guarda el adjunto. Si ya existe uno distinto con el mismo nombre, lo
    mueve a _reemplazados (dentro de la carpeta del dia) antes de guardar."""
    tmp = destino.with_name(destino.name + ".descargando")
    cand.correo.guardar_adjunto(cand.adjunto_idx, tmp)
    if destino.exists():
        if sha1_archivo(destino) == sha1_archivo(tmp):
            tmp.unlink()
            return
        carpeta = destino.parent / "_reemplazados"
        carpeta.mkdir(exist_ok=True)
        shutil.move(str(destino), str(carpeta / ("%s_%s%s" % (destino.stem, dt.datetime.now().strftime("%H%M%S"), destino.suffix))))
    os.replace(tmp, destino)


# =============================================================================
# Excel armado con los correos HTML (hoy: Scotia, que manda el Excel tarde)
# =============================================================================
# reportes.json > <reporte> > "alternativa_html" dice como reconocer los correos
# (asunto con el fondo y la fecha de cierre), que columnas tomar de la tabla del
# correo y como se llama y se ve el Excel original. El archivo armado queda en
# 01_Originales con el MISMO nombre y formato que el adjunto de la contraparte,
# asi pasa por las mismas reglas y ajustes que el Excel de verdad.

ORIGEN_HTML = "correos HTML"
MESES_EN = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")


class _TablasHTML(HTMLParser):
    """Junta las tablas de un HTML como listas de filas de textos (soporta tablas anidadas
    y celdas sin cierre, como las que deja Outlook)."""

    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.tablas = []
        self._abiertas = []
        self._celda = None

    def _cerrar_celda(self):
        if self._celda is not None and self._abiertas:
            if not self._abiertas[-1]:
                self._abiertas[-1].append([])
            self._abiertas[-1][-1].append(" ".join("".join(self._celda).split()))
        self._celda = None

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            self._cerrar_celda()
            self._abiertas.append([])
        elif tag == "tr" and self._abiertas:
            self._cerrar_celda()
            self._abiertas[-1].append([])
        elif tag in ("td", "th") and self._abiertas:
            self._cerrar_celda()
            self._celda = []
        elif tag == "br" and self._celda is not None:
            self._celda.append(" ")

    def handle_endtag(self, tag):
        if tag in ("td", "th", "tr"):
            self._cerrar_celda()
        elif tag == "table" and self._abiertas:
            self._cerrar_celda()
            self.tablas.append(self._abiertas.pop())

    def handle_data(self, data):
        if self._celda is not None:
            self._celda.append(data)


def tabla_html(html, encabezado):
    """Primera tabla del HTML que tiene una fila con el encabezado indicado.
    Devuelve (encabezados, filas de datos) o (None, None)."""
    p = _TablasHTML()
    p.feed(html or "")
    p.close()
    buscado = normalizar_encabezado(encabezado)
    for tabla in p.tablas:
        for k, fila in enumerate(tabla):
            if any(normalizar_encabezado(c) == buscado for c in fila):
                return fila, [f for f in tabla[k + 1:] if any(c for c in f)]
    return None, None


def numero_html(texto):
    """'3,928,584' -> 3928584 | '-734,400' -> -734400 | '(1,234)' -> -1234 | '3.456000' -> 3.456.
    Si no es numero devuelve el texto tal cual."""
    t = str(texto).replace(",", "").replace(" ", "").replace("\xa0", "")
    negativo = t.startswith("(") and t.endswith(")")
    if negativo:
        t = t[1:-1]
    if not re.fullmatch(r"[-+]?\d+(\.\d+)?", t):
        return texto
    v = float(t) if "." in t else int(t)
    return -v if negativo else v


def fecha_en_texto(f, formato="%b %d %Y"):
    """Fecha con mes en ingles, sin depender del idioma de Windows: %b=Nov %d=03 %-d=3 %m=11 %Y=2026."""
    t = formato.replace("%b", MESES_EN[f.month - 1]).replace("%Y", "%04d" % f.year).replace("%m", "%02d" % f.month)
    return t.replace("%-d", str(f.day)).replace("%d", "%02d" % f.day)


def _con_fecha(texto, cob, conf):
    return str(texto).replace("{cob}", fecha_en_texto(cob, conf.get("formato_cob", "%b %d %Y")))


def alternativas_html(ctx, pendientes):
    """Reportes pendientes que se pueden armar con correos HTML -> {id: configuracion}."""
    salida = {}
    for r in pendientes:
        rep = r.reporte
        conf = rep.get("alternativa_html") or {}
        if not conf or not conf.get("activo", True) or rep["id"] in salida:
            continue
        rx = compilar(conf.get("asunto"))
        if rx is None or not conf.get("columnas") or not conf.get("fondos") or not conf.get("nombre_archivo"):
            decir("  Aviso: %s > alternativa_html esta incompleta en reportes.json (asunto, fondos, columnas,"
                  " nombre_archivo); no se usa." % rep["id"])
            continue
        c = dict(conf)
        c["_rx"] = rx
        dominios = conf.get("dominios") or (rep.get("correo") or {}).get("dominios", [])
        c["_dominios"] = [d.lower().lstrip("@") for d in dominios]
        salida[rep["id"]] = c
    return salida


def evaluar_html(alternas, correo):
    """(reporte, fondo, fecha de cierre) de los correos HTML que calzan."""
    for rid, conf in alternas.items():
        m = conf["_rx"].search(correo.asunto or "")
        if not m:
            continue
        dominios = conf["_dominios"]
        if dominios and not any(d_.endswith("@" + d) or d_.endswith("." + d) for d_ in correo.remitentes for d in dominios):
            continue
        g = m.groupdict()
        fondo = str(g.get("fondo") or "").strip().upper()
        fecha = fecha_desde_texto(g.get("cob"))
        if fondo and fecha:
            yield rid, fondo, fecha


def leer_correos_html(conf, correos, fondos):
    """Lee la tabla de cada correo. Devuelve (filas por fondo, problemas, avisos)."""
    encabezado = conf.get("tabla_encabezado", "Trans ID")
    necesarias = [c["html"] for c in conf["columnas"] if c.get("html")]
    ignorar = {normalizar_encabezado(x) for x in conf.get("ignorar_columnas", [])}
    conocidas = {normalizar_encabezado(x) for x in necesarias} | ignorar
    salida, problemas, avisos = {}, [], []
    for fondo in fondos:
        columnas, filas = tabla_html(correos[fondo].html(), encabezado)
        if columnas is None:
            problemas.append("fondo %s: no encontre la tabla con '%s'" % (fondo, encabezado))
            continue
        idx = {}
        for i, c in enumerate(columnas):
            idx.setdefault(normalizar_encabezado(c), i)
        faltan = [n for n in necesarias if normalizar_encabezado(n) not in idx]
        if faltan:
            problemas.append("fondo %s: el correo no trae la(s) columna(s) %s" % (fondo, ", ".join(faltan)))
            continue
        nuevas = [c for c in columnas if c and normalizar_encabezado(c) not in conocidas]
        if nuevas:
            avisos.append("fondo %s: el correo trae columnas que no estan en alternativa_html (%s), no se incluyen"
                          % (fondo, ", ".join(nuevas)))
        salida[fondo] = []
        for f in filas:
            salida[fondo].append({n: (f[idx[normalizar_encabezado(n)]] if idx[normalizar_encabezado(n)] < len(f) else "")
                                  for n in necesarias})
        if not salida[fondo]:
            avisos.append("fondo %s: el correo no trae operaciones" % fondo)
    return salida, problemas, avisos


def armar_excel_html(conf, filas_por_fondo, cob, destino):
    """Escribe el Excel con el mismo nombre, hoja, titulos, encabezados, columnas y formato del
    original de la contraparte. Los fondos van en el orden de alternativa_html > fondos."""
    import openpyxl
    from openpyxl.styles import Alignment, Font
    from openpyxl.worksheet.properties import PageSetupProperties
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = conf.get("hoja", "Sheet1")
    fuente = conf.get("fuente", "Scotia")
    f_dato = Font(name=fuente, size=10)
    f_enc = Font(name=fuente, size=10, bold=True)
    centro = Alignment(horizontal="center", vertical="center")
    derecha = Alignment(horizontal="right", vertical="center")
    for celda, texto in (conf.get("titulos") or {}).items():
        ws[celda].value = _con_fecha(texto, cob, conf)
        ws[celda].number_format = "#,##0.00"
    for rango in conf.get("combinar", []):
        ws.merge_cells(rango)
        ws[rango.split(":")[0]].alignment = Alignment(horizontal="center")
    fila_enc = int(conf.get("fila_encabezado", 9))
    columnas = conf["columnas"]
    for j, col in enumerate(columnas, start=1):
        c = ws.cell(row=fila_enc, column=j)
        if col.get("encabezado"):
            c.value = col["encabezado"]
        c.font = f_enc
        c.alignment = centro
    nombres = conf["fondos"]
    fila = fila_enc + 1
    for fondo in nombres:
        for datos in filas_por_fondo.get(fondo, []):
            for j, col in enumerate(columnas, start=1):
                tipo = col.get("tipo", "texto")
                c = ws.cell(row=fila, column=j)
                if "valor" in col:
                    v = str(col["valor"]).replace("{fondo}", str(nombres[fondo])).replace("{letra}", fondo)
                else:
                    v = datos.get(col.get("html"), "")
                if tipo == "fondo":
                    c.value = v
                    c.number_format = "#,##0.00"
                    continue
                if v in ("", None):
                    c.alignment = derecha if tipo == "tasa" else centro
                    continue
                if tipo in ("monto", "tasa"):
                    v = numero_html(v)
                c.value = v
                c.font = f_dato
                es_num = isinstance(v, (int, float))
                if tipo == "monto" and es_num:
                    c.number_format = conf.get("formato_monto", "#,##0")
                c.alignment = derecha if tipo in ("monto", "tasa") and es_num else centro
            fila += 1
    for letra, ancho in (conf.get("anchos") or {}).items():
        ws.column_dimensions[letra].width = ancho
    ws.sheet_properties.pageSetUpPr = PageSetupProperties(fitToPage=True)
    ws.page_setup.fitToHeight = 0
    wb.properties.creator = "Colaterales %s" % VERSION
    wb.properties.title = "Armado desde los correos HTML del cierre %s" % cob.strftime("%d-%m-%Y")
    tmp = destino.with_name(destino.name + ".descargando")
    wb.save(str(tmp))
    if destino.exists():
        carpeta = destino.parent / "_reemplazados"
        carpeta.mkdir(exist_ok=True)
        shutil.move(str(destino), str(carpeta / ("%s_%s%s" % (destino.stem, dt.datetime.now().strftime("%H%M%S"),
                                                                destino.suffix))))
    os.replace(tmp, destino)
    return fila - fila_enc - 1


def ofrecer_armado_html(ctx, r, conf, lista, manifiesto):
    """No llego el Excel: si estan los correos HTML de todos los fondos para el cierre esperado,
    pregunta y arma el Excel en 01_Originales."""
    rep = r.reporte
    quien = rep.get("contraparte", rep["id"])
    fondos = list(conf["fondos"].keys())
    por_cob = {}
    for fondo, fecha, correo in lista:
        if fecha in ctx.cobs and fondo in fondos:
            actual = por_cob.setdefault(fecha, {}).get(fondo)
            if actual is None or correo.recibido > actual.recibido:
                por_cob[fecha][fondo] = correo
    if not por_cob:
        return
    completos = [f for f in ctx.cobs if f in por_cob and all(x in por_cob[f] for x in fondos)]
    if not completos:
        cob = next(f for f in ctx.cobs if f in por_cob)
        msg = ("Aun no llega el Excel; de los correos HTML del cierre %s llegaron %s y faltan %s: no se puede armar "
               "completo, vuelve a ejecutar mas tarde" % (cob.strftime("%d-%m-%Y"),
                                                          ", ".join(x for x in fondos if x in por_cob[cob]),
                                                          ", ".join(x for x in fondos if x not in por_cob[cob])))
        decir("  %s: %s." % (quien, msg))
        r.observaciones.append(msg)
        return
    cob = completos[0]
    correos = por_cob[cob]
    filas, problemas, avisos = leer_correos_html(conf, correos, fondos)
    if problemas:
        msg = ("Llegaron los correos HTML del cierre %s pero no los pude leer (%s). No arme el Excel; si %s cambio el "
               "formato del correo, ajusta alternativa_html en reportes.json" % (cob.strftime("%d-%m-%Y"),
                                                                                  "; ".join(problemas[:3]), quien))
        decir("  %s: %s." % (quien, msg))
        r.observaciones.append(msg)
        return
    nombre = nombre_seguro(_con_fecha(conf["nombre_archivo"], cob, conf))
    rep2, _, _, fecha2 = identificar_archivo(ctx, nombre)
    if rep2 is None or rep2["id"] != rep["id"] or fecha2 != cob:
        msg = ("alternativa_html > nombre_archivo arma '%s', que no calza con adjunto > patron de %s; revisa "
               "reportes.json" % (nombre, rep["id"]))
        decir("  Aviso: " + msg)
        r.observaciones.append(msg)
        return
    hora = max(c.recibido for c in correos.values())
    n_filas = sum(len(v) for v in filas.values())
    decir("")
    decir("  %s: aun no llega el Excel del cierre %s, pero ya estan los %d correos HTML (fondos %s;"
          % (quien, cob.strftime("%d-%m-%Y"), len(fondos), ", ".join(fondos)))
    decir("    el ultimo llego el %s; %d filas). Puedo armar el Excel con esos datos, con el mismo nombre y"
          % (hora.strftime("%d-%m %H:%M"), n_filas))
    decir("    formato del original, para cargarlo sin esperar. Si el Excel llega despues, vuelve a ejecutar:")
    decir("    se usa el Excel y te digo si cambio algo.")
    for a in avisos:
        decir("    Ojo: " + a)
    if not conf.get("preguntar", True):
        armar = True
    elif ctx.interactivo:
        armar = not preguntar("  Armar el Excel desde los correos HTML? (S/n): ", True, "s").lower().startswith("n")
    else:
        armar = str(conf.get("en_sin_pausa", "armar")).strip().lower() == "armar"
    if not armar:
        msg = "Llegaron los correos HTML del cierre %s; elegiste esperar el Excel" % cob.strftime("%d-%m-%Y")
        r.observaciones.append(msg)
        decir("  " + msg + ".")
        return
    ctx.dir_orig.mkdir(parents=True, exist_ok=True)
    destino = ctx.dir_orig / nombre
    armar_excel_html(conf, filas, cob, destino)
    r.archivo = destino
    r.armado_html = True
    r.origen = ORIGEN_HTML
    r.correo = "%s | %d correos HTML (fondos %s)" % (hora.strftime("%d-%m %H:%M"), len(correos), ", ".join(fondos))
    r.estado = ESTADO_OBS
    r.observaciones = [o for o in r.observaciones if not o.startswith("Aun no llega el de hoy")]
    r.observaciones.append("Armado desde los %d correos HTML del cierre %s porque aun no llegaba el Excel. Si el Excel "
                           "llega despues, vuelve a ejecutar: se usa el Excel y te digo si cambio algo"
                           % (len(correos), cob.strftime("%d-%m-%Y")))
    r.observaciones += avisos
    manifiesto["archivos"][destino.name] = {
        "reporte": rep["id"], "fondo": r.fondo, "origen": ORIGEN_HTML, "correo": r.correo,
        "armado": dt.datetime.now().isoformat(timespec="seconds"), "sha1": sha1_archivo(destino)}
    decir("  -> Armado: %s (%d filas)" % (destino.name, n_filas))
    LOG.info("[%s] armado desde correos HTML: %s", rep["id"], mostrar(destino))


def apartar_armado_html(ctx, r, manifiesto, subcarpeta="_armado_desde_html", origen=None):
    """Llego el Excel de verdad: el armado (desde HTML o con el cierre anterior) se mueve a
    01_Originales\\_armado_desde_html (o a la subcarpeta indicada)."""
    carpeta = ctx.dir_orig / subcarpeta
    carpeta.mkdir(parents=True, exist_ok=True)
    destino = carpeta / r.archivo.name
    if destino.exists():
        destino = carpeta / ("%s_%s%s" % (r.archivo.stem, dt.datetime.now().strftime("%H%M%S"), r.archivo.suffix))
    r.nombre_armado = r.archivo.name
    r.info_armado = manifiesto["archivos"].pop(r.archivo.name, {"reporte": r.reporte["id"], "fondo": r.fondo,
                                                                 "origen": origen or ORIGEN_HTML})
    shutil.move(str(r.archivo), str(destino))
    return destino


def comparar_contenido(ruta_a, ruta_b):
    """Celdas con distinto valor entre dos archivos (None si no se pudieron leer)."""
    try:
        la, lb = Libro(ruta_a), Libro(ruta_b)
    except Exception as e:
        LOG.warning("No pude comparar %s con %s: %s", ruta_a, ruta_b, e)
        return None
    difs = []
    for k in range(max(len(la.hojas), len(lb.hojas))):
        ha = la.hojas[k] if k < len(la.hojas) else Hoja("", [])
        hb = lb.hojas[k] if k < len(lb.hojas) else Hoja("", [])
        for f in range(max(len(ha.filas), len(hb.filas))):
            ancho = max(len(ha.filas[f]) if f < len(ha.filas) else 0, len(hb.filas[f]) if f < len(hb.filas) else 0)
            for c in range(ancho):
                va, vb = ha.valor(f, c), hb.valor(f, c)
                if not iguales(va, vb):
                    difs.append("%s%d: %s -> %s" % (indice_a_letra(c), f + 1, normalizar(va) or "(vacio)",
                                                     normalizar(vb) or "(vacio)"))
    return difs


def reemplazo_de_armado_html(ctx, r, armado, nuevo, manifiesto):
    """Compara el Excel que llego con el armado y deja 02_Para_Cargar listo para regenerarse."""
    rep = r.reporte
    quien = rep.get("contraparte", rep["id"])
    salida_vieja = ctx.dir_cargar / nombre_de_salida(rep, getattr(r, "nombre_armado", armado.name))
    salida_nueva = ctx.dir_cargar / nombre_de_salida(rep, nuevo.name)
    if salida_vieja.exists() and mostrar(salida_vieja).lower() != mostrar(salida_nueva).lower():
        respaldar(salida_vieja, ctx.dir_cargar / "_respaldo")
        salida_vieja.unlink()
        manifiesto.setdefault("preparados", {}).pop(salida_vieja.name, None)
    ctx.forzar.add(r.clave)            # 02_Para_Cargar se vuelve a preparar con el Excel (respalda el anterior)
    r.armado_html = False
    difs = comparar_contenido(armado, nuevo)
    if difs is None:
        msg = ("Llego el Excel de %s y reemplaza al armado desde los correos HTML (no pude compararlos; si ya "
               "cargaste el armado, vuelve a cargar el de 02_Para_Cargar)" % quien)
        r.estado = ESTADO_REVISAR
    elif not difs:
        msg = ("Llego el Excel de %s y reemplaza al armado desde los correos HTML: los datos son identicos (si ya "
               "cargaste el armado, no hace falta volver a cargarlo)" % quien)
    else:
        msg = ("Llego el Excel de %s y tiene %d diferencia(s) con el armado desde los correos HTML (ej. %s). Si ya "
               "cargaste el armado, vuelve a cargar el de 02_Para_Cargar" % (quien, len(difs), "; ".join(difs[:4])))
        r.estado = ESTADO_REVISAR
        LOG.info("[%s] diferencias Excel vs armado HTML: %s", rep["id"], difs)
    decir("  " + msg + ".")
    r.observaciones.append(msg)
    manifiesto["archivos"].setdefault(nuevo.name, {}).update(
        {"reemplaza_armado_html": mostrar(armado), "diferencias_con_armado": len(difs) if difs is not None else None})


# =============================================================================
# Statement del cierre anterior (la contraparte no envio el de hoy)
# =============================================================================
# Si una contraparte no manda el statement de hoy, se usa el del cierre anterior: lo dejas en
# 01_Originales de hoy (o aceptas cuando el script lo ofrece al final). El script ve por el nombre
# que es de un cierre anterior y arma en 01_Originales el archivo "de hoy": mismo formato, el
# nombre con las fechas de hoy y adentro las fechas del cierre llevadas al cierre de hoy (la fecha
# de valorizacion de cada fila y las del encabezado: "as of", "COB", "Run on", etc.). Las
# operaciones y el MTM quedan tal cual (son los del cierre anterior); despues pasa por las mismas
# reglas, ajustes y pareo que cualquier statement. El archivo que dejaste queda en
# 01_Originales\_base_cierre_anterior. Si mas tarde llega el statement de verdad, lo reemplaza y
# vuelve a preparar 02_Para_Cargar.
#   configuracion.json > cierre_anterior        reportes.json > <reporte> > cierre_anterior

ORIGEN_CIERRE = "cierre anterior"
CARPETA_BASE_CIERRE = "_base_cierre_anterior"
MESES_LARGOS_EN = ("January", "February", "March", "April", "May", "June", "July", "August", "September",
                   "October", "November", "December")
CIERRE_ANTERIOR_POR_DEFECTO = {
    "activo": True,
    "ofrecer": True,
    "dias_atras": 10,
    "dias_atras_max": 31,
    "filas_encabezado": 15,
    "columnas_fecha_cierre": ["Valuation Date", "MtM Validation Date", "Exposure Date", "COB Date", "MtM date COB",
                              "As Of", "As of Date", "Report Date", "Business Date", "Statement Date",
                              "Valuation_Date", "Close of Business Date"],
    "etiquetas_no": ["flow", "trade", "maturity", "value", "settlement", "settle", "payment", "pay", "fixing", "fix",
                     "expiry", "expiration", "effective", "start", "end", "mat", "eff", "vencimiento", "inicio",
                     "pago", "termino"],
}

# Formas en que los bancos escriben una fecha. 'orden' marca las ambiguas (dia/mes o mes/dia).
_FORMAS_FECHA = [
    ("{Y}{mm}{dd}", None), ("{Y}-{mm}-{dd}", None), ("{Y}/{mm}/{dd}", None), ("{Y}_{mm}_{dd}", None),
    ("{dd}/{mm}/{Y}", "dmy"), ("{d}/{m}/{Y}", "dmy"), ("{dd}-{mm}-{Y}", "dmy"), ("{dd}.{mm}.{Y}", "dmy"),
    ("{mm}/{dd}/{Y}", "mdy"), ("{m}/{d}/{Y}", "mdy"), ("{mm}-{dd}-{Y}", "mdy"),
    ("{dd}-{b}-{Y}", None), ("{d}-{b}-{Y}", None), ("{dd}-{b}-{y}", None), ("{dd} {b} {Y}", None),
    ("{d} {b} {Y}", None), ("{dd}{b}{Y}", None), ("{d}{b}{Y}", None), ("{dd}_{b}_{Y}", None), ("{d}_{b}_{Y}", None),
    ("{b} {dd} {Y}", None), ("{b} {d} {Y}", None), ("{b}-{dd}-{Y}", None), ("{b}-{d}-{Y}", None),
    ("{b} {dd}, {Y}", None), ("{b} {d}, {Y}", None),
    ("{dd} {B} {Y}", None), ("{d} {B} {Y}", None), ("{dd}-{B}-{Y}", None), ("{d}-{B}-{Y}", None),
    ("{B} {dd}, {Y}", None), ("{B} {d}, {Y}", None), ("{B} {dd} {Y}", None), ("{B} {d} {Y}", None),
]


def conf_cierre_anterior(ctx, rep=None):
    conf = dict(CIERRE_ANTERIOR_POR_DEFECTO)
    conf.update({k: v for k, v in (ctx.conf.get("cierre_anterior") or {}).items() if not k.startswith("_")})
    if rep is not None:
        conf.update({k: v for k, v in (rep.get("cierre_anterior") or {}).items() if not k.startswith("_")})
    return conf


def _forma_fecha(plantilla, d):
    return plantilla.format(Y="%04d" % d.year, y="%02d" % (d.year % 100), mm="%02d" % d.month, m=str(d.month),
                            dd="%02d" % d.day, d=str(d.day), b=MESES_EN[d.month - 1], B=MESES_LARGOS_EN[d.month - 1])


def _buscar_fechas(texto, mapa, orden=None):
    """[(inicio, fin, texto_nuevo)] de cada fecha de 'mapa' {vieja: nueva} escrita en 'texto' en
    cualquiera de las formas conocidas; el texto nuevo va en la MISMA forma (03-Nov-2026 -> 04-Nov-2026)."""
    if not isinstance(texto, str) or not mapa or not re.search(r"\d", texto):
        return []
    hallados = []
    for plantilla, orden_p in _FORMAS_FECHA:
        if orden and orden_p and orden_p != orden:
            continue
        con_mes = "{b}" in plantilla or "{B}" in plantilla
        for vieja, nueva in mapa.items():
            s = _forma_fecha(plantilla, vieja)
            antes = r"(?<!\d)" if s[0].isdigit() else r"(?<![A-Za-z])"
            despues = r"(?!\d)" if s[-1].isdigit() else r"(?![A-Za-z])"
            rx = re.compile(antes + re.escape(s) + despues, re.IGNORECASE if con_mes else 0)
            for m in rx.finditer(texto):
                nuevo = _forma_fecha(plantilla, nueva)
                letras = [ch for ch in m.group(0) if ch.isalpha()]
                if letras and all(ch.isupper() for ch in letras):
                    nuevo = nuevo.upper()
                elif letras and all(ch.islower() for ch in letras):
                    nuevo = nuevo.lower()
                hallados.append((m.start(), m.end(), nuevo))
    elegidos = []
    for a, b, nuevo in sorted(hallados, key=lambda x: (-(x[1] - x[0]), x[0])):
        if all(b <= a2 or a >= b2 for a2, b2, _ in elegidos):
            elegidos.append((a, b, nuevo))
    return sorted(elegidos)


def reemplazar_fechas_en_texto(texto, mapa, orden=None):
    """Cambia en 'texto' cada fecha de 'mapa' {vieja: nueva} por la nueva, en la misma forma.
    Todas se cambian de una vez (03->04 y 04->05 no se pisan). Devuelve (texto, n)."""
    elegidos = _buscar_fechas(texto, mapa, orden)
    if not elegidos:
        return texto, 0
    salida, pos = [], 0
    for a, b, nuevo in elegidos:
        salida.append(texto[pos:a])
        salida.append(nuevo)
        pos = b
    salida.append(texto[pos:])
    return "".join(salida), len(elegidos)


def _fecha_celda_nueva(v, mapa, orden):
    """Valor nuevo de una celda que trae una fecha del cierre anterior (None si no trae)."""
    if isinstance(v, dt.datetime):
        if v.date() in mapa:
            f = mapa[v.date()]
            return dt.datetime(f.year, f.month, f.day, v.hour, v.minute, v.second)
        return None
    if isinstance(v, dt.date):
        return mapa.get(v)
    if isinstance(v, str):
        nuevo, n = reemplazar_fechas_en_texto(v, mapa, orden)
        return nuevo if n else None
    return None


def detectar_orden_fechas(libro):
    """dmy o mdy segun las fechas de texto del archivo (None si no se puede saber)."""
    dmy = mdy = 0
    for h in libro.hojas:
        for fila in h.filas:
            for v in fila:
                if not isinstance(v, str) or "/" not in v and "-" not in v and "." not in v:
                    continue
                for m in re.finditer(r"(?<!\d)(\d{1,2})[/.-](\d{1,2})[/.-]\d{4}(?!\d)", v):
                    a, b = int(m.group(1)), int(m.group(2))
                    if a > 12 >= b:
                        dmy += 1
                    elif b > 12 >= a:
                        mdy += 1
    if dmy > 3 * mdy:
        return "dmy"
    if mdy > 3 * dmy:
        return "mdy"
    return None


def _orden_del_reporte(rep, conf, libro):
    return (conf.get("orden_fechas") or (rep.get("pareo") or {}).get("orden_fechas") or detectar_orden_fechas(libro))


def _etiqueta_negativa(texto_antes, etiquetas_no):
    """True si lo que va justo antes de la fecha es 'Flow date:', 'Trade Date', 'Maturity' ..."""
    t = re.sub(r"\s+", " ", str(texto_antes or "")).strip().lower()
    if not t or not etiquetas_no:
        return False
    rx = r"\b(%s)\b\.?\s*(date|dt|fecha)?\s*[:=\-]?\s*$" % "|".join(re.escape(x) for x in etiquetas_no)
    return re.search(rx, t) is not None


def ediciones_cierre_anterior(libro, rep, conf, mapa_cob, mapa_emi):
    """Cambios para llevar un statement del cierre anterior al cierre de hoy.
    1) Columnas de fecha de cierre (Valuation Date, COB Date, As Of...): cada fila del cierre anterior.
    2) Encabezado (filas antes de la tabla, o las primeras filas de hojas sin tabla, ej. First_Page):
       fechas del cierre y de emision ('Statement as at', 'Report as of', 'Run on', 'Date:'), salvo
       las que son de una operacion ('Flow date:', 'Trade Date'...).
    Devuelve (ediciones, resumen) y deja el libro en memoria con las fechas nuevas."""
    orden = _orden_del_reporte(rep, conf, libro)
    claves = {normalizar_encabezado(n) for n in conf.get("columnas_fecha_cierre", [])}
    mapa_todo = dict(mapa_emi)
    mapa_todo.update(mapa_cob)
    encabezados = {}
    for t in detectar_tablas(libro, rep.get("tabla")):
        encabezados.setdefault(t.hoja_idx, {}).setdefault(t.fila_enc, {})
    for h_idx, hoja in enumerate(libro.hojas):
        for i, fila in enumerate(hoja.filas):
            cols = {j: str(v).strip() for j, v in enumerate(fila) if normalizar_encabezado(v) in claves}
            # solo filas de encabezado de una tabla (varias columnas), no una etiqueta suelta "As Of: ..."
            if cols and sum(1 for v in fila if v is not None and str(v).strip()) >= 3:
                encabezados.setdefault(h_idx, {}).setdefault(i, {}).update(cols)
    ediciones, resumen = [], Counter()
    detalle = "cierre anterior: %s" % ", ".join("%s -> %s" % (a.strftime("%d-%m-%Y"), b.strftime("%d-%m-%Y"))
                                                for a, b in sorted(mapa_todo.items()))

    def cambiar(h_idx, i, j, nuevo, col_nombre, clave_resumen):
        hoja = libro.hojas[h_idx]
        anterior = hoja.valor(i, j)
        hoja.poner(i, j, nuevo)
        ediciones.append(Edicion(h_idx, i, j, anterior, nuevo, "cierre_anterior", detalle, col_nombre, "",
                                 MANTENER_FORMATO if isinstance(nuevo, str) else None))
        resumen[clave_resumen] += 1

    for h_idx, hoja in enumerate(libro.hojas):
        filas_enc = sorted(encabezados.get(h_idx, {}))
        # 1) columnas de fecha de cierre, desde cada encabezado hasta el siguiente
        for k, i0 in enumerate(filas_enc):
            fin = filas_enc[k + 1] if k + 1 < len(filas_enc) else len(hoja.filas)
            for j, nombre in encabezados[h_idx][i0].items():
                for i in range(i0 + 1, fin):
                    nuevo = _fecha_celda_nueva(hoja.valor(i, j), mapa_cob, orden)
                    if nuevo is not None:
                        cambiar(h_idx, i, j, nuevo, nombre, "%s %s" % (hoja.nombre, nombre))
        # 2) encabezado del reporte
        tope = filas_enc[0] if filas_enc else min(len(hoja.filas), int(conf.get("filas_encabezado", 15)))
        for i in range(tope):
            fila = hoja.filas[i]
            for j, v in enumerate(fila):
                nuevo = _fecha_celda_nueva(v, mapa_todo, orden)
                if nuevo is None:
                    continue
                antes = ""
                if isinstance(v, str):
                    hallados = _buscar_fechas(v, mapa_todo, orden)
                    antes = v[:hallados[0][0]] if hallados else ""
                if not re.search(r"[A-Za-z]", antes):
                    previos = [x for x in fila[:j] if x is not None and str(x).strip()]
                    antes = str(previos[-1]) if previos else ""
                if _etiqueta_negativa(antes, conf.get("etiquetas_no", [])):
                    continue
                cambiar(h_idx, i, j, nuevo, "(encabezado)", "%s %s%d" % (hoja.nombre, indice_a_letra(j), i + 1))
    return ediciones, resumen


def fechas_del_nombre(rep, nombre):
    """(cob, emision) segun el nombre del archivo (cualquiera puede ser None)."""
    rx = compilar(rep.get("adjunto", {}).get("patron"))
    m = rx.fullmatch(nombre) if rx else None
    if not m:
        return None, None
    g = m.groupdict()
    cob = fecha_desde_texto(g["cob"]) if g.get("cob") else None
    emi = fecha_desde_texto(g["emision"]) if g.get("emision") else None
    return cob, emi


def _dia_semana(d, paso):
    d = d + dt.timedelta(days=paso)
    while d.weekday() >= 5:
        d += dt.timedelta(days=paso)
    return d


def fechas_base(rep, nombre):
    """Cierre y emision del archivo base. Si el nombre trae solo una, la otra se deduce
    (la emision es el dia habil siguiente al cierre)."""
    cob, emi = fechas_del_nombre(rep, nombre)
    if cob is None and emi is not None:
        cob = _dia_semana(emi, -1)
    if emi is None and cob is not None:
        emi = _dia_semana(cob, 1)
    return cob, emi


def nombre_con_fechas_nuevas(rep, nombre, mapa_cob, mapa_emi):
    """Nombre del archivo con las fechas de hoy, en la misma forma (None si no se pudo)."""
    rx = compilar(rep.get("adjunto", {}).get("patron"))
    m = rx.fullmatch(nombre) if rx else None
    if not m:
        return None
    grupos = sorted((m.span(g), g) for g in ("cob", "emision") if g in rx.groupindex and m.group(g))
    if not grupos:
        return None
    salida, pos = [], 0
    for (a, b), g in grupos:
        salida.append(nombre[pos:a])
        nuevo, n = reemplazar_fechas_en_texto(nombre[a:b], mapa_cob if g == "cob" else mapa_emi)
        if not n:
            return None
        salida.append(nuevo)
        pos = b
    salida.append(nombre[pos:])
    nuevo_nombre = "".join(salida)
    return nuevo_nombre if rx.fullmatch(nuevo_nombre) else None


def cob_del_dia(ctx, ranuras):
    """Cierre que traen los statements de hoy (el mas comun); si no hay ninguno, el habil anterior."""
    conteo = Counter()
    for r in ranuras.values():
        if r.archivo is None or getattr(r, "arrastre", None):
            continue
        cob, _ = fechas_del_nombre(r.reporte, r.archivo.name)
        if cob in ctx.cobs:
            conteo[cob] += 1
    return conteo.most_common(1)[0][0] if conteo else ctx.cobs[0]


def bases_en_carpeta_de_hoy(ctx, ranuras):
    """Archivos de un cierre anterior que dejaste en la carpeta de hoy (01_Originales o suelto en
    la carpeta del dia) para reportes que no tienen el de hoy. {clave: (ruta, cob, emision)}"""
    vacias = {r.clave: r for r in ranuras.values() if r.archivo is None}
    if not vacias:
        return {}
    salida = {}
    for carpeta in (ctx.dir_orig, ctx.dia):
        try:
            archivos = sorted(carpeta.iterdir())
        except OSError:
            continue
        for ruta in archivos:
            if not ruta.is_file() or ruta.name.startswith(("~$", ".")) or ruta.suffix == ".descargando":
                continue
            rep, fondo, tipo, fecha = identificar_archivo(ctx, ruta.name)
            if rep is None or (rep["id"], fondo) not in vacias:
                continue
            cob, emi = fechas_base(rep, ruta.name)
            if cob is None or cob >= min(ctx.cobs):
                continue
            previo = salida.get((rep["id"], fondo))
            if previo is None or cob > previo[1]:
                salida[(rep["id"], fondo)] = (ruta, cob, emi)
    return salida


def _mover_a_base(ctx, ruta):
    carpeta = ctx.dir_orig / CARPETA_BASE_CIERRE
    carpeta.mkdir(parents=True, exist_ok=True)
    destino = carpeta / ruta.name
    if destino.exists():
        if sha1_archivo(destino) == sha1_archivo(ruta):
            ruta.unlink()           # es el mismo archivo que ya quedo guardado ahi
            return destino
        destino = carpeta / ("%s_%s%s" % (ruta.stem, dt.datetime.now().strftime("%H%M%S"), ruta.suffix))
    shutil.move(str(ruta), str(destino))
    return destino


def crear_desde_cierre_anterior(ctx, r, base, cob_base, emi_base, cob_nuevo, manifiesto, copiar=False):
    """Arma en 01_Originales el statement de hoy a partir del de un cierre anterior."""
    rep = r.reporte
    quien = rep.get("contraparte", rep["id"])
    conf = conf_cierre_anterior(ctx, rep)
    emi_base = emi_base or _dia_semana(cob_base, 1)
    mapa_cob = {cob_base: cob_nuevo}
    mapa_emi = {cob_base + dt.timedelta(days=k): ctx.hoy for k in range(1, max(1, (emi_base - cob_base).days) + 1)}
    nuevo_nombre = nombre_con_fechas_nuevas(rep, base.name, mapa_cob, mapa_emi)
    if not nuevo_nombre:
        r.observaciones.append("No pude poner la fecha de hoy en el nombre de %s; no se uso el del cierre anterior"
                               % base.name)
        return False
    destino = ctx.dir_orig / nombre_seguro(nuevo_nombre)
    try:
        libro = Libro(base)
        ediciones, resumen = ediciones_cierre_anterior(libro, rep, conf, mapa_cob, mapa_emi)
        ctx.dir_orig.mkdir(parents=True, exist_ok=True)
        if destino.exists():
            carpeta = ctx.dir_orig / "_reemplazados"
            carpeta.mkdir(exist_ok=True)
            shutil.move(str(destino), str(carpeta / ("%s_%s%s" % (destino.stem, dt.datetime.now().strftime("%H%M%S"),
                                                                   destino.suffix))))
        if ediciones:
            avisos, fallas = escribir_y_verificar(ctx, libro, base, destino, ediciones,
                                                  ctx.conf.get("motor_excel", "excel"))
            if fallas:
                try:
                    destino.unlink()
                except OSError:
                    pass
                r.observaciones.append("No pude dejar las fechas de hoy en %s (%s); no se uso" % (base.name, fallas[0]))
                LOG.error("[%s %s] cierre anterior, fallas: %s", rep["id"], r.fondo, fallas)
                return False
        else:
            shutil.copy2(base, destino)
    except Exception as e:
        r.observaciones.append("No pude usar el statement del cierre anterior %s: %s" % (base.name, e))
        LOG.error(traceback.format_exc())
        return False
    # El archivo que dejaste (o una copia, si venia de otro dia) queda en 01_Originales\_base_cierre_anterior
    if copiar:
        carpeta = ctx.dir_orig / CARPETA_BASE_CIERRE
        carpeta.mkdir(parents=True, exist_ok=True)
        guardado = carpeta / base.name
        if not guardado.exists():
            shutil.copy2(base, guardado)
    else:
        guardado = _mover_a_base(ctx, base)
    vencen = sorted({op["id"] for op in operaciones_del_libro(libro, rep, r.fondo)
                     if op.get("md") is not None and op["md"] <= cob_nuevo})
    info = {"base": base.name, "base_guardada": mostrar(guardado), "cob_base": str(cob_base), "cob_nuevo": str(cob_nuevo),
            "emision_base": str(emi_base), "emision_nueva": str(ctx.hoy), "celdas": len(ediciones),
            "detalle": dict(resumen), "vencen": vencen}
    manifiesto["archivos"][destino.name] = {
        "reporte": rep["id"], "fondo": r.fondo, "origen": ORIGEN_CIERRE, "cierre_anterior": info,
        "creado": dt.datetime.now().isoformat(timespec="seconds"), "sha1": sha1_archivo(destino)}
    r.archivo = destino
    r.origen = ORIGEN_CIERRE
    r.arrastre = info
    r.estado = ESTADO_OBS
    ctx.no_usados[:] = [x for x in ctx.no_usados if not x.startswith(base.name + " (")]
    r.observaciones.append(texto_cierre_anterior(info, quien))
    hojas_cols = "; ".join("%s (%d)" % kv for kv in sorted(resumen.items()))
    grupos = OrderedDict()
    for e in ediciones:
        hoja = libro.hojas[e.hoja].nombre
        if e.col_nombre == "(encabezado)":
            r.detalle_cambios.append([hoja, "%s%d" % (indice_a_letra(e.col), e.fila + 1), e.col_nombre, "",
                                      normalizar(e.anterior), normalizar(e.nuevo), "cierre_anterior",
                                      "fecha del cierre anterior llevada a la de hoy"])
        else:
            grupos.setdefault((hoja, e.col, e.col_nombre), []).append(e)
    for (hoja, col, nombre), eds in grupos.items():
        filas = [e.fila + 1 for e in eds]
        r.detalle_cambios.append([hoja, "%s%d:%s%d" % (indice_a_letra(col), min(filas), indice_a_letra(col), max(filas)),
                                  nombre, "%d filas" % len(eds), normalizar(eds[0].anterior), normalizar(eds[0].nuevo),
                                  "cierre_anterior", "fecha del cierre anterior llevada a la de hoy"])
    decir("  %s%s: no llego el de hoy; uso el del cierre %s (%s) con fechas al %s: %s"
          % (quien, (" fondo %s" % r.fondo) if len(rep.get("fondos", [])) > 1 else "", cob_base.strftime("%d-%m"),
             base.name, cob_nuevo.strftime("%d-%m"), hojas_cols or "solo el nombre"))
    LOG.info("[%s %s] cierre anterior %s -> %s (%s): %s", rep["id"], r.fondo, base.name, destino.name,
             hojas_cols, [e.describir(libro) for e in ediciones[:20]])
    return True


def texto_cierre_anterior(info, quien):
    cob_b = fecha_desde_texto(info["cob_base"])
    cob_n = fecha_desde_texto(info["cob_nuevo"])
    partes = ["SIN STATEMENT DE HOY: se uso el del cierre %s (%s) con las fechas llevadas al cierre %s"
              % (cob_b.strftime("%d-%m-%Y"), info["base"], cob_n.strftime("%d-%m-%Y"))]
    if info.get("detalle"):
        partes.append("(%s)" % "; ".join("%s: %d" % kv for kv in sorted(info["detalle"].items())))
    texto = " ".join(partes) + ". Las operaciones y el MTM son los del %s" % cob_b.strftime("%d-%m")
    if info.get("vencen"):
        texto += ("; %d operacion(es) vencen el %s o antes y la contraparte ya no las informaria: %s"
                  % (len(info["vencen"]), cob_n.strftime("%d-%m"), ", ".join(info["vencen"][:8])
                     + (" ..." if len(info["vencen"]) > 8 else "")))
    return texto + ". Si llega el de %s, vuelve a ejecutar y lo reemplaza" % quien


def aplicar_cierre_anterior(ctx, ranuras, manifiesto):
    """Statements de un cierre anterior que dejaste en la carpeta de hoy: los deja con las fechas de hoy."""
    conf = conf_cierre_anterior(ctx)
    if not conf.get("activo", True):
        return []
    bases = bases_en_carpeta_de_hoy(ctx, ranuras)
    if not bases:
        return []
    cob_nuevo = cob_del_dia(ctx, ranuras)
    hechos = []
    for clave, (ruta, cob, emi) in sorted(bases.items()):
        r = ranuras[clave]
        if not conf_cierre_anterior(ctx, r.reporte).get("activo", True):
            continue
        if crear_desde_cierre_anterior(ctx, r, ruta, cob, emi, cob_nuevo, manifiesto):
            hechos.append(r)
    guardar_manifiesto(ctx, manifiesto)
    return hechos


def buscar_base_dias_anteriores(ctx, rep, fondo, cob_nuevo, dias_atras):
    """Ultimo statement de ese reporte y fondo en 01_Originales de dias anteriores."""
    sub = ctx.conf.get("subcarpetas_dia", {}).get("originales", "01_Originales")
    limite = ctx.hoy - dt.timedelta(days=int(dias_atras))
    try:
        dias = sorted((p for p in ctx.raiz_descargas.iterdir() if p.is_dir()), key=lambda p: p.name, reverse=True)
    except OSError:
        return None
    for d in dias:
        f = fecha_desde_texto(d.name)
        if f is None or not (limite <= f < ctx.hoy):
            continue
        carpeta = d / sub
        mejor = None
        try:
            archivos = sorted(carpeta.iterdir())
        except OSError:
            continue
        for ruta in archivos:
            if not ruta.is_file() or ruta.name.startswith(("~$", ".")):
                continue
            r2, f2, _, _ = identificar_archivo(ctx, ruta.name)
            if r2 is None or r2["id"] != rep["id"] or f2 != fondo:
                continue
            cob, emi = fechas_base(rep, ruta.name)
            if cob is None or cob >= cob_nuevo:
                continue
            if mejor is None or cob > mejor[1]:
                mejor = (ruta, cob, emi, d)
        if mejor:
            return mejor
    return None


def ofrecer_cierre_anterior(ctx, ranuras, manifiesto):
    """Al final: si un statement no llego y hay uno de un cierre anterior en carpetas de dias pasados,
    ofrece usarlo con las fechas de hoy (por defecto no)."""
    conf = conf_cierre_anterior(ctx)
    if not conf.get("activo", True):
        return
    # v2.3: todo lo que quedo sin archivo (no llego, quedo en 03_Revisar o el manual no se guardo)
    faltan = [r for r in sorted(ranuras.values(), key=lambda x: (x.reporte.get("contraparte", ""), x.fondo))
              if r.archivo is None and r.estado != ESTADO_ERROR
              and conf_cierre_anterior(ctx, r.reporte).get("activo", True)]
    if not faltan:
        return
    cob_nuevo = cob_del_dia(ctx, ranuras)
    opciones, sin_base = [], []
    for r in faltan:
        base = buscar_base_dias_anteriores(ctx, r.reporte, r.fondo, cob_nuevo, conf.get("dias_atras", 10))
        if base is None and int(conf.get("dias_atras_max", 31)) > int(conf.get("dias_atras", 10)):
            # el ultimo que mando la contraparte, aunque sea mas antiguo
            base = buscar_base_dias_anteriores(ctx, r.reporte, r.fondo, cob_nuevo, conf.get("dias_atras_max", 31))
        if base:
            opciones.append((r, base))
        else:
            sin_base.append(r)
    for r in sin_base:
        r.observaciones.append("No llego y no hay un statement anterior de %s en las carpetas de los ultimos %s dias "
                               "para reutilizar" % (r.reporte.get("contraparte", r.reporte["id"]),
                                                    conf.get("dias_atras_max", 31)))
    if not opciones:
        return
    nombre = lambda r: "%s%s" % (r.reporte.get("contraparte", r.reporte["id"]),
                                 (" fondo %s" % r.fondo) if len(r.reporte.get("fondos", [])) > 1 else "")
    if not ctx.interactivo or not conf.get("ofrecer", True):
        for r, (ruta, cob, emi, d) in opciones:
            r.observaciones.append("Hay statement del cierre %s (%s\\%s). Si %s no va a enviar el de hoy, copialo a "
                                   "01_Originales de hoy y vuelve a ejecutar: queda con las fechas de hoy"
                                   % (cob.strftime("%d-%m"), d.name, ruta.name, r.reporte.get("contraparte")))
        return
    decir("")
    decir("  FALTAN %d STATEMENT(S). Puedo reutilizar el ultimo que mando cada contraparte, con las fechas de hoy:"
          % len(opciones))
    for k, (r, (ruta, cob, emi, d)) in enumerate(opciones, 1):
        motivo = " [hay correos parecidos en 03_Revisar]" if r.candidatos_revisar or r.estado == ESTADO_REVISAR else ""
        decir("   %d) %s: cierre %s (%s\\%s)%s" % (k, nombre(r), cob.strftime("%d-%m-%Y"), d.name, ruta.name, motivo))
    decir("  Si la contraparte no los va a enviar, los uso con las fechas llevadas al cierre %s (el MTM queda el del "
          "cierre anterior)." % cob_nuevo.strftime("%d-%m-%Y"))
    resp = preguntar("  T = usar todos  |  numeros separados por coma (ej. 1,2)  |  Enter = no, seguir esperando: ",
                     ctx.interactivo, "")
    resp = resp.strip().upper()
    if not resp:
        for r, (ruta, cob, emi, d) in opciones:
            r.observaciones.append("No llego; no se uso el del cierre %s (se respondio que no)" % cob.strftime("%d-%m"))
        return
    if resp.startswith(("T", "S", "C")):
        elegidos = list(range(len(opciones)))
    else:
        elegidos = sorted({int(x) - 1 for x in re.findall(r"\d+", resp) if 0 < int(x) <= len(opciones)})
    for k in elegidos:
        r, (ruta, cob, emi, d) = opciones[k]
        crear_desde_cierre_anterior(ctx, r, ruta, cob, emi, cob_nuevo, manifiesto, copiar=True)
    guardar_manifiesto(ctx, manifiesto)
    if elegidos:
        paso("Preparacion", preparar_archivos, ctx, ranuras, manifiesto)


def reemplazo_de_cierre_anterior(ctx, r, provisional, nuevo, manifiesto):
    """Llego el statement de hoy: reemplaza al armado con el del cierre anterior."""
    rep = r.reporte
    quien = rep.get("contraparte", rep["id"])
    salida_vieja = ctx.dir_cargar / nombre_de_salida(rep, getattr(r, "nombre_armado", provisional.name))
    salida_nueva = ctx.dir_cargar / nombre_de_salida(rep, nuevo.name)
    if salida_vieja.exists() and mostrar(salida_vieja).lower() != mostrar(salida_nueva).lower():
        respaldar(salida_vieja, ctx.dir_cargar / "_respaldo")
        salida_vieja.unlink()
        manifiesto.setdefault("preparados", {}).pop(salida_vieja.name, None)
    ctx.forzar.add(r.clave)
    r.arrastre = None
    r.observaciones = [o for o in r.observaciones if not o.startswith("SIN STATEMENT DE HOY")]
    msg = ("Llego el statement de hoy de %s y reemplaza al armado con el del cierre anterior. Si ya cargaste ese en el "
           "aplicativo, vuelve a cargar el de 02_Para_Cargar" % quien)
    decir("  " + msg + ".")
    r.observaciones.append(msg)
    if r.estado == ESTADO_OK:
        r.estado = ESTADO_OBS
    manifiesto["archivos"].setdefault(nuevo.name, {}).update({"reemplaza_cierre_anterior": mostrar(provisional)})


# =============================================================================
# Pareo con la cartera de Vmetrix
# =============================================================================
# Despues de las reglas y del resultado esperado (ajustes_operaciones.json), cada operacion del
# statement se busca en la cartera de Vmetrix (misma contraparte, fondo, tipo, monedas, nominal,
# fechas). Si la encuentra y solo difiere en fechas, centavos del nominal principal o la tasa,
# deja el archivo igual a la cartera (que es lo que espera el aplicativo). Lo que no se puede
# corregir con seguridad se informa en rojo. Todo queda en un correo y en Pareo_AAAA-MM-DD.xlsx.
#   configuracion.json > vmetrix, pareo, correo_informe     reportes.json > <reporte> > pareo

VM_COLUMNAS = {
    "contraparte": "Counterparty", "tipo_empresa": "Company Type", "fondo": "Portfolio", "tipo": "Ins Type",
    "nominal": "Side Notional", "moneda": "Notional Currency", "compra_venta": "Buy/Sell",
    "referencia": "Inst. Reference", "trade": "Trade Date", "inicio": "Settle Date", "vencimiento": "Expiration Date",
    "id": "Tran Id",
}
VM_MONEDAS = {"US$": "USD", "NO ": "CLP", "UF ": "CLF", "CNF": "CHF"}
CAMPO_TEXTO = {"td": "Fecha trade", "sd": "Fecha inicio", "md": "Vencimiento", "nominal": "Nominal",
               "tasa": "Tasa", "tasa_flotante": "Tasa pata flotante"}


def _clave_col(nombre):
    return re.sub(r"[^a-z0-9]", "", str(nombre).lower())


def _num_vm(v):
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().replace(",", "").replace(" ", "")
    if not s or s.upper() in ("NA", "N/A", "-"):
        return None
    neg = s.startswith("(") and s.endswith(")")
    s = s.strip("()").rstrip("%")
    try:
        x = float(s)
    except ValueError:
        return None
    return -x if neg else x


def _fecha_vm(v, orden="dmy"):
    if v is None:
        return None
    if isinstance(v, dt.datetime):
        return v.date()
    if isinstance(v, dt.date):
        return v
    if isinstance(v, (int, float)) and v > 10 ** 11:          # epoch en milisegundos (API)
        return dt.datetime.utcfromtimestamp(v / 1000.0).date()
    s = str(v).strip()
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})", s)
    if m:
        return _fecha(*m.groups())
    if re.fullmatch(r"\d{1,2}/\d{1,2}/\d{4}", s):
        return _leer_fecha(s, orden)
    return fecha_desde_texto(s)


def _decimales(v):
    """Decimales con que viene escrito un numero (para comparar tasas a la misma precision)."""
    if isinstance(v, float):
        t = repr(v)
        return len(t.split(".")[1].rstrip("0")) if "." in t and "e" not in t else 8
    t = str(v).strip().rstrip("%)")
    return len(t.split(".")[1].rstrip("0")) if "." in t else 0


# ----------------------------------------------------------------------------- cartera
def _credenciales_vmetrix(ctx, conf):
    texto = (ctx.usuario or {}).get("credenciales_vmetrix") or conf.get("archivo_credenciales") or ""
    t = str(texto).replace("{USUARIO}", ctx.login)
    if os.sep == "/":
        t = t.replace("\\", "/")
    ruta = Path(os.path.expandvars(os.path.expanduser(t)))
    if not t or not ruta.exists():
        raise RuntimeError("no encontre el archivo de credenciales de Vmetrix (%s). Crea un TXT con dos lineas "
                           "LOGIN=tu_usuario y PASS=tu_clave, o indica la ruta en usuarios.json "
                           "('credenciales_vmetrix')" % (ruta if t else "sin ruta configurada"))
    datos = {}
    for linea in ruta.read_text(encoding="utf-8-sig", errors="replace").splitlines():
        if "=" in linea:
            k, v = linea.split("=", 1)
            datos[k.strip().upper()] = v.strip()
    if not datos.get("LOGIN") or not (datos.get("PASS") or datos.get("PASSWORD")):
        raise RuntimeError("el archivo %s debe tener LOGIN=... y PASS=..." % ruta.name)
    return datos["LOGIN"], datos.get("PASS") or datos.get("PASSWORD")


def _tabla_vmetrix(data):
    """Respuesta del report-station -> lista de diccionarios (soporta las formas habituales)."""
    filas, columnas = None, None
    if isinstance(data, list):
        filas = data
    elif isinstance(data, dict):
        for campo in ("items", "rows", "data", "content", "results", "records"):
            valor = data.get(campo)
            if isinstance(valor, list):
                filas = valor
                break
            if isinstance(valor, dict):
                interna = _tabla_vmetrix(valor)
                if interna:
                    return interna
        for campo in ("columns", "headers", "header", "fields", "columnNames"):
            if isinstance(data.get(campo), list):
                columnas = []
                for c in data[campo]:
                    if isinstance(c, dict):
                        c = next((c[k] for k in ("label", "name", "title", "field", "key") if c.get(k)), c)
                    columnas.append(str(c))
                break
    if not filas:
        # forma no prevista: uso la lista de filas mas larga que aparezca en cualquier nivel
        mejor = []

        def buscar(x, nivel=0):
            nonlocal mejor
            if nivel > 6:
                return
            if isinstance(x, dict):
                for v in x.values():
                    buscar(v, nivel + 1)
            elif isinstance(x, list):
                if len(x) > len(mejor) and x and all(isinstance(f, (dict, list)) for f in x[:50]):
                    mejor = x
                for v in x[:5]:
                    buscar(v, nivel + 1)
        buscar(data)
        if not mejor or mejor is data:
            return []
        return _tabla_vmetrix(mejor) if all(isinstance(f, dict) for f in mejor[:50]) else \
            _tabla_vmetrix(dict(data if isinstance(data, dict) else {}, rows=mejor))
    if all(isinstance(f, dict) for f in filas):
        return filas
    columnas = columnas or ["Columna %d" % (k + 1) for k in range(max(len(f) for f in filas))]
    return [dict(zip(columnas, f if isinstance(f, (list, tuple)) else [f])) for f in filas]


def _cartera_desde_api(ctx, conf):
    try:
        import requests
    except ImportError:
        raise RuntimeError("falta la libreria requests (pip install requests)")
    login, clave = _credenciales_vmetrix(ctx, conf)
    base = str(conf.get("url", "https://principal.vmetrix.com")).rstrip("/")
    r = requests.post(base + "/authentication/v1/auth", json={"login": login, "password": clave}, timeout=60)
    r.raise_for_status()
    token = r.json()["accessToken"]
    reportes = conf.get("reportes") or [{"nombre": "cartera", "id": conf["reporte_cartera"]}]
    tablas = []
    for rp in reportes:
        nombre, rid = (rp.get("nombre", "reporte"), rp["id"]) if isinstance(rp, dict) else ("reporte", rp)
        r = requests.get(base + "/report-station/v1/report/" + rid,
                         headers={"Authorization": token, "Content-Type": "application/json"},
                         timeout=int(conf.get("timeout", 180)))
        r.raise_for_status()
        filas = _tabla_vmetrix(r.json())
        if not filas:
            raise RuntimeError("el reporte %s vino vacio" % nombre)
        tablas.append((nombre, filas))
    return tablas


def _cartera_desde_archivos(rutas):
    return [(Path(r).stem, _cartera_desde_archivo(r)) for r in rutas]


def _cartera_desde_archivo(ruta):
    ruta = Path(ruta)
    if ruta.suffix.lower() == ".csv":
        import csv
        texto = ruta.read_bytes().decode("utf-8-sig", errors="replace")
        lineas = texto.splitlines()
        # las copias que guarda el script (vmetrix_copia_*.csv) van separadas por ';'
        primera = lineas[0] if lineas else ""
        sep = ";" if primera.count(";") > primera.count(",") else ","
        return list(csv.DictReader(lineas, delimiter=sep))
    import openpyxl
    wb = openpyxl.load_workbook(str(ruta), read_only=True, data_only=True)
    ws = wb.worksheets[0]
    filas, enc, vacias = [], None, 0
    for valores in ws.iter_rows(values_only=True):
        if enc is None:
            if valores and sum(1 for v in valores if v not in (None, "")) >= 5:
                enc = [str(v).strip() if v is not None else "" for v in valores]
            continue
        if not any(v not in (None, "") for v in valores):
            vacias += 1
            if vacias > 50:
                break
            continue
        vacias = 0
        filas.append(dict(zip(enc, valores)))
    wb.close()
    return filas


def _guardar_copia_cartera(ctx, filas, nombre="cartera"):
    import csv
    if not filas:
        return
    columnas = []
    for f in filas[:50]:
        for k in f:
            if k not in columnas:
                columnas.append(k)
    try:
        nombre = re.sub(r"[^A-Za-z0-9]+", "_", str(nombre)).strip("_").lower()
        archivo = ("%s.csv" if nombre.startswith("vmetrix_copia") else "vmetrix_copia_%s.csv") % nombre
        with open(str(ctx.dia / archivo), "w", newline="", encoding="utf-8-sig") as fh:
            w = csv.writer(fh, delimiter=";")
            w.writerow(columnas)
            for f in filas:
                w.writerow(["" if f.get(c) is None else f.get(c) for c in columnas])
    except Exception as e:
        LOG.warning("No pude guardar la copia de la cartera: %s", e)


VM_COLUMNAS_FX = {"contraparte": "Counterparty", "fondo": "Portfolio", "referencia": "Inst. Reference",
                  "monto_base": "FX-FWD Base Amount", "monto_cotizada": "FX-FWD Quote Amount",
                  "moneda_base": "Base Ccy", "trade": "Trade Date", "vencimiento": "Settle Date",
                  "id": "Tran Deal", "id_externo": "Tran External ID", "estado": "Status", "ndf": "Is Ndf"}
VM_COLUMNAS_SWAP = {"contraparte": "Counterparty", "fondo": "Portfolio", "referencia": "Inst. Reference",
                    "nominal": "Nominal", "nominal_lado": "Side Notional", "moneda": "Notnl Ccy",
                    "trade": "Trade Date", "inicio": "Settle Date", "vencimiento": "Expiration Date",
                    "id": "Tran Deal", "id_externo": "Tran External ID", "estado": "Status"}
VM_ESTADOS_FUERA = re.compile(r"CANCEL|DELET|REJECT|ANUL|ELIMIN", re.IGNORECASE)


def formato_reporte_vm(filas):
    """'fx' (reporte FX de Vmetrix), 'swap' (reporte Swap) o 'cartera' (reporte de cartera antiguo)."""
    claves = set()
    for f in filas[:20]:
        claves.update(_clave_col(k) for k in f)
    if "fxfwdbaseamount" in claves:
        return "fx"
    if "fixfloat" in claves:
        return "swap"
    return "cartera"


def _columnas_vm(filas, nombres, obligatorias, formato):
    claves = {}
    for f in filas[:20]:
        for k in f:
            claves.setdefault(_clave_col(k), k)
    faltan = [nombres[k] for k in obligatorias if _clave_col(nombres[k]) not in claves]
    if faltan:
        raise RuntimeError("el reporte %s de Vmetrix no trae las columnas %s (trae: %s). Ajusta configuracion.json "
                           "> vmetrix > columnas_%s" % (formato, ", ".join(faltan), ", ".join(list(claves.values())[:40]),
                                                       formato))
    return {k: claves.get(_clave_col(v)) for k, v in nombres.items()}


def _vigente(op, cob):
    return op["td"] is not None and op["md"] is not None and op["td"] <= cob < op["md"]


def normalizar_reporte_fx(filas, conf, cob, ignorar=()):
    """Reporte FX de Vmetrix (vista Cuprum): trae los montos exactos de las dos monedas."""
    nombres = dict(VM_COLUMNAS_FX, **(conf.get("columnas_fx") or {}))
    monedas = dict(VM_MONEDAS, **(conf.get("monedas") or {}))
    col = _columnas_vm(filas, nombres, ("contraparte", "fondo", "referencia", "monto_base", "monto_cotizada",
                                        "moneda_base", "trade", "vencimiento"), "fx")
    ops, extranjeras = [], Counter()
    for f in filas:
        g = lambda campo: f.get(col[campo]) if col.get(campo) else None
        if VM_ESTADOS_FUERA.search(str(g("estado") or "")):
            continue
        ref, cp = str(g("referencia") or "").strip(), str(g("contraparte") or "").strip()
        m = re.match(r"^(.{3})(.{3})(.{3})(\d{6})_([\d.,]+)_(BUY|SELL)", ref, re.IGNORECASE)
        mb, mc = _num_vm(g("monto_base")), _num_vm(g("monto_cotizada"))
        base = str(g("moneda_base") or "").strip().upper()
        if not m or not cp or mb is None or mc is None or not base:
            continue
        fichas = [monedas.get(m.group(2), m.group(2)), monedas.get(m.group(3), m.group(3))]
        if base not in fichas:
            continue
        otra = fichas[1] if fichas[0] == base else fichas[0]
        txt = m.group(5).replace(".", "").replace(",", ".") if "," in m.group(5) else m.group(5)
        md = _fecha_vm(g("vencimiento"))
        if md is None:
            try:
                md = dt.datetime.strptime(m.group(4), "%y%m%d").date()
            except ValueError:
                continue
        op = dict(cp=cp, fondo=str(g("fondo") or "").strip()[-1:].upper(), id=normalizar(g("id")), ref=ref,
                  id_externo=normalizar(g("id_externo")), td=_fecha_vm(g("trade")), sd=None, md=md,
                  extranjera=cp not in ignorar, tipo="FX", base=base, precio=otra, tasa=float(txt),
                  dec_tasa=len(txt.split(".")[1]) if "." in txt else 0, exacta=True, es_deal=True,
                  patas={base: abs(mb), otra: abs(mc)}, compra_base=(mb > 0) if mb else None,
                  ndf=str(g("ndf") or "").strip().upper() in ("1", "TRUE", "SI", "S", "Y", "YES"))
        if not _vigente(op, cob):
            continue
        if op["extranjera"]:
            extranjeras[cp] += 1
        ops.append(op)
    return ops, extranjeras


def normalizar_reporte_swap(filas, conf, cob, ignorar=()):
    """Reporte Swap de Vmetrix (vista Cuprum): una fila por swap; las patas salen del Inst. Reference."""
    nombres = dict(VM_COLUMNAS_SWAP, **(conf.get("columnas_swap") or {}))
    col = _columnas_vm(filas, nombres, ("contraparte", "fondo", "referencia", "moneda", "trade"), "swap")
    ops, extranjeras = [], Counter()
    for f in filas:
        g = lambda campo: f.get(col[campo]) if col.get(campo) else None
        if VM_ESTADOS_FUERA.search(str(g("estado") or "")):
            continue
        ref, cp = str(g("referencia") or "").strip(), str(g("contraparte") or "").strip()
        nominal = _num_vm(g("nominal"))
        if nominal is None:
            nominal = _num_vm(g("nominal_lado"))
        m = re.match(r"^(.{3})(.{3})(\d{6})(\d{6})?_(.*)$", ref)
        if not m or not cp or nominal is None:
            continue
        try:
            md = dt.datetime.strptime(m.group(3), "%y%m%d").date()
        except ValueError:
            md = _fecha_vm(g("vencimiento"))
        patas = m.group(5).split("_")
        fija = [p for p in patas if p.startswith("FIJA")]
        mm = re.search(r"([+-]\d+[.,]\d+)", fija[0]) if fija else None
        op = dict(cp=cp, fondo=str(g("fondo") or "").strip()[-1:].upper(), id=normalizar(g("id")), ref=ref,
                  id_externo=normalizar(g("id_externo")), td=_fecha_vm(g("trade")), sd=_fecha_vm(g("inicio")),
                  md=md, extranjera=cp not in ignorar, tipo="IRS", moneda=str(g("moneda") or "").strip().upper(),
                  nominal=abs(nominal), tasa=float(mm.group(1).replace(",", ".")) if mm else None,
                  afp_paga_fija=bool(patas) and patas[0].startswith("FIJA"), es_deal=True)
        if not _vigente(op, cob):
            continue
        if op["extranjera"]:
            extranjeras[cp] += 1
        ops.append(op)
    return ops, extranjeras


def normalizar_tablas_vm(tablas, conf, cob, ignorar=()):
    """Junta las operaciones de uno o varios reportes de Vmetrix (detecta el formato de cada uno)."""
    ops, extranjeras, formatos = [], Counter(), []
    for nombre, filas in tablas:
        formato = formato_reporte_vm(filas)
        if formato == "fx":
            o, e = normalizar_reporte_fx(filas, conf, cob, ignorar)
        elif formato == "swap":
            o, e = normalizar_reporte_swap(filas, conf, cob, ignorar)
        else:
            o, e = normalizar_cartera(filas, conf, cob)
        formatos.append("%s: %d" % (nombre, len(o)))
        ops.extend(o)
        extranjeras.update(e)
    return ops, extranjeras, formatos


def normalizar_cartera(filas, conf, cob):
    """Filas del reporte de Vmetrix -> operaciones vigentes al cierre (trade <= cierre < vencimiento)."""
    nombres = dict(VM_COLUMNAS, **(conf.get("columnas") or {}))
    monedas = dict(VM_MONEDAS, **(conf.get("monedas") or {}))
    claves = {}
    for f in filas[:20]:
        for k in f:
            claves.setdefault(_clave_col(k), k)
    opcionales = ("tipo_empresa", "id", "compra_venta", "inicio")
    faltan = [v for k, v in nombres.items() if k not in opcionales and _clave_col(v) not in claves]
    if faltan:
        raise RuntimeError("el reporte de Vmetrix no trae las columnas %s (trae: %s). Ajusta configuracion.json > "
                           "vmetrix > columnas" % (", ".join(faltan), ", ".join(list(claves.values())[:40])))
    col = {k: claves.get(_clave_col(v)) for k, v in nombres.items()}
    ops, extranjeras = [], Counter()
    for f in filas:
        g = lambda campo: f.get(col[campo]) if col.get(campo) else None
        ref = str(g("referencia") or "").strip()
        tipo = str(g("tipo") or "").upper()
        cp = str(g("contraparte") or "").strip()
        nominal = _num_vm(g("nominal"))
        if not ref or not cp or nominal is None:
            continue
        op = dict(cp=cp, fondo=str(g("fondo") or "").strip()[-1:].upper(), id=normalizar(g("id")), ref=ref,
                  td=_fecha_vm(g("trade")), sd=_fecha_vm(g("inicio")), md=_fecha_vm(g("vencimiento")),
                  extranjera="EXTRANJ" in str(g("tipo_empresa") or "").upper())
        if "FX" in tipo:
            m = re.match(r"^(.{3})(.{3})(.{3})(\d{6})_([\d.,]+)_(BUY|SELL)", ref, re.IGNORECASE)
            if not m:
                continue
            precio, base = monedas.get(m.group(2), m.group(2)), monedas.get(m.group(3), m.group(3))
            mon = str(g("moneda") or "").strip()
            txt = m.group(5).replace(".", "").replace(",", ".") if "," in m.group(5) else m.group(5)
            tasa = float(txt)
            if mon and mon == precio:       # el nominal viene en la moneda cotizada
                patas = {precio: abs(nominal), base: abs(nominal) / tasa if tasa else 0.0}
            else:
                patas = {base: abs(nominal), precio: abs(nominal) * tasa}
            op.update(tipo="FX", base=base, precio=precio, tasa=tasa,
                      dec_tasa=len(txt.split(".")[1]) if "." in txt else 0, patas=patas)
        elif "IRS" in tipo or "SWAP" in tipo:
            m = re.match(r"^(.{3})(.{3})(\d{6})(\d{6})?_(.*)$", ref)
            patas = m.group(5).split("_") if m else []
            if m:       # el vencimiento del Inst. Reference es el bueno (Expiration Date a veces trae el inicio)
                try:
                    op["md"] = dt.datetime.strptime(m.group(3), "%y%m%d").date()
                except ValueError:
                    pass
            fija = [p for p in patas if p.startswith("FIJA")]
            mm = re.search(r"([+-]\d+[.,]\d+)", fija[0]) if fija else None
            op.update(tipo="IRS", moneda=str(g("moneda") or "").strip(), nominal=abs(nominal),
                      tasa=float(mm.group(1).replace(",", ".")) if mm else None,
                      afp_paga_fija=bool(patas) and patas[0].startswith("FIJA"))
        else:
            continue
        if op["td"] is None or op["md"] is None or op["td"] > cob or op["md"] <= cob:
            continue
        if op["extranjera"]:
            extranjeras[cp] += 1
        ops.append(op)
    return ops, extranjeras


def cargar_cartera_vmetrix(ctx):
    """Baja la cartera (API de Vmetrix; si falla, un archivo cartera_vmetrix*.xlsx/csv en la carpeta del dia)."""
    conf = ctx.conf.get("vmetrix") or {}
    estado = {"ok": False, "origen": "", "error": "", "ops": [], "por_cp": {}, "cambios": [], "no_corregidos": [],
              "sin_cartera": [], "pareadas": set(), "cps_fondos": set(), "cubiertos": {}, "archivos": [],
              "extranjeras": Counter()}
    ctx.pareo = estado
    if not conf.get("activo", True) or getattr(ctx.args, "sin_vmetrix", False):
        estado["error"] = "desactivado (configuracion.json > vmetrix > activo, o --sin-vmetrix)"
        decir("  Pareo con Vmetrix desactivado.")
        return estado
    cob = max(ctx.cobs) if ctx.cobs else ctx.hoy - dt.timedelta(days=1)
    forzado = getattr(ctx.args, "cartera", None)

    ignorar = set((ctx.conf.get("pareo") or {}).get("contrapartes_ignorar", []))

    def locales():
        """Exportaciones de Vmetrix dejadas en la carpeta del dia: cartera_vmetrix*.xlsx/csv (puede ser una sola
        cartera, o el reporte FX y el Swap por separado)."""
        return sorted([p for p in ctx.dia.glob("*") if p.is_file() and p.name.lower().startswith("cartera_vmetrix")
                       and p.suffix.lower() in (".xlsx", ".csv") and not p.name.startswith("~$")],
                      key=lambda p: p.name.lower())

    copias_dia = sorted(p for p in ctx.dia.glob("vmetrix_copia_*.csv") if p.is_file()) if ctx.dia.is_dir() else []
    if forzado:
        rutas = forzado if isinstance(forzado, list) else [forzado]
        fuentes = [("archivo %s" % ", ".join(Path(r).name for r in rutas), lambda: _cartera_desde_archivos(rutas))]
    elif getattr(ctx, "plan_b", False) and copias_dia:
        # plan B: la misma cartera con que se preparo lo que se cargo (copias guardadas en la carpeta del dia)
        fuentes = [("copia del dia %s" % ", ".join(p.name for p in copias_dia),
                    lambda: _cartera_desde_archivos(copias_dia)),
                   ("Vmetrix (API)", lambda: _cartera_desde_api(ctx, conf))]
    else:
        fuentes = [("Vmetrix (API)", lambda: _cartera_desde_api(ctx, conf))]
        if locales():
            fuentes.append(("archivo %s" % ", ".join(p.name for p in locales()),
                            lambda: _cartera_desde_archivos(locales())))
        if conf.get("reportes") and conf.get("reporte_cartera"):
            fuentes.append(("Vmetrix (API, reporte de cartera)",
                            lambda: _cartera_desde_api(ctx, dict(conf, reportes=None))))
    errores, ops = [], None
    for origen, leer in fuentes:
        try:
            tablas = leer()
            if not tablas or not any(f for _, f in tablas):
                raise RuntimeError("la cartera vino vacia")
            ops, extranjeras, formatos = normalizar_tablas_vm(tablas, conf, cob, ignorar)
            if not ops:
                raise RuntimeError("la cartera no tiene operaciones vigentes al %s" % cob.strftime("%d-%m-%Y"))
        except Exception as e:
            errores.append("%s: %s" % (origen, e))
            LOG.warning("Cartera %s: %s", origen, e)
            ops = None
            continue
        if errores:
            decir("  No pude usar %s. Uso %s." % ("; ".join(errores), origen))
        estado["origen"], estado["extranjeras"] = "%s [%s]" % (origen, "; ".join(formatos)), extranjeras
        for nombre, filas in tablas:
            _guardar_copia_cartera(ctx, filas, nombre)
        break
    if ops is None:
        estado["error"] = "; ".join(errores) or "sin cartera"
        decir("  Sin cartera de Vmetrix (%s). Sigo como antes (solo reglas y JSON)." % estado["error"])
        return estado
    estado.update(ok=True, ops=ops, cob=cob)
    for o in ops:
        estado["por_cp"].setdefault(o["cp"], []).append(o)
    decir("  Cartera: %d operaciones vigentes al cierre %s (%s)." % (len(ops), cob.strftime("%d-%m-%Y"), estado["origen"]))
    return estado


# ----------------------------------------------------------------------------- statement
def _valor_spec(t, i, spec):
    """(valor, columna) segun una especificacion de reportes.json > pareo:
    "Columna" | ["Col1", "Col2"] (la primera con dato) | {"columna"/"columnas", "elegir", "patron", "escala"}."""
    if spec is None:
        return None, None
    if isinstance(spec, list):
        for s in spec:
            v, j = _valor_spec(t, i, s)
            if v is not None and str(v).strip() != "":
                return v, j
        return None, None
    if isinstance(spec, str):
        j = t.col(spec)
        return (t.hoja.valor(i, j) if j is not None else None), j
    cols = spec.get("columnas") or [spec.get("columna")]
    for c in cols:
        j = t.col(c) if c else None
        v = t.hoja.valor(i, j) if j is not None else None
        if v is None or str(v).strip() == "":
            continue
        elegir = spec.get("elegir")
        if elegir == "con_porcentaje" and "%" not in str(v):
            continue
        if elegir == "distinto_de_cero" and not _num_vm(v):
            continue
        if spec.get("patron"):
            m = re.search(spec["patron"], str(v))
            if not m:
                continue
            v = m.group(1)
        if spec.get("escala") is not None:
            x = _num_vm(v)
            if x is not None and abs(x) < float(spec.get("si_menor_que", 1e300)):
                v = x * float(spec["escala"])
        return v, j
    return None, None


def operaciones_del_libro(libro, rep, fondo_archivo):
    """Operaciones del statement segun reportes.json > pareo, con la celda de cada dato."""
    conf = rep.get("pareo") or {}
    unico = fondo_archivo if len(rep.get("fondos", [])) > 1 else None
    orden_rep = conf.get("orden_fechas", "dmy")
    ops = []
    for t in detectar_tablas(libro, rep.get("tabla")):
        seccion = None
        for k in range(t.fila_enc - 1, max(t.fila_enc - 10, -1), -1):
            seccion = fondo_en_texto(" ".join(str(v) for v in t.hoja.filas[k] if isinstance(v, str)))
            if seccion:
                break
        for i in t.filas_datos():
            for tc in conf.get("tipos", []):
                if tc.get("si") and not _cumple(t, i, tc["si"]):
                    continue
                orden = tc.get("orden_fechas", orden_rep)
                ident, _ = _valor_spec(t, i, tc.get("id"))
                ident = normalizar(ident)
                if not ident:
                    continue
                fila_txt = " ".join(str(v) for v in t.hoja.filas[i] if isinstance(v, str))
                op = dict(tipo=tc["tipo"], id=ident, tabla=t, fila=i, conf=tc, orden=orden,
                          fondo=unico or fondo_en_texto(fila_txt) or seccion or fondo_archivo, celdas={})
                for campo, clave in (("td", "trade"), ("sd", "inicio"), ("md", "vencimiento")):
                    v, j = _valor_spec(t, i, tc.get(clave))
                    op[campo] = _fecha_vm(v, orden)
                    op["celdas"][campo] = j
                op["celdas"]["td_extra"] = [t.col(c) for c in tc.get("trade_tambien", []) if t.col(c) is not None]
                v, j = _valor_spec(t, i, tc.get("tasa"))
                op["tasa"], op["tasa_txt"], op["celdas"]["tasa"] = _num_vm(v), v, j
                if tc["tipo"] == "FX":
                    patas = {}
                    for cc, ca in tc.get("patas", []):
                        mon, _ = _valor_spec(t, i, cc)
                        monto, jm = _valor_spec(t, i, ca)
                        x = _num_vm(monto)
                        if mon and x is not None:
                            patas[str(mon).strip().upper()] = (abs(x), jm, x)
                    if len(patas) != 2:
                        continue
                    op["patas"] = patas
                else:
                    v, j = _valor_spec(t, i, tc.get("nominal"))
                    mon, _ = _valor_spec(t, i, tc.get("moneda"))
                    if _num_vm(v) is None:
                        continue
                    op.update(nominal=abs(_num_vm(v)), nominal_raw=_num_vm(v), moneda=str(mon or "").strip().upper())
                    op["celdas"]["nominal"] = j
                    tf = tc.get("tasa_flotante")
                    if tf:
                        op["celdas"]["tasa_flotante"] = t.col(tf.get("columna"))
                        if (tf.get("texto") or {}).get("columna"):
                            op["celdas"]["tasa_flotante_texto"] = t.col(tf["texto"]["columna"])
                if op["md"] is None:
                    continue
                ops.append(op)
                break
    return ops


# ----------------------------------------------------------------------------- pareo
def _comparar_vm(s, c, pconf):
    """Diferencias entre la operacion del statement (s) y la de cartera (c). None si no son la misma."""
    dias_max = int(pconf.get("dias_max", 10))
    rel_max = float(pconf.get("nominal_relativo_max", 0.002))
    if s["tipo"] != c["tipo"] or s["fondo"] != c["fondo"]:
        return None
    dif = {}
    if s["tipo"] == "FX":
        if set(s["patas"]) != set(c["patas"]):
            return None
        for mon, v in c["patas"].items():
            w = s["patas"][mon][0]
            if abs(w - v) / max(v, 1) > rel_max:
                return None
            if mon == c["base"]:
                if abs(w - v) > 0.005:
                    dif["nominal"] = (w, round(v, 2), mon)
            elif c.get("exacta"):
                if abs(w - v) > 0.005:
                    dif["pata_derivada"] = (w, round(v, 2), mon)
            else:
                tol = c["patas"][c["base"]] * 0.5 * 10 ** -c.get("dec_tasa", 7) + 1.0
                if abs(w - v) > tol:
                    dif["pata_derivada"] = (w, round(v, 2), mon)
        if s.get("tasa") and c.get("tasa") and s["tasa"] > 0:
            # la contraparte puede cotizar al reves (ej. 0,8547 en vez de 1,17): se compara en su sentido
            r1, r2 = s["tasa"], c["tasa"]
            inversa = abs(math.log(r1) + math.log(r2)) < abs(math.log(r1) - math.log(r2))
            objetivo = 1.0 / r2 if inversa else r2
            dec_s, dec_c = _decimales(s["tasa_txt"]), c.get("dec_tasa", 7)
            tol = 1.5 * max(10 ** -min(dec_s, 12), objetivo * 10 ** -dec_c / r2 if inversa else 10 ** -dec_c)
            if abs(r1 - objetivo) > tol + 1e-12:
                dif["tasa"] = (r1, round(objetivo, max(dec_s, 6)) if inversa else r2)
    else:
        if s["moneda"] and c["moneda"] and s["moneda"] != c["moneda"]:
            return None
        if abs(s["nominal"] - c["nominal"]) / max(c["nominal"], 1) > rel_max:
            return None
        if abs(s["nominal"] - c["nominal"]) > 0.005:
            dif["nominal"] = (s["nominal"], c["nominal"], c["moneda"])
        if s.get("tasa") is not None and c.get("tasa") is not None:
            if abs(s["tasa"] - c["tasa"]) > 0.05:
                return None
            if abs(s["tasa"] - c["tasa"]) > 0.00005:
                dif["tasa"] = (s["tasa"], c["tasa"])
        if s.get("sd") and c.get("sd") and s["sd"] != c["sd"] and abs((s["sd"] - c["sd"]).days) <= dias_max:
            dif["sd"] = (s["sd"], c["sd"])
    dm = (s["md"] - c["md"]).days
    if abs(dm) > dias_max:
        return None
    if dm:
        dif["md"] = (s["md"], c["md"])
    if s.get("td") and c.get("td"):
        d = (s["td"] - c["td"]).days
        if abs(d) > dias_max:
            return None
        if d:
            dif["td"] = (s["td"], c["td"])
    return dif


def _costo_vm(dif):
    c = 0.0
    for k, v in dif.items():
        if k in ("nominal", "pata_derivada"):
            c += 5 + min(abs(v[0] - v[1]), 100)
        elif k == "tasa":
            c += 5
        else:
            c += 1 + min(abs((v[0] - v[1]).days), 30) / 10.0
    return c


def parear_vm(stm, cart, pconf):
    """Pareo uno a uno, primero los mas parecidos. Marca ambiguos (empate con otra operacion distinta)."""
    por_fondo = {}
    for k, c in enumerate(cart):
        por_fondo.setdefault((c["fondo"], c["tipo"]), []).append(k)
    pares = []
    for j, s in enumerate(stm):
        for k in por_fondo.get((s["fondo"], s["tipo"]), []):
            d = _comparar_vm(s, cart[k], pconf)
            if d is not None:
                pares.append((_costo_vm(d), j, k, d))
    pares.sort(key=lambda x: (x[0], x[1], x[2]))
    usados_s, usados_c, res = set(), set(), []
    for costo, j, k, d in pares:
        if j in usados_s or k in usados_c:
            continue
        empate = [x for x in pares if x[1] == j and x[2] != k and x[2] not in usados_c and x[0] == costo and x[3] != d]
        usados_s.add(j)
        usados_c.add(k)
        res.append((stm[j], cart[k], d, bool(empate)))
    return res, [s for j, s in enumerate(stm) if j not in usados_s]


# ----------------------------------------------------------------------------- correccion
def _fecha_como_original(original, f, orden):
    if isinstance(original, dt.datetime):
        return original.replace(year=f.year, month=f.month, day=f.day)
    if isinstance(original, dt.date):
        return f
    s = str(original)
    nucleo = s.strip()
    nuevo = _escribir_fecha(nucleo, f, orden)
    if nuevo is None:
        return None
    ini = s[:len(s) - len(s.lstrip())]
    fin = s[len(s.rstrip()):]
    return ini + nuevo + fin


def _numero_como_original(original, x, dec=2):
    """x con el mismo tipo y formato de texto que 'original' (signo, miles, decimales, parentesis)."""
    if isinstance(original, bool) or original is None:
        return x
    if isinstance(original, int):
        return int(round(x)) if abs(x - round(x)) < 1e-9 else round(x, dec)
    if isinstance(original, float):
        return round(x, max(dec, 0))
    s = str(original)
    nucleo = s.strip()
    ini, fin = s[:len(s) - len(s.lstrip())], s[len(s.rstrip()):]
    parentesis = nucleo.startswith("(")
    limpio = nucleo.strip("()%").replace(",", "")
    d = len(limpio.split(".")[1]) if "." in limpio else 0
    cuerpo = format(abs(x), ",.%df" % d) if "," in nucleo else "%.*f" % (d, abs(x))
    if x < 0:
        cuerpo = "(%s)" % cuerpo if parentesis else "-" + cuerpo
    return ini + cuerpo + fin


CAMPOS_POLITICA = {"td": "td", "trade": "td", "fecha trade": "td", "trade date": "td",
                   "sd": "sd", "inicio": "sd", "fecha inicio": "sd", "md": "md", "vencimiento": "md",
                   "maturity": "md", "nominal": "nominal", "tasa": "tasa", "tasa_flotante": "tasa_flotante",
                   "tasa flotante": "tasa_flotante"}


def _politica_no_igualar(s, c, campo, reglas=None, origen="reportes.json > pareo > no_igualar"):
    """Regla que deja este dato como lo manda la contraparte (porque asi lo acepta el aplicativo):
    reportes.json > pareo > tipos > no_igualar (por reporte) o configuracion.json > pareo > no_igualar
    (todas las contrapartes). Devuelve la nota de la regla o None."""
    for regla in (s["conf"].get("no_igualar") if reglas is None else reglas) or []:
        if not isinstance(regla, dict) or not regla.get("activo", True):
            continue
        if CAMPOS_POLITICA.get(str(regla.get("campo", "")).strip().lower()) != campo:
            continue
        if regla.get("tipos") and s.get("tipo") not in regla["tipos"]:
            continue
        if regla.get("contrapartes") and c.get("cp") not in regla["contrapartes"]:
            continue
        if regla.get("excepto_contrapartes") and c.get("cp") in regla["excepto_contrapartes"]:
            continue
        td = c.get("td") or s.get("td")
        lim = fecha_desde_texto(regla["si_trade_antes_de"]) if regla.get("si_trade_antes_de") else None
        if regla.get("si_trade_antes_de") and (lim is None or td is None or not td < lim):
            continue
        lim = fecha_desde_texto(regla["si_trade_desde"]) if regla.get("si_trade_desde") else None
        if regla.get("si_trade_desde") and (lim is None or td is None or td < lim):
            continue
        if regla.get("operaciones") and s["id"] not in {normalizar(x) for x in regla["operaciones"]}:
            continue
        if regla.get("si") and not _cumple(s["tabla"], s["fila"], regla["si"]):
            continue
        return regla.get("_nota") or origen
    return None


def _decision_campo(ctx, rep, s, c, campo):
    """('contraparte', regla, motivo) si este dato NO se iguala a cartera; None = se iguala (lo normal).
    Manda lo aprendido del aplicativo (seguimiento); si no hay nada aprendido, la politica de reportes.json."""
    lec = (getattr(ctx, "lecciones", None) or {}).get((rep["id"], s["fondo"], s["id"], campo))
    if lec and lec.get("usar") == "contraparte":
        return "contraparte", "aprendizaje", lec.get("motivo") or "aprendido del aplicativo"
    if lec and lec.get("usar") == "cartera":
        return None
    nota = _politica_no_igualar(s, c, campo)
    if nota:
        return "contraparte", "politica", nota
    if s["conf"].get("no_igualar_global", True):
        nota = _politica_no_igualar(s, c, campo, (ctx.conf.get("pareo") or {}).get("no_igualar") or [],
                                    "configuracion.json > pareo > no_igualar")
        if nota:
            return "contraparte", "politica", nota
    return None


def _valor_original(res, t, i, j):
    """Valor que trajo la contraparte en esa celda (antes de reglas y pareo)."""
    for e in res.ediciones:
        if (e.hoja, e.fila, e.col) == (t.hoja_idx, i, j):
            return e.anterior
    return t.hoja.valor(i, j)


def _comparar_vm_forzado(s, c, pconf):
    """Segunda pasada (pareo forzado): misma contraparte, fondo, tipo y monedas; el nominal (swap) o una de
    las patas (FX) igual, y fechas cercanas. La otra pata o la tasa pueden diferir (ej. SG informa el NDF con
    otra tasa). Devuelve (costo, diferencias) o None."""
    if s["tipo"] != c["tipo"] or s["fondo"] != c["fondo"]:
        return None
    dias = int(pconf.get("dias_max_forzado", 31))
    rel = float(pconf.get("nominal_relativo_max", 0.002))
    dif, costo = {}, 0.0
    dias_md = dias
    if s["tipo"] == "FX":
        if set(s["patas"]) != set(c["patas"]):
            return None
        iguales_ = [m for m, v in c["patas"].items() if abs(s["patas"][m][0] - v) / max(v, 1) <= rel]
        if not iguales_:
            return None
        for m, v in c["patas"].items():
            if m not in iguales_:
                brecha = abs(s["patas"][m][0] - v) / max(v, 1)
                if brecha > float(pconf.get("pata_derivada_max_forzado", 0.20)):
                    return None     # la otra pata es demasiado distinta: es otra operacion
                dif["pata_derivada"] = (s["patas"][m][0], round(v, 2), m)
                costo += 2 + min(brecha * 100, 50)
        # forwards con el mismo monto son comunes: el vencimiento tiene que estar cerca (como en el pareo normal)
        dias_md = int(pconf.get("dias_max", 10))
    else:
        if s.get("moneda") and c.get("moneda") and s["moneda"] != c["moneda"]:
            return None
        if abs(s["nominal"] - c["nominal"]) / max(c["nominal"], 1) > rel:
            return None
        if s.get("tasa") is not None and c.get("tasa") is not None and abs(s["tasa"] - c["tasa"]) > 0.00005:
            dif["tasa"] = (s["tasa"], c["tasa"])
            costo += 2 + min(abs(s["tasa"] - c["tasa"]) * 10, 30)
    for campo in ("md", "td"):
        if s.get(campo) is None or c.get(campo) is None:
            if campo == "md":
                return None
            continue
        dd = abs((s[campo] - c[campo]).days)
        if dd > (dias_md if campo == "md" else dias):
            return None
        if dd:
            dif[campo] = (s[campo], c[campo])
            costo += 1 + dd / 10.0
    if s.get("sd") and c.get("sd") and s["sd"] != c["sd"] and abs((s["sd"] - c["sd"]).days) <= dias:
        dif["sd"] = (s["sd"], c["sd"])
    return costo, dif


def parear_forzado(stm, cart, pconf, memoria=None, clave=None):
    """Para lo que no pareo exacto: 1) por historial (el N de operacion de la contraparte ya se pareo con esa
    operacion de cartera en dias anteriores) y 2) por parecido (nominal o una pata igual y fechas cercanas).
    Solo se parea si no hay empate. Devuelve [(s, c, dif, motivo)]."""
    pares, usados_s, usados_c = [], set(), set()
    por_id = {}
    for k, c in enumerate(cart):
        por_id.setdefault(c["id"], []).append(k)
    for j, s in enumerate(stm):
        tran = (memoria or {}).get(clave(s)) if clave else None
        if not tran:
            continue
        for k in por_id.get(tran, []):
            c = cart[k]
            if k in usados_c or c["fondo"] != s["fondo"] or c["tipo"] != s["tipo"]:
                continue
            r = _comparar_vm_forzado(s, c, dict(pconf, dias_max_forzado=int(pconf.get("dias_max_forzado", 31)) * 3))
            dif = r[1] if r else {}
            if r is None:       # mismo N de operacion pero ya no se parece: se parea sin corregir nada
                dif = {}
            usados_s.add(j)
            usados_c.add(k)
            pares.append((s, c, dif, "historial: el N %s ya se pareo con la operacion %s de Vmetrix" % (s["id"], tran),
                          r is not None))
            break
    candidatos = []
    for j, s in enumerate(stm):
        if j in usados_s:
            continue
        for k, c in enumerate(cart):
            if k in usados_c:
                continue
            r = _comparar_vm_forzado(s, c, pconf)
            if r is not None:
                candidatos.append((r[0], j, k, r[1]))
    candidatos.sort(key=lambda x: (x[0], x[1], x[2]))
    for costo, j, k, d in candidatos:
        if j in usados_s or k in usados_c:
            continue
        empate = [x for x in candidatos if x[1] == j and x[2] != k and x[2] not in usados_c and abs(x[0] - costo) < 1e-9]
        empate += [x for x in candidatos if x[2] == k and x[1] != j and x[1] not in usados_s and abs(x[0] - costo) < 1e-9]
        if empate:
            continue
        usados_s.add(j)
        usados_c.add(k)
        partes = []
        if "pata_derivada" in d:
            partes.append("pata %s distinta" % d["pata_derivada"][2])
        if "tasa" in d:
            partes.append("tasa distinta")
        if any(x in d for x in ("td", "md", "sd")):
            partes.append("fechas distintas")
        pares.append((stm[j], cart[k], d, "parecido: %s" % (", ".join(partes) or "dentro de tolerancia"), True))
    return pares


def pareo_archivo(ctx, r, libro, res, editar=True):
    """Parea el archivo con la cartera y (si editar) corrige en memoria. Devuelve un resumen."""
    est = ctx.pareo
    rep = r.reporte
    conf = rep.get("pareo") or {}
    pconf = ctx.conf.get("pareo") or {}
    cp = conf.get("contraparte_vmetrix")
    if not est or not est.get("ok") or not cp or not conf.get("tipos"):
        return None
    stm = operaciones_del_libro(libro, rep, r.fondo)
    fondos = {s["fondo"] for s in stm} | ({r.fondo} if len(rep.get("fondos", [])) > 1 else set("ABCDE"))
    tipos = {tc.get("tipo") for tc in conf.get("tipos", [])}
    for f in fondos:
        est["cps_fondos"].add((cp, f))
        for tp in tipos:
            est.setdefault("cobertura", set()).add((cp, f, tp))
            # statement armado con el de un cierre anterior: no sirve para pedir contratos faltantes
            est.setdefault("cobertura_arrastre" if getattr(r, "arrastre", None) else "cobertura_real", set()).add(
                (cp, f, tp))
    cart = est["por_cp"].get(cp, [])
    pares, sin = parear_vm(stm, cart, pconf)
    pares = [(s, c, d, amb, "") for s, c, d, amb in pares]
    if sin and pconf.get("pareo_forzado", True):
        usados = {id(c) for _, c, _, _, _ in pares}
        libres = [c for c in cart if id(c) not in usados]
        forz = parear_forzado(sin, libres, pconf, est.get("memoria"),
                              lambda s: (rep["id"], s["fondo"], s["id"]))
        ids = {id(s) for s, _, _, _, _ in forz}
        sin = [s for s in sin if id(s) not in ids]
        for s, c, d, motivo, parecido in forz:
            pares.append((s, c, d if parecido else {}, False, motivo))
            est.setdefault("forzados", []).append(dict(
                contraparte=rep.get("contraparte", ""), reporte=rep["id"], archivo=(r.salida or r.archivo).name,
                fondo=s["fondo"], operacion=s["id"], op_cartera=c["id"], mov=mov_operacion(ctx, c), referencia=c["ref"],
                motivo=motivo))
    corregir = set(pconf.get("corregir", ["fechas", "nominal", "tasa"]))
    nominal_max = float(pconf.get("nominal_correccion_max", 1.0))
    resumen = Counter()
    base = dict(contraparte=rep.get("contraparte", ""), reporte=rep["id"], archivo=(r.salida or r.archivo).name)

    def anotar(lista, s, c, campo, antes, despues, rojo, motivo=""):
        lista.append(dict(base, fondo=s["fondo"], operacion=s["id"], op_cartera=c["id"] if c else "",
                          mov=mov_operacion(ctx, c),
                          referencia=c["ref"] if c else "", campo=campo, antes=normalizar(antes),
                          despues=normalizar(despues), rojo=rojo, motivo=motivo))

    def editar_celda(s, j, nuevo, campo, antes, despues, rojo, c):
        t, i = s["tabla"], s["fila"]
        if j is None or nuevo is None:
            anotar(est["no_corregidos"], s, c, campo, antes, despues, rojo, "no encontre la columna o el formato")
            return
        if (t.hoja_idx, i, j) in res.protegidas:
            anotar(est["no_corregidos"], s, c, campo, antes, despues, False,
                   "manda el valor esperado de ajustes_operaciones.json")
            return
        n = len(res.ediciones)
        res.editar(t, i, j, nuevo, "vmetrix", "cartera Vmetrix op %s" % c["id"], formato=MANTENER_FORMATO)
        if len(res.ediciones) > n:
            anotar(est["cambios"], s, c, campo, antes, despues, rojo)
            resumen[campo] += 1

    def dejar_contraparte(s, c, j, campo_txt, antes, cartera, regla, motivo):
        """El dato se deja como lo manda la contraparte (politica o aprendizaje): si una regla lo habia
        cambiado, vuelve al original."""
        t, i = s["tabla"], s["fila"]
        if j is None:
            return
        if (t.hoja_idx, i, j) in res.protegidas:
            return
        original = _valor_original(res, t, i, j)
        actual = t.hoja.valor(i, j)
        if not (type(actual) == type(original) and actual == original):
            res.editar(t, i, j, original, regla, motivo)
        est.setdefault("respetados", []).append(dict(
            base, fondo=s["fondo"], operacion=s["id"], op_cartera=c["id"], mov=mov_operacion(ctx, c),
            referencia=c["ref"], campo=campo_txt, antes=normalizar(antes), despues=normalizar(cartera),
            regla=regla, motivo=motivo))

    for s, c, d, ambiguo, forzado in pares:
        est["pareadas"].add(id(c))
        if not editar:
            continue
        t, i, celdas = s["tabla"], s["fila"], s["celdas"]
        decision = {}
        for campo in ("td", "sd", "md", "nominal", "tasa", "tasa_flotante"):
            dec = _decision_campo(ctx, rep, s, c, campo)
            if dec:
                decision[campo] = dec
        # Fechas que la politica o el aprendizaje dejan como las manda la contraparte (aunque no difieran
        # despues de las reglas: si una regla las cambio, vuelven al original)
        for campo in ("td", "sd", "md"):
            j = celdas.get(campo)
            if campo in decision and j is not None and c.get(campo) is not None:
                crudo = _fecha_vm(_valor_original(res, t, i, j), s["orden"])
                if crudo is not None and crudo != c[campo]:
                    dejar_contraparte(s, c, j, CAMPO_TEXTO[campo], crudo, c[campo], decision[campo][1],
                                      decision[campo][2])
                    if campo == "td":
                        for jx in celdas.get("td_extra", []):
                            dejar_contraparte(s, c, jx, "Fecha trade (%s)" % normalizar(t.hoja.valor(t.fila_enc, jx)),
                                              crudo, c[campo], decision[campo][1], decision[campo][2])
        if "tasa_flotante" in decision:
            for clave_tf in ("tasa_flotante", "tasa_flotante_texto"):
                j = celdas.get(clave_tf)
                if j is not None and (t.hoja_idx, i, j) not in res.protegidas:
                    original = _valor_original(res, t, i, j)
                    actual = t.hoja.valor(i, j)
                    if not (type(actual) == type(original) and actual == original):
                        dejar_contraparte(s, c, j, CAMPO_TEXTO["tasa_flotante"], original, actual,
                                          decision["tasa_flotante"][1], decision["tasa_flotante"][2])
        extra = [j for j in celdas.get("td_extra", [])
                 if _fecha_vm(t.hoja.valor(i, j), s["orden"]) not in (None, c["td"])] if "td" not in decision else []
        if not d and not extra and not (s["conf"].get("tasa_flotante") and c.get("afp_paga_fija")):
            continue
        if ambiguo:
            for campo, v in d.items():
                anotar(est["no_corregidos"], s, c, CAMPO_TEXTO.get(campo, campo), v[0], v[1], campo in ("nominal", "tasa"),
                       "hay otra operacion igual de parecida en la cartera: no se toco")
            continue
        for campo in ("td", "sd", "md"):
            if campo not in d or campo in decision:
                continue
            if forzado and abs((d[campo][0] - d[campo][1]).days) > int(pconf.get("dias_max", 10)):
                anotar(est["no_corregidos"], s, c, CAMPO_TEXTO[campo], d[campo][0], d[campo][1], False,
                       "pareo forzado (%s): diferencia de fecha mayor a dias_max, no se toca" % forzado)
                continue
            if "fechas" not in corregir:
                anotar(est["no_corregidos"], s, c, CAMPO_TEXTO[campo], d[campo][0], d[campo][1], False,
                       "correccion de fechas desactivada en configuracion.json")
                continue
            j = celdas.get(campo)
            nuevo = _fecha_como_original(t.hoja.valor(i, j), d[campo][1], s["orden"]) if j is not None else None
            editar_celda(s, j, nuevo, CAMPO_TEXTO[campo], d[campo][0], d[campo][1], False, c)
        # columnas que deben llevar la misma fecha de trade (ej. Eff. Date de Deutsche)
        for j in (celdas.get("td_extra", []) if "td" not in decision else []):
            actual = _fecha_vm(t.hoja.valor(i, j), s["orden"])
            if "fechas" in corregir and actual is not None and actual != c["td"]:
                nuevo = _fecha_como_original(t.hoja.valor(i, j), c["td"], s["orden"])
                editar_celda(s, j, nuevo, "Fecha trade (%s)" % normalizar(t.hoja.valor(t.fila_enc, j)), actual, c["td"],
                             False, c)
        if "nominal" in d:
            w, v, mon = d["nominal"]
            campo = "Nominal %s" % mon
            if forzado:
                anotar(est["no_corregidos"], s, c, campo, w, v, True, "pareo forzado (%s): el nominal no se toca" % forzado)
            elif "nominal" in decision:
                anotar(est["no_corregidos"], s, c, campo, w, v, True, decision["nominal"][2])
            elif abs(w - v) <= nominal_max and "nominal" in corregir:
                if s["tipo"] == "FX":
                    _, j, crudo = s["patas"][mon]
                else:
                    j, crudo = celdas.get("nominal"), s["nominal_raw"]
                original = t.hoja.valor(i, j) if j is not None else None
                nuevo = _numero_como_original(original, math.copysign(v, crudo if crudo else 1))
                editar_celda(s, j, nuevo, campo, crudo, math.copysign(v, crudo if crudo else 1), True, c)
            else:
                anotar(est["no_corregidos"], s, c, campo, w, v, True,
                       "diferencia de %s: mas que redondeo, revisar con la contraparte" % normalizar(round(abs(w - v), 2)))
        if "pata_derivada" in d:
            w, v, mon = d["pata_derivada"]
            campo = "Nominal %s (segunda pata)" % mon
            if forzado:
                pass        # se informa en la hoja Pareo forzado (ej. SG informa el NDF con otra tasa)
            elif not c.get("exacta"):
                anotar(est["no_corregidos"], s, c, campo, w, v, True,
                       "Vmetrix no trae este monto exacto; si el aplicativo no la lee, va en ajustes_operaciones.json")
            elif "nominal" in decision:
                anotar(est["no_corregidos"], s, c, campo, w, v, True, decision["nominal"][2])
            elif abs(w - v) <= nominal_max and "nominal" in corregir:
                _, j, crudo = s["patas"][mon]
                original = t.hoja.valor(i, j) if j is not None else None
                nuevo = _numero_como_original(original, math.copysign(v, crudo if crudo else 1))
                editar_celda(s, j, nuevo, campo, crudo, math.copysign(v, crudo if crudo else 1), True, c)
            else:
                anotar(est["no_corregidos"], s, c, campo, w, v, True,
                       "diferencia de %s: mas que redondeo, revisar con la contraparte" % normalizar(round(abs(w - v), 2)))
        if "tasa" in d:
            r1, r2 = d["tasa"]
            puede = (s["tipo"] == "FX" and s["conf"].get("corregir_tasa", False) and "nominal" not in d
                     and "pata_derivada" not in d and "tasa" in corregir and not forzado and "tasa" not in decision)
            if puede:
                j = celdas.get("tasa")
                original = t.hoja.valor(i, j) if j is not None else None
                nuevo = _numero_como_original(original, r2, _decimales(r2)) if isinstance(original, str) else r2
                editar_celda(s, j, nuevo, "Tasa", r1, r2, True, c)
            elif not forzado:
                anotar(est["no_corregidos"], s, c, "Tasa", r1, r2, True,
                       "tasa distinta a la de cartera (en este reporte solo se informa)")
        tf = s["conf"].get("tasa_flotante")
        if tf and c.get("afp_paga_fija") and "tasa_flotante" not in decision:
            j = celdas.get("tasa_flotante")
            actual = t.hoja.valor(i, j) if j is not None else None
            objetivo = tf.get("valor", 0)
            if actual is not None and _num_vm(actual) not in (None, float(objetivo)):
                nuevo = str(objetivo) if isinstance(actual, str) else objetivo
                editar_celda(s, j, nuevo, "Tasa pata flotante (%s)" % tf.get("columna"), actual, objetivo, True, c)
            tx = tf.get("texto")
            j2 = celdas.get("tasa_flotante_texto")
            actual2 = t.hoja.valor(i, j2) if (tx and j2 is not None) else None
            if isinstance(actual2, str) and tx.get("patron"):
                nuevo2 = re.sub(tx["patron"], tx.get("reemplazo", ""), actual2)
                if nuevo2 != actual2:
                    editar_celda(s, j2, nuevo2, "Tasa pata flotante (%s)" % tx.get("columna"), actual2, nuevo2, True, c)
    if editar:
        for s, c, d, ambiguo, forzado in pares:
            _foto_par(ctx, rep, r, res, s, c, forzado)
    for s in sin:                   # tambien si el archivo ya estaba preparado (antes quedaba la hoja vacia)
        nota = ""
        if getattr(r, "arrastre", None) and s.get("md") is not None and s["md"] <= est["cob"]:
            nota = "vence el %s: viene del statement del cierre anterior" % s["md"].strftime("%d-%m-%Y")
        elif s.get("md") is not None and s["md"] <= ctx.hoy:
            nota = "liquida el %s (hoy o antes): la cartera de Vmetrix ya no la trae" % s["md"].strftime("%d-%m-%Y")
        est["sin_cartera"].append(dict(base, fondo=s["fondo"], operacion=s["id"], tipo=s["tipo"],
                                       trade=s.get("td"), vencimiento=s.get("md"), nota=nota))
    if editar:
        _marcar_json_cubierto(ctx, rep, r.fondo, libro, [(s, c, d, a) for s, c, d, a, _ in pares], est)
    est["archivos"].append(dict(base, operaciones=len(stm), pareadas=len(pares), sin_cartera=len(sin),
                                cambios=sum(resumen.values()), nuevo=editar,
                                forzadas=sum(1 for p in pares if p[4])))
    return resumen, len(stm), len(pares), len(sin)


def _foto_par(ctx, rep, r, res, s, c, forzado):
    """Como quedo cada dato de la operacion en 02_Para_Cargar (para el seguimiento con el aplicativo):
    solo los datos donde la contraparte y la cartera no coinciden."""
    t, i, celdas = s["tabla"], s["fila"], s["celdas"]
    campos = []
    for campo in ("td", "sd", "md"):
        j = celdas.get(campo)
        if j is None or c.get(campo) is None:
            continue
        crudo = _fecha_vm(_valor_original(res, t, i, j), s["orden"])
        final = _fecha_vm(t.hoja.valor(i, j), s["orden"])
        if crudo is None or crudo == c[campo]:
            continue
        cargado = "cartera" if final == c[campo] else ("contraparte" if final == crudo else "otro")
        campos.append(dict(campo=campo, contraparte=normalizar(crudo), cartera=normalizar(c[campo]), cargado=cargado))
    if s["tipo"] != "FX" and celdas.get("nominal") is not None:
        crudo = _num_vm(_valor_original(res, t, i, celdas["nominal"]))
        final = _num_vm(t.hoja.valor(i, celdas["nominal"]))
        if crudo is not None and abs(abs(crudo) - c["nominal"]) > 0.005:
            cargado = "cartera" if final is not None and abs(abs(final) - c["nominal"]) <= 0.005 else "contraparte"
            campos.append(dict(campo="nominal", contraparte=normalizar(abs(crudo)), cartera=normalizar(c["nominal"]),
                               cargado=cargado))
    j = celdas.get("tasa_flotante")
    if j is not None:
        crudo, final = _num_vm(_valor_original(res, t, i, j)), _num_vm(t.hoja.valor(i, j))
        if crudo is not None and final is not None and abs(crudo - final) > 1e-9:
            campos.append(dict(campo="tasa_flotante", contraparte=normalizar(crudo), cartera=normalizar(final),
                               cargado="cartera"))
    ctx.pareo.setdefault("foto", []).append(dict(
        reporte=rep["id"], fondo=s["fondo"], archivo=(r.salida or r.archivo).name, operacion=s["id"],
        tran=c["id"], externo=c.get("id_externo", ""), tipo=s["tipo"], cp=c["cp"],
        td=normalizar(c.get("td")), md=normalizar(c.get("md")), forzado=forzado or "", campos=campos))


def _marcar_json_cubierto(ctx, rep, fondo, libro, pares, est):
    """Valores de ajustes_operaciones.json que Vmetrix ya entrega (se podrian borrar del JSON)."""
    ajustes = ajustes_del_reporte(ctx, rep, fondo)
    if not ajustes:
        return
    valores = {}
    for s, c, d, amb in pares:
        t, i = s["tabla"], s["fila"]
        for campo, attr in (("td", "td"), ("sd", "sd"), ("md", "md")):
            j = s["celdas"].get(campo)
            if j is not None and c.get(attr):
                valores[(t.hoja_idx, i, j)] = c[attr]
        if s["tipo"] == "FX":
            for mon in ([c["base"]] + ([m for m in c["patas"] if m != c["base"]] if c.get("exacta") else [])):
                if mon in s["patas"]:
                    valores[(t.hoja_idx, i, s["patas"][mon][1])] = c["patas"][mon]
        elif s["celdas"].get("nominal") is not None:
            valores[(t.hoja_idx, i, s["celdas"]["nominal"])] = c["nominal"]
    tablas = detectar_tablas(libro, rep.get("tabla"))
    col_id = (rep.get("tabla") or {}).get("columna_id")
    for a in ajustes:
        for t, i, j in ubicar_ajuste(tablas, a, col_id):
            v = valores.get((t.hoja_idx, i, j))
            if v is None:
                continue
            esperado = a.get("valor_correcto")
            if isinstance(v, dt.date):
                ok = fecha_desde_texto(esperado) == v or _fecha_vm(esperado) == v
            else:
                x = _num_vm(esperado)
                ok = x is not None and abs(abs(x) - v) < 0.005
            if ok:
                est["cubiertos"][id_ajuste(a)] = a


def pareo_solo_lectura(ctx, r, ruta):
    """Archivo preparado en una ejecucion anterior: solo se parea (para el informe), sin tocarlo."""
    if not ctx.pareo or not ctx.pareo.get("ok") or not (r.reporte.get("pareo") or {}).get("tipos"):
        return
    try:
        pareo_archivo(ctx, r, Libro(ruta), Resultado(), editar=False)
    except Exception as e:
        LOG.warning("Pareo de solo lectura %s: %s", ruta.name, e)


# ----------------------------------------------------------------------------- informe
def mov_operacion(ctx, c):
    """Numero con que el aplicativo muestra la operacion (mov_operacion = base + Tran Deal de Vmetrix)."""
    if not c or not c.get("es_deal"):
        return ""
    base = (ctx.conf.get("vmetrix") or {}).get("mov_operacion_base", 30000000)
    try:
        return int(base) + int(str(c["id"]).strip())
    except (TypeError, ValueError):
        return ""


def _filas_sin_statement(ctx):
    est = ctx.pareo
    filas, sin_archivo = [], Counter()
    configurados = {(rep.get("pareo") or {}).get("contraparte_vmetrix") for rep in ctx.reportes}
    cobertura = est.get("cobertura") or set()
    for c in est["ops"]:
        if id(c) in est["pareadas"] or c["cp"] not in configurados:
            continue
        if (c["cp"], c["fondo"], c["tipo"]) not in cobertura:
            # no llego (o no se proceso) el statement de ese tipo (FX o swap) para ese fondo
            sin_archivo[(c["cp"], c["fondo"], c["tipo"])] += 1
            continue
        filas.append(c)
    return filas, sin_archivo


def contrapartes_del_otro_proceso(ctx):
    """Codigos Vmetrix configurados en el reportes.json del otro proceso (nacionales <-> extranjeros), para no
    marcarlos como contrapartes nuevas. Busca las carpetas hermanas de la del proceso (Diario\\Nacional,
    Diario\\Colaterales) que tengan Json\\reportes.json."""
    salida = set()
    try:
        propio = Path(ctx.dir_json).resolve()
        for d in propio.parent.parent.iterdir():
            j = d / "Json"
            try:
                if not d.is_dir() or j.resolve() == propio or not (j / "reportes.json").is_file():
                    continue
                datos = json.loads((j / "reportes.json").read_text(encoding="utf-8-sig"))
            except Exception:
                continue
            reps = datos.get("reportes", []) if isinstance(datos, dict) else datos
            for rep in reps or []:
                cp = ((rep or {}).get("pareo") or {}).get("contraparte_vmetrix") if isinstance(rep, dict) else None
                if cp:
                    salida.add(cp)
    except Exception:
        pass
    return salida


def informe_pareo(ctx, ranuras):
    """Excel Pareo_AAAA-MM-DD_HHMM.xlsx + correo con los cambios (nominal y tasa en rojo)."""
    est = ctx.pareo
    if est is None:
        return
    conf = ctx.conf.get("correo_informe") or {}
    hora = dt.datetime.now()
    sin_stm, sin_archivo = _filas_sin_statement(ctx) if est.get("ok") else ([], Counter())
    configurados = {(rep.get("pareo") or {}).get("contraparte_vmetrix") for rep in ctx.reportes}
    ignorar = set(ctx.conf.get("pareo", {}).get("contrapartes_ignorar", [])) | contrapartes_del_otro_proceso(ctx)
    nuevas = {cp: n for cp, n in est.get("extranjeras", {}).items() if cp not in configurados and cp not in ignorar}
    ruta_xlsx = ctx.dia / ("Pareo_Vmetrix_%s_%s.xlsx" % (ctx.hoy.strftime("%Y-%m-%d"), hora.strftime("%H%M%S")))
    try:
        _excel_pareo(ctx, ruta_xlsx, est, sin_stm, sin_archivo, nuevas)
    except Exception as e:
        decir("  No pude escribir %s: %s" % (ruta_xlsx.name, e))
        ruta_xlsx = None
    html = _html_pareo(ctx, est, sin_stm, sin_archivo, nuevas, ranuras)
    try:
        (ctx.dia / ("Pareo_Vmetrix_%s_%s.html" % (ctx.hoy.strftime("%Y-%m-%d"), hora.strftime("%H%M%S")))).write_text(
            html, encoding="utf-8")
    except Exception:
        pass
    rojos = sum(1 for x in est["cambios"] if x["rojo"]) + sum(1 for x in est["no_corregidos"] if x["rojo"])
    if est.get("ok"):
        decir("  Pareo Vmetrix: %d cambios (%d de nominal o tasa), %d sin corregir, %d de cartera que la contraparte no mando."
              % (len(est["cambios"]), sum(1 for x in est["cambios"] if x["rojo"]), len(est["no_corregidos"]), len(sin_stm)))
    else:
        decir("  Pareo Vmetrix NO se hizo (%s). Los archivos quedaron solo con reglas y JSON." % est.get("error", "sin cartera"))
    if not conf.get("activo", True) or not conf.get("para"):
        return ruta_xlsx
    if not getattr(ctx, "preparados_ahora", 1):
        decir("  Correo no enviado: esta ejecucion no preparo archivos nuevos (vale el informe de la ejecucion "
              "anterior; este queda en %s)." % (ruta_xlsx.name if ruta_xlsx else "la carpeta del dia"))
        return ruta_xlsx
    asunto = "%sColaterales %s: pareo con Vmetrix - %d cambios%s" % (
        "[PRUEBA] " if ctx.args.prueba else "", ctx.hoy.strftime("%d-%m-%Y"), len(est["cambios"]),
        " (%d en rojo)" % rojos if rojos else "")
    if not est.get("ok"):
        asunto = "%sColaterales %s: SIN pareo con Vmetrix" % ("[PRUEBA] " if ctx.args.prueba else "",
                                                             ctx.hoy.strftime("%d-%m-%Y"))
    if any(getattr(r, "preparado_antes", None) for r in ranuras.values()):
        asunto += " (solo archivos nuevos de esta ejecucion)"
    n_arr = sum(1 for r in ranuras.values() if getattr(r, "arrastre", None))
    if n_arr:
        asunto += " - %d statement(s) del cierre anterior" % n_arr
    try:
        import win32com.client
        ol = win32com.client.Dispatch("Outlook.Application")
        correo = ol.CreateItem(0)
        correo.To = "; ".join(conf["para"])
        correo.Subject = asunto
        correo.HTMLBody = html
        if ruta_xlsx and ruta_xlsx.exists():
            correo.Attachments.Add(mostrar(ruta_xlsx))
        if conf.get("enviar", True):
            correo.Send()
            decir("  Informe enviado a %s." % ", ".join(conf["para"]))
        else:
            correo.Display()
            decir("  Informe abierto en Outlook (sin enviar).")
    except Exception as e:
        decir("  No pude enviar el correo del informe (%s). Queda en %s." % (e, ruta_xlsx.name if ruta_xlsx else "la carpeta"))
    return ruta_xlsx


def _excel_pareo(ctx, ruta, est, sin_stm, sin_archivo, nuevas):
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill
    from openpyxl.utils import get_column_letter
    wb = Workbook()
    wb.remove(wb.active)
    rojo = Font(color="C00000", bold=True)

    def hoja(nombre, enc, filas, col_rojo=None):
        ws = wb.create_sheet(nombre)
        ws.append(enc)
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF")
            c.fill = PatternFill("solid", fgColor="1F3864")
        for f in filas:
            valores = f[:-1] if col_rojo else f
            ws.append([v if isinstance(v, (int, float)) and not isinstance(v, bool) else
                       ("" if v is None else str(v)) for v in valores])
            if col_rojo and f[-1]:
                for c in ws[ws.max_row]:
                    c.font = rojo
        for j in range(1, ws.max_column + 1):
            largo = max((len(str(ws.cell(row=i, column=j).value or "")) for i in range(1, min(ws.max_row, 300) + 1)),
                        default=8)
            ws.column_dimensions[get_column_letter(j)].width = min(max(10, largo + 2), 60)
        ws.freeze_panes = "A2"
        if ws.max_row > 1:
            ws.auto_filter.ref = ws.dimensions

    enc = ["Contraparte", "Reporte", "Fondo", "Archivo", "N operacion contraparte", "Op. Vmetrix", "mov_operacion",
           "Inst. Reference", "Campo", "Valor contraparte", "Valor cartera", "Motivo"]
    fila = lambda x: [x["contraparte"], x["reporte"], x["fondo"], x["archivo"], x["operacion"], x["op_cartera"],
                      x.get("mov", ""), x["referencia"], x["campo"], x["antes"], x["despues"], x.get("motivo", ""),
                      x["rojo"]]
    hoja("Cambios", enc[:-1], [fila(x)[:-2] + [x["rojo"]] for x in est["cambios"]], col_rojo=True)
    hoja("No corregido", enc, [fila(x) for x in est["no_corregidos"]], col_rojo=True)
    hoja("No lo envia la contraparte", ["Contraparte (Vmetrix)", "Fondo", "Op. Vmetrix", "mov_operacion", "ID externo",
                                       "Inst. Reference", "Tipo", "Trade", "Vencimiento", "Nominal"],
         [[c["cp"], c["fondo"], c["id"], mov_operacion(ctx, c), c.get("id_externo", ""), c["ref"], c["tipo"], c["td"],
           c["md"], c["patas"][c["base"]] if c["tipo"] == "FX" else c["nominal"]] for c in sin_stm]
         + [[cp, f, "", "", "", "Falta el statement %s de este fondo hoy (%d operaciones en cartera)" % (tp, n), tp, "",
             "", ""] for (cp, f, tp), n in sorted(sin_archivo.items())])
    hoja("Statement sin cartera", ["Contraparte", "Reporte", "Fondo", "Archivo", "N operacion", "Tipo", "Trade",
                                   "Vencimiento", "Nota"],
         [[x["contraparte"], x["reporte"], x["fondo"], x["archivo"], x["operacion"], x["tipo"], x["trade"],
           x["vencimiento"], x.get("nota", "")] for x in est["sin_cartera"]])
    hoja("JSON ya cubierto", ["Reporte", "Fondo", "N operacion", "Columna", "Valor esperado", "Comentario"],
         [[a.get("reporte"), a.get("fondo"), a.get("operacion"), a.get("columna"), normalizar(a.get("valor_correcto")),
           "Vmetrix entrega este mismo valor: se puede borrar de ajustes_operaciones.json"]
          for a in est["cubiertos"].values()])
    hoja("Contrapartes nuevas", ["Codigo Vmetrix", "Operaciones vigentes", "Que hacer"],
         [[cp, n, "Contraparte extranjera sin statement configurado en reportes.json"] for cp, n in sorted(nuevas.items())])
    hoja("Archivos", ["Contraparte", "Reporte", "Archivo", "Operaciones", "Pareadas", "De ellas forzadas",
                      "Sin cartera", "Cambios"],
         [[a["contraparte"], a["reporte"], a["archivo"], a["operaciones"], a["pareadas"], a.get("forzadas", 0),
           a["sin_cartera"], a["cambios"]] for a in est["archivos"]])
    hoja("Pareo forzado", ["Contraparte", "Reporte", "Fondo", "Archivo", "N operacion contraparte", "Op. Vmetrix",
                           "mov_operacion", "Inst. Reference", "Como se pareo"],
         [[x["contraparte"], x["reporte"], x["fondo"], x["archivo"], x["operacion"], x["op_cartera"], x.get("mov", ""),
           x["referencia"], x["motivo"]] for x in est.get("forzados", [])])
    hoja("Dato de la contraparte", ["Contraparte", "Reporte", "Fondo", "Archivo", "N operacion contraparte",
                                    "Op. Vmetrix", "mov_operacion", "Inst. Reference", "Campo", "Valor contraparte (se deja)",
                                    "Valor cartera", "Por que", "Detalle"],
         [[x["contraparte"], x["reporte"], x["fondo"], x["archivo"], x["operacion"], x["op_cartera"], x.get("mov", ""),
           x["referencia"], x["campo"], x["antes"], x["despues"],
           "politica de reportes.json" if x["regla"] == "politica" else "aprendido del aplicativo", x["motivo"]]
          for x in est.get("respetados", [])])
    hoja("Seguimiento aplicativo", ["Cierre", "Contraparte", "Fondo", "mov_operacion", "Op. Vmetrix", "Inst. Reference",
                                    "Reporte", "N operacion contraparte", "Situacion", "Detalle"],
         [[normalizar(x["cierre"]), x["contraparte"], x["fondo"], x["mov"], x["tran"], x["referencia"], x["reporte"],
           x["operacion"], x["situacion"], x["detalle"]] for x in getattr(ctx, "seguimiento", [])]
         + [[normalizar(T), "", "", "", "", "", "", "", "Resumen: %d sin valor de la contraparte" % n, texto]
            for T, n, texto, info in getattr(ctx, "seguimiento_resumen", [])])
    wb.save(str(ruta))


def _html_pareo(ctx, est, sin_stm, sin_archivo, nuevas, ranuras=None):
    import html as _h
    e = lambda v: _h.escape("" if v is None else str(v))
    th = "border:1px solid #BFBFBF;padding:4px 8px;background:#1F3864;color:#FFFFFF;text-align:left;"
    td = "border:1px solid #BFBFBF;padding:4px 8px;"
    tabla = lambda enc, filas: (
        "<table style='border-collapse:collapse;font-family:Calibri,Arial;font-size:10pt;'><tr>%s</tr>%s</table>"
        % ("".join("<th style='%s'>%s</th>" % (th, e(c)) for c in enc),
           "".join("<tr>%s</tr>" % "".join("<td style='%s%s'>%s</td>" % (td, "color:#C00000;font-weight:bold;" if rojo else "",
                                                                       e(v)) for v in f) for f, rojo in filas)))
    p = []
    p.append("<div style='font-family:Calibri,Arial;font-size:11pt;'>")
    arrastres = [r for r in (ranuras or {}).values() if getattr(r, "arrastre", None) and r.arrastre.get("cob_base")]
    if arrastres:
        p.append("<p><b style='color:#C00000'>Sin statement de hoy (se uso el del cierre anterior con las fechas de "
                 "hoy; el MTM es el del cierre anterior)</b>:</p>")
        p.append(tabla(["Contraparte", "Fondo", "Archivo base", "Cierre base", "Cierre nuevo", "Vencen"],
                       [((r.reporte.get("contraparte", ""), r.fondo, r.arrastre.get("base"),
                          r.arrastre.get("cob_base"), r.arrastre.get("cob_nuevo"),
                          len(r.arrastre.get("vencen") or [])), False)
                        for r in sorted(arrastres, key=lambda x: (x.reporte.get("contraparte", ""), x.fondo))]))
    if not est.get("ok"):
        p.append("<p><b style='color:#C00000'>No se hizo el pareo con Vmetrix</b>: %s.<br>Los archivos se prepararon "
                 "como antes (reglas y ajustes_operaciones.json).</p></div>" % e(est.get("error")))
        return "".join(p)
    rojos = [x for x in est["cambios"] if x["rojo"]]
    fechas = [x for x in est["cambios"] if not x["rojo"]]
    p.append("<p>Cierre %s | cartera: %d operaciones (%s) | archivos pareados: %d.</p>" % (
        est["cob"].strftime("%d-%m-%Y"), len(est["ops"]), e(est["origen"]), len(est["archivos"])))
    p.append("<p><b>Cambios hechos en 02_Para_Cargar: %d</b> (nominal o tasa: <b style='color:#C00000'>%d</b>; "
             "fechas: %d).</p>" % (len(est["cambios"]), len(rojos), len(fechas)))
    resumen = Counter((x["contraparte"], x["campo"].split(" (")[0]) for x in est["cambios"])
    if resumen:
        p.append(tabla(["Contraparte", "Campo", "Cambios"], [((cp, campo, n), campo.startswith(("Nominal", "Tasa")))
                                                            for (cp, campo), n in sorted(resumen.items())]))
    detalle = rojos + fechas[:max(0, 80 - len(rojos))]
    enc = ["Contraparte", "Fondo", "N operacion", "mov_operacion", "Campo", "Antes", "Despues"]
    if detalle:
        p.append("<p><b>Detalle</b>%s</p>" % (" (primeros %d; el resto en el Excel adjunto)" % len(detalle)
                                              if len(detalle) < len(est["cambios"]) else ""))
        p.append(tabla(enc, [((x["contraparte"], x["fondo"], x["operacion"], x.get("mov") or x["op_cartera"], x["campo"],
                               x["antes"],
                               x["despues"]), x["rojo"]) for x in detalle]))
    if est["no_corregidos"]:
        p.append("<p><b>No se corrigio (revisar): %d</b></p>" % len(est["no_corregidos"]))
        p.append(tabla(enc + ["Motivo"], [((x["contraparte"], x["fondo"], x["operacion"], x.get("mov") or x["op_cartera"],
                                            x["campo"],
                                            x["antes"], x["despues"], x["motivo"]), x["rojo"])
                                          for x in est["no_corregidos"][:60]]))
    if sin_stm or sin_archivo:
        p.append("<p><b>En cartera pero la contraparte no lo envio: %d</b></p>" % len(sin_stm))
        filas = [((c["cp"], c["fondo"], mov_operacion(ctx, c) or c["id"], c["ref"], c["td"], c["md"]), False)
                 for c in sin_stm[:60]]
        filas += [((cp, f, "", "Falta el statement %s de este fondo hoy (%d operaciones)" % (tp, n), "", ""), False)
                  for (cp, f, tp), n in sorted(sin_archivo.items())]
        p.append(tabla(["Contraparte", "Fondo", "mov_operacion", "Inst. Reference", "Trade", "Vencimiento"], filas))
    forz = est.get("forzados", [])
    if forz:
        p.append("<p><b>Pareo forzado: %d</b> operaciones del statement que no calzaban exacto se parearon con la "
                 "cartera (por su N de operacion de dias anteriores o por nominal y fechas). Detalle en la hoja "
                 "'Pareo forzado'.</p>" % len(forz))
    resp = est.get("respetados", [])
    if resp:
        cuenta = Counter((x["contraparte"], x["campo"], x["regla"]) for x in resp)
        p.append("<p><b>Datos que se dejaron como los manda la contraparte</b> (el aplicativo los parea asi):</p>")
        p.append(tabla(["Contraparte", "Campo", "Por que", "Operaciones"],
                       [((cp, campo, "politica de reportes.json" if regla == "politica" else "aprendido del aplicativo",
                          n), regla != "politica") for (cp, campo, regla), n in sorted(cuenta.items())]))
    seg = getattr(ctx, "seguimiento_resumen", [])
    if seg:
        p.append("<p><b>Seguimiento con el aplicativo</b> (Informe Diario / Comparacion en las carpetas de los ultimos "
                 "dias):</p>")
        p.append(tabla(["Cierre", "Sin valor de la contraparte", "Detalle"],
                       [((T.strftime("%d-%m-%Y"), n, texto), False) for T, n, texto, info in seg]))
        revisar = [x for x in getattr(ctx, "seguimiento", []) if x["situacion"] not in (SIT_NO_ENVIADO, SIT_SIN_ARCHIVO)]
        if revisar:
            p.append(tabla(["Contraparte", "Fondo", "mov_operacion", "N operacion contraparte", "Situacion", "Detalle"],
                           [((x["contraparte"], x["fondo"], x["mov"], x["operacion"], x["situacion"], x["detalle"]),
                             x["situacion"].startswith(("No pareo", "El statement coincide")))
                            for x in revisar[:40]]))
    if nuevas:
        p.append("<p><b style='color:#C00000'>Contrapartes extranjeras en cartera sin statement configurado</b>: %s</p>"
                 % e(", ".join("%s (%d)" % kv for kv in sorted(nuevas.items()))))
    if est["cubiertos"]:
        p.append("<p>%d valores de ajustes_operaciones.json ya los entrega Vmetrix (detalle en el Excel, hoja "
                 "'JSON ya cubierto').</p>" % len(est["cubiertos"]))
    p.append("<p style='color:#595959;font-size:9pt;'>Rojo = cambio o diferencia de nominal o tasa. Las fechas se "
             "dejan iguales a la cartera de Vmetrix. Detalle completo en el Excel adjunto.</p></div>")
    return "".join(p)


# =============================================================================
# Seguimiento con el aplicativo (aprendizaje)
# =============================================================================
# Cada ejecucion deja en la carpeta del dia un pareo_dia.json: con que operacion de Vmetrix se pareo cada
# operacion del statement y, en los datos donde la contraparte y la cartera no coinciden, cual de los dos
# valores quedo en 02_Para_Cargar. Cuando en una carpeta de dia aparece el resultado del aplicativo
#   - el Excel del Informe Diario con Valorizacion_Contraparte (el mismo que usa valo_contraparte.py), o
#   - la "Comparacion" descargada del aplicativo (columnas mov_operacion y valor_banco),
# el script cruza ambos: si un contrato quedo sin valor del banco y ese dia se le cambio un dato para
# igualarlo a la cartera, al dia siguiente prueba con el dato de la contraparte (y al reves). Si pareo, lo
# mantiene; si ninguna de las dos formas parea, lo deja como siempre y lo informa para revisarlo en el
# aplicativo. Todo queda en el informe (hoja Seguimiento aplicativo). Nada se guarda en los JSON.
#   configuracion.json > seguimiento

ARCHIVO_FOTO = "pareo_dia.json"
SEGUIMIENTO_POR_DEFECTO = {"activo": True, "dias": 15, "dias_operacion_nueva": 3, "aprender": True}
SIT_NO_ENVIADO = "La contraparte no lo envio en su statement"
SIT_SIN_ARCHIVO = "No se proceso statement de esa contraparte o tipo (falta el archivo o es nacional)"
SIT_NUEVA = "Operacion nueva: el aplicativo puede no tener aun todos sus datos"
SIT_COINCIDE = "El statement coincide con la cartera y el aplicativo no lo pareo: revisar en el aplicativo"
SIT_CAMBIADO = "Se cambio %s para igualar a cartera y no pareo: se prueba con el dato de la contraparte"
SIT_CONTRAPARTE = "Se dejo %s como la contraparte y no pareo: se vuelve al de cartera"
SIT_SIN_SOLUCION = "No pareo ni con el dato de cartera ni con el de la contraparte (%s): revisar en el aplicativo"


def conf_seguimiento(ctx):
    conf = dict(SEGUIMIENTO_POR_DEFECTO)
    conf.update({k: v for k, v in (ctx.conf.get("seguimiento") or {}).items() if not str(k).startswith("_")})
    return conf


def carpetas_de_dias(ctx, dias, incluir_hoy=True):
    """Carpetas AAAA-MM-DD de la carpeta de descargas de los ultimos 'dias' dias (de la mas antigua a hoy)."""
    salida = []
    limite = ctx.hoy - dt.timedelta(days=int(dias))
    try:
        hijos = list(ctx.raiz_descargas.iterdir())
    except OSError:
        return salida
    for d in hijos:
        if not d.is_dir():
            continue
        f = fecha_desde_texto(d.name)
        if f is None or f < limite or f > ctx.hoy or (f == ctx.hoy and not incluir_hoy):
            continue
        salida.append((f, d))
    return sorted(salida, key=lambda x: x[0])


def _leer_json(ruta):
    try:
        return json.loads(Path(ruta).read_text(encoding="utf-8"))
    except Exception:
        return None


def guardar_foto(ctx):
    """pareo_dia.json en la carpeta del dia (se combina con el de una ejecucion anterior del mismo dia)."""
    est = ctx.pareo
    if not est or not est.get("ok"):
        return
    ruta = ctx.dia / ARCHIVO_FOTO
    previo = _leer_json(ruta) or {}
    ahora = {p["archivo"] for p in est.get("foto", [])}
    pares = [p for p in previo.get("pares", []) if p.get("archivo") not in ahora] + est.get("foto", [])
    sin_stm, _ = _filas_sin_statement(ctx)
    datos = {"version": VERSION, "fecha": normalizar(ctx.hoy), "cob": normalizar(est["cob"]),
             "generado": dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "usuario": ctx.login,
             "pares": pares,
             "no_enviados": [dict(cp=c["cp"], fondo=c["fondo"], tran=c["id"], externo=c.get("id_externo", ""),
                                  tipo=c["tipo"], ref=c["ref"], td=normalizar(c.get("td")), md=normalizar(c.get("md")))
                             for c in sin_stm]}
    try:
        ruta.write_text(json.dumps(datos, indent=1, ensure_ascii=True), encoding="utf-8")
    except Exception as e:
        LOG.warning("No pude guardar %s: %s", ruta, e)


def cargar_memoria(ctx):
    """(reporte, fondo, N operacion contraparte) -> Tran Deal con que se pareo en dias anteriores, y al reves
    Tran Deal -> (N operacion de la contraparte, cierre en que vino)."""
    memoria, inversa = {}, {}
    for f, d in carpetas_de_dias(ctx, conf_seguimiento(ctx).get("dias", 15), incluir_hoy=False):
        foto = _leer_json(d / ARCHIVO_FOTO)
        cob = fecha_desde_texto((foto or {}).get("cob"))
        for p in (foto or {}).get("pares", []):
            if p.get("operacion") and p.get("tran"):
                memoria[(p.get("reporte"), p.get("fondo"), p["operacion"])] = str(p["tran"])
                inversa[str(p["tran"])] = (p["operacion"], _fecha_en(cob) if cob else d.name)
    return memoria, inversa


def _encabezado_informe(filas):
    """(fila, {campo: columna}, tipo) del Informe Diario o de la Comparacion del aplicativo."""
    nombres = {"fecha": ["FECHA_INFORME", "Process_date"], "fondo": ["EMP_CODIGO", "Fondo"],
               "tran": ["VM_TRAN_DEAL"], "externo": ["EXTERNAL_ID"], "valor_cp": ["VALORIZACION_CONTRAPARTE",
                                                                                  "Valorizacion_Contraparte"],
               "mov": ["mov_operacion"], "valor_banco": ["valor_banco"], "trade_id": ["trade_id"]}
    for k, fila in enumerate(filas[:15]):
        claves = {_clave_col(v): j for j, v in enumerate(fila) if v is not None and str(v).strip()}
        col = {}
        for campo, lista in nombres.items():
            for n in lista:
                if _clave_col(n) in claves:
                    col[campo] = claves[_clave_col(n)]
                    break
        if "valor_cp" in col and ("tran" in col or "externo" in col):
            return k, col, "informe"
        if "mov" in col and "valor_banco" in col:
            return k, col, "comparacion"
    return None, None, None


def _filas_de_archivo(ruta):
    if ruta.suffix.lower() == ".csv":
        import csv
        texto = ruta.read_bytes().decode("utf-8-sig", errors="replace")
        lineas = texto.splitlines()
        sep = ";" if lineas and lineas[0].count(";") > lineas[0].count(",") else ","
        return [list(f) for f in csv.reader(lineas, delimiter=sep)]
    import openpyxl
    wb = openpyxl.load_workbook(str(ruta), read_only=True, data_only=True)
    try:
        return [list(f) for f in wb.worksheets[0].iter_rows(values_only=True)]
    finally:
        wb.close()


def leer_resultados_aplicativo(ctx):
    """{cierre T: {"ceros": set(tran), "con_valor": set(tran), "completo": bool, "archivos": [..]}} con los
    Informes Diarios y Comparaciones que haya en las carpetas de los ultimos dias."""
    conf = conf_seguimiento(ctx)
    salida = {}
    ext_a_tran = {}
    for c in (ctx.pareo or {}).get("ops", []):
        if c.get("id_externo"):
            ext_a_tran[c["id_externo"]] = c["id"]
    base_mov = int((ctx.conf.get("vmetrix") or {}).get("mov_operacion_base", 30000000))
    for f, d in carpetas_de_dias(ctx, conf.get("dias", 15)):
        foto = _leer_json(d / ARCHIVO_FOTO) or {}
        for p in foto.get("pares", []):
            if p.get("externo") and p.get("tran"):
                ext_a_tran.setdefault(p["externo"], p["tran"])
        try:
            archivos = sorted(x for x in d.iterdir() if x.is_file())
        except OSError:
            continue
        if not (getattr(ctx, "plan_b", False) and f == ctx.hoy):
            archivos += archivos_comparacion(d / _sub_comparaciones(ctx))   # v2.4: AAAA-MM-DD\04_Comparaciones
        for ruta in archivos:
            n = ruta.name.lower()
            if "(valo contraparte)" in n:
                continue        # copia llenada por valo_contraparte.py: no es el resultado del aplicativo
            if (ruta.suffix.lower() not in (".xlsx", ".xlsm", ".csv") or n.startswith(("~$", "reporte_", "pareo_vmetrix",
                                                                                       "valo_contraparte", "vmetrix_copia",
                                                                                       "cartera_vmetrix", "faltantes_"))):
                continue
            try:
                filas = _filas_de_archivo(ruta)
            except Exception:
                continue
            k, col, tipo = _encabezado_informe(filas)
            if tipo is None:
                continue
            for fila in filas[k + 1:]:
                g = lambda campo: fila[col[campo]] if campo in col and col[campo] < len(fila) else None
                if tipo == "informe":
                    T = _fecha_vm(g("fecha"))
                    tran = normalizar(g("tran")) if g("tran") not in (None, "") else ext_a_tran.get(normalizar(g("externo")))
                    x = _num_vm(g("valor_cp"))
                    cero = x is None or abs(x) < 0.5
                else:
                    T = fecha_desde_texto(foto.get("cob")) if foto.get("cob") else None
                    if T is None:
                        T = dia_habil_anterior(f, FERIADOS)
                    m = _num_vm(g("mov"))
                    tran = str(int(m) - base_mov) if m is not None and m > base_mov else None
                    cero = _sin_valor(g("valor_banco"))
                if T is None or not tran:
                    continue
                info = salida.setdefault(T, {"ceros": set(), "con_valor": set(), "completo": False, "archivos": set()})
                info["archivos"].add("%s\\%s" % (d.name, ruta.name))
                (info["ceros"] if cero else info["con_valor"]).add(tran)
    for T, info in salida.items():
        # El Excel que manda el equipo del Informe Diario trae solo lo que quedo en 0: lo que no esta, pareo
        info["completo"] = not info["con_valor"]
    return salida


def _fotos_por_cierre(ctx, dias):
    fotos = {}
    for f, d in carpetas_de_dias(ctx, dias):
        foto = _leer_json(d / ARCHIVO_FOTO)
        if foto and foto.get("cob"):
            T = fecha_desde_texto(foto["cob"])
            if T is not None:
                foto["_carpeta"] = d.name
                fotos[T] = foto           # si hay dos carpetas con el mismo cierre, vale la mas reciente
    return fotos


def _habiles_antes(T, n):
    d = T
    for _ in range(int(n)):
        d = dia_habil_anterior(d, FERIADOS)
    return d


def calcular_aprendizaje(ctx):
    """Lecciones {(reporte, fondo, N operacion, campo): {"usar", "estado", "motivo"}} y filas de seguimiento."""
    conf = conf_seguimiento(ctx)
    lecciones, filas, resumen = {}, [], []
    if not conf.get("activo", True):
        return lecciones, filas, resumen
    resultados = leer_resultados_aplicativo(ctx)
    if not resultados:
        return lecciones, filas, resumen
    fotos = _fotos_por_cierre(ctx, conf.get("dias", 15) + 5)
    historial = {}
    ops = {c["id"]: c for c in (ctx.pareo or {}).get("ops", [])}
    nombres = {(rep.get("pareo") or {}).get("contraparte_vmetrix"): rep.get("contraparte", "") for rep in ctx.reportes}
    ultimo_T = max(resultados)
    for T in sorted(resultados):
        info = resultados[T]
        foto = fotos.get(T)
        cuenta = Counter()
        if not foto:
            resumen.append((T, len(info["ceros"]), "sin pareo_dia.json de ese cierre (se proceso con una version "
                                                   "anterior o en otro PC): no se puede aprender de ese dia", info))
            continue
        pares = {}
        for p in foto.get("pares", []):
            pares.setdefault(str(p["tran"]), p)
        no_env = {str(x["tran"]): x for x in foto.get("no_enviados", [])}
        nueva_desde = _habiles_antes(T, conf.get("dias_operacion_nueva", 3))
        for tran in sorted(info["ceros"]):
            p = pares.get(tran)
            c = ops.get(tran)
            base = dict(cierre=T, tran=tran, mov=mov_operacion(ctx, c or {"id": tran, "es_deal": True}),
                        contraparte=nombres.get((p or {}).get("cp") or (c or {}).get("cp") or
                                                (no_env.get(tran) or {}).get("cp"), ""),
                        fondo=(p or c or no_env.get(tran) or {}).get("fondo", ""),
                        reporte=(p or {}).get("reporte", ""), operacion=(p or {}).get("operacion", ""),
                        referencia=(c or {}).get("ref") or (no_env.get(tran) or {}).get("ref", ""))
            if p is None:
                sit = SIT_NO_ENVIADO if tran in no_env else SIT_SIN_ARCHIVO
                cuenta[sit] += 1
                if T == ultimo_T:
                    filas.append(dict(base, situacion=sit, detalle=""))
                continue
            td = fecha_desde_texto(p.get("td"))
            if td is not None and td >= nueva_desde:
                cuenta[SIT_NUEVA] += 1
                if T == ultimo_T:
                    filas.append(dict(base, situacion=SIT_NUEVA, detalle="trade %s" % normalizar(td)))
                continue
            if not p.get("campos"):
                cuenta[SIT_COINCIDE] += 1
                if T == ultimo_T:
                    filas.append(dict(base, situacion=SIT_COINCIDE, detalle=p.get("forzado", "")))
                continue
            for cm in p["campos"]:
                historial.setdefault((p["reporte"], p["fondo"], p["operacion"], cm["campo"]), []).append(
                    (T, cm["cargado"], False, cm, base))
            cuenta["con datos distintos a cartera"] += 1
        for tran, p in pares.items():
            if tran in info["ceros"]:
                continue
            if tran in info["con_valor"] or info["completo"]:
                for cm in p.get("campos", []):
                    historial.setdefault((p["reporte"], p["fondo"], p["operacion"], cm["campo"]), []).append(
                        (T, cm["cargado"], True, cm, None))
        resumen.append((T, len(info["ceros"]), "; ".join("%s: %d" % kv for kv in sorted(cuenta.items())), info))
    if not conf.get("aprender", True):
        return lecciones, filas, resumen
    for clave, eventos in historial.items():
        eventos.sort(key=lambda e: e[0])
        T, cargado, ok, cm, base = eventos[-1]
        texto = CAMPO_TEXTO.get(cm["campo"], cm["campo"])
        if ok:
            if cargado == "contraparte":
                lecciones[clave] = dict(usar="contraparte", estado="confirmado",
                                        motivo="el %s pareo en el aplicativo con el dato de la contraparte (%s)"
                                               % (T.strftime("%d-%m"), cm["contraparte"]))
            elif cargado == "cartera":
                lecciones[clave] = dict(usar="cartera", estado="confirmado", motivo="")
            continue
        fallo_cartera = any(e[1] == "cartera" and not e[2] for e in eventos)
        fallo_contraparte = any(e[1] == "contraparte" and not e[2] for e in eventos)
        if fallo_cartera and fallo_contraparte:
            sit = SIT_SIN_SOLUCION % texto
            detalle = "contraparte %s / cartera %s" % (cm["contraparte"], cm["cartera"])
            lecciones[clave] = dict(usar="sin_solucion", estado="sin_solucion", motivo=sit)
        elif cargado == "cartera":
            sit = SIT_CAMBIADO % texto
            detalle = "cartera %s -> se prueba %s" % (cm["cartera"], cm["contraparte"])
            lecciones[clave] = dict(usar="contraparte", estado="probar",
                                    motivo="el %s con %s de cartera (%s) no pareo en el aplicativo; se prueba con el de "
                                           "la contraparte (%s)" % (T.strftime("%d-%m"), texto, cm["cartera"],
                                                                    cm["contraparte"]))
        else:
            sit = SIT_CONTRAPARTE % texto
            detalle = "contraparte %s -> se vuelve a %s" % (cm["contraparte"], cm["cartera"])
            lecciones[clave] = dict(usar="cartera", estado="probar",
                                    motivo="el %s con %s de la contraparte no pareo; vuelve al de cartera" %
                                           (T.strftime("%d-%m"), texto))
        if T == ultimo_T and base:
            filas.append(dict(base, situacion=sit, detalle=detalle))
        if base:
            lecciones[clave].update(tran=base.get("tran", ""), mov=base.get("mov", ""),
                                    valor_contraparte=cm.get("contraparte"), valor_cartera=cm.get("cartera"))
    return lecciones, filas, resumen


def preparar_seguimiento(ctx):
    """Antes de preparar los archivos: memoria de pareos anteriores y lecciones del aplicativo
    (las guardadas en Json\aprendizaje_aplicativo.json mas las de los ultimos dias)."""
    ctx.lecciones, ctx.seguimiento, ctx.seguimiento_resumen = {}, [], []
    est = ctx.pareo
    if not est or not est.get("ok") or not conf_seguimiento(ctx).get("activo", True):
        return
    try:
        est["memoria"], est["memoria_inv"] = cargar_memoria(ctx)
    except Exception as e:
        LOG.warning("Memoria de pareos: %s", e)
    guardadas = cargar_lecciones(ctx)
    ctx.lecciones = {k: v for k, v in guardadas.items() if v.get("activo", True)}
    try:
        nuevas, ctx.seguimiento, ctx.seguimiento_resumen = calcular_aprendizaje(ctx)
    except Exception as e:
        LOG.error("Seguimiento del aplicativo: %s\n%s", e, traceback.format_exc())
        nuevas = {}
    for k, v in nuevas.items():
        if guardadas.get(k, {}).get("activo", True):
            ctx.lecciones[k] = dict(guardadas.get(k, {}), **v)
    try:
        guardar_lecciones(ctx, nuevas, "seguimiento del aplicativo")
    except Exception as e:
        LOG.warning("No pude guardar %s: %s", ARCHIVO_LECCIONES, e)
    if guardadas:
        decir("  Aprendido antes (Json\\%s): %d dato(s)." % (ARCHIVO_LECCIONES, len(guardadas)))
    for T, n, texto, info in ctx.seguimiento_resumen:
        decir("  Aplicativo cierre %s: %d contratos sin valor de la contraparte (%s)" % (T.strftime("%d-%m-%Y"), n,
                                                                                         texto or "-"))
    activas = [l for l in ctx.lecciones.values() if l.get("usar") == "contraparte"]
    if activas:
        decir("  Aprendido del aplicativo: %d dato(s) se dejan como los manda la contraparte." % len(activas))
    sin = [l for l in ctx.lecciones.values() if l.get("usar") == "sin_solucion"]
    if sin:
        decir("  %d dato(s) no parean de ninguna forma: revisar en el aplicativo (hoja Seguimiento aplicativo)." % len(sin))


# =============================================================================
# v2.4: lo aprendido del aplicativo queda guardado (Json\aprendizaje_aplicativo.json)
# =============================================================================
#   Una linea por dato de un contrato: que dato acepta el aplicativo (el de la contraparte o el de
#   cartera). Lo escriben el seguimiento diario y el plan B; se puede editar a mano ("activo": false
#   para que no se use). Las de contratos que ya no estan en la cartera se borran solas.

ARCHIVO_LECCIONES = "aprendizaje_aplicativo.json"
CAMPO_JSON = {"td": "trade", "sd": "inicio", "md": "vencimiento", "nominal": "nominal",
              "tasa_flotante": "tasa_flotante"}
INSTRUCCIONES_LECCIONES = [
    "Lo aprende el script (seguimiento diario y plan B con las Comparaciones del aplicativo). No hace falta editarlo.",
    "Cada linea: reporte, fondo, operacion (N de la contraparte) y campo (vencimiento, trade, inicio, nominal,",
    "tasa_flotante). usar = 'contraparte' (el dato se deja como lo manda la contraparte) o 'cartera' (se iguala a",
    "Vmetrix). estado: probar (se esta probando), confirmado (parea en el aplicativo), sin_solucion (no pareo con",
    "ninguno de los dos: revisar en el aplicativo). 'activo': false = no se usa. Las lineas de contratos que ya",
    "no estan vigentes en la cartera se borran solas.",
]


def _sin_valor(v):
    """valor_banco de la Comparacion: vacio o NA = el aplicativo no pareo el contrato. Cualquier otro texto
    (aunque Excel lo haya dejado como 5.503.106.330.954) = pareo."""
    if v is None:
        return True
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return False
    return str(v).strip().upper() in ("", "NA", "N/A", "NAN", "NULL", "-")


def _sub_comparaciones(ctx):
    return (ctx.conf.get("subcarpetas_dia") or {}).get("comparaciones", "04_Comparaciones")


def archivos_comparacion(carpeta):
    """CSV/XLSX descargados del aplicativo en la carpeta (sin subcarpetas: _usadas_* ya se procesaron)."""
    try:
        return sorted(x for x in ruta_larga(carpeta).iterdir()
                      if x.is_file() and x.suffix.lower() in (".csv", ".xlsx", ".xlsm")
                      and not x.name.startswith(("~$", ".")))
    except OSError:
        return []


def _clave_leccion(d):
    campo = CAMPOS_POLITICA.get(str(d.get("campo", "")).strip().lower(), d.get("campo"))
    return (d.get("reporte"), d.get("fondo"), normalizar(d.get("operacion")), campo)


def cargar_lecciones(ctx):
    """{(reporte, fondo, operacion, campo): leccion} de Json\\aprendizaje_aplicativo.json."""
    ruta = ctx.dir_json / ARCHIVO_LECCIONES
    if not ruta.is_file():
        return {}
    try:
        datos = cargar_json(ruta)
    except SystemExit as e:
        decir("Aviso: %s" % e)
        return {}
    salida = {}
    for d in datos.get("lecciones", []) if isinstance(datos, dict) else []:
        if isinstance(d, dict) and d.get("reporte") and d.get("operacion") and d.get("campo"):
            salida[_clave_leccion(d)] = dict(d)
    return salida


def guardar_lecciones(ctx, nuevas, origen):
    """Suma 'nuevas' a lo guardado (lo nuevo manda; se conserva 'desde' y lo que editaste) y borra lo de
    contratos que ya no estan vigentes en la cartera."""
    ruta = ctx.dir_json / ARCHIVO_LECCIONES
    guardadas = cargar_lecciones(ctx)
    cambio = False
    hoy = normalizar(ctx.hoy)
    ahora = dt.datetime.now().strftime("%Y-%m-%d %H:%M")
    for (rep, fondo, op, campo), v in nuevas.items():
        clave = (rep, fondo, normalizar(op), campo)
        previo = guardadas.get(clave)
        if previo is not None and not previo.get("activo", True):
            continue                      # la desactivaste a mano: no se toca
        dato = dict(previo or {})
        for k in ("usar", "estado", "motivo", "tran", "mov", "valor_contraparte", "valor_cartera"):
            if v.get(k) not in (None, ""):
                dato[k] = normalizar(v[k]) if k in ("valor_contraparte", "valor_cartera") else v[k]
        if previo and all(previo.get(k) == dato.get(k) for k in ("usar", "estado")):
            continue
        dato.update(reporte=rep, fondo=fondo, operacion=normalizar(op), campo=CAMPO_JSON.get(campo, campo),
                    actualizado=ahora, origen=origen)
        dato.setdefault("desde", hoy)
        guardadas[clave] = dato
        cambio = True
    est = ctx.pareo
    if est and est.get("ok") and est.get("ops"):
        vigentes = {str(c["id"]) for c in est["ops"]}
        for clave in [k for k, v in guardadas.items() if v.get("tran") and str(v["tran"]) not in vigentes]:
            del guardadas[clave]
            cambio = True
    if not cambio:
        return False
    orden = sorted(guardadas.values(), key=lambda d: (str(d.get("reporte")), str(d.get("fondo")),
                                                      str(d.get("operacion")), str(d.get("campo"))))
    campos = ["reporte", "fondo", "operacion", "campo", "usar", "estado", "activo", "tran", "mov",
              "valor_contraparte", "valor_cartera", "motivo", "desde", "actualizado", "origen"]
    lineas = [OrderedDict((k, d[k]) for k in campos if k in d) for d in orden]
    if ruta.is_file():
        try:          # un respaldo por dia
            hoy_txt = dt.date.today().strftime("%Y%m%d")
            if not list((ctx.dir_json / "_respaldos").glob("%s_%s_*%s" % (ruta.stem, hoy_txt, ruta.suffix))):
                respaldar(ruta, ctx.dir_json / "_respaldos")
        except Exception:
            pass
    guardar_json(ruta, {"_instrucciones": INSTRUCCIONES_LECCIONES, "lecciones": lineas})
    return True


# =============================================================================
# v2.4: Plan B con las Comparaciones del aplicativo (04_Comparaciones)
# =============================================================================
#   1. Lee las Comparaciones que descargaste del aplicativo (CSV o Excel con mov_operacion y valor_banco).
#   2. Para cada contrato sin valor_banco busca su fila en el archivo que se cargo (02_Para_Cargar) y en
#      el original de la contraparte, y ve que dato se cargo: el de cartera o el de la contraparte.
#   3. Prueba con el otro dato, de a uno por contrato y en este orden: vencimiento, nominal, fecha trade,
#      fecha inicio, tasa pata flotante. Si ya se probaron los dos, lo marca para revisar en el aplicativo.
#   4. Vuelve a preparar solo esos archivos (desde 01_Originales, el anterior queda en _respaldo) y los
#      copia a 02_Para_Cargar\_RECARGAR_PlanB_HHMM para que cargues solo esos.
#   5. Guarda lo aprendido en Json\aprendizaje_aplicativo.json: desde ese dia la script normal ya los
#      prepara asi. Las Comparaciones usadas pasan a 04_Comparaciones\_usadas_HHMM.

PRIORIDAD_PLAN_B = ("md", "nominal", "td", "sd", "tasa_flotante")
SITB_NUEVA = "Operacion del dia del cierre o posterior: llega en el statement siguiente"
SITB_NO_VIGENTE = "No esta vigente en la cartera de Vmetrix del dia (vencio, o la comparacion es de otro cierre)"
SITB_SIN_CONFIG = "Contraparte sin statement configurado en reportes.json"
COLUMNAS_COMPARACION = {"contraparte": "contraparte", "fondo": "fondo", "mov": "mov_operacion",
                        "instrumento": "instrumento", "serie": "serie", "valor_banco": "valor_banco",
                        "trade_id": "trade_id", "fecha_venc": "fecha_venc", "nominal": "nominales_activo_objeto",
                        "valor_afp": "valor_afp", "fecha_sub": "fecha_sub"}


def leer_comparaciones(ctx, archivos):
    """({tran: info}, [(archivo, filas)], [problemas]). Si un contrato aparece en varias descargas y en
    alguna ya parea, vale esa."""
    base_mov = int((ctx.conf.get("vmetrix") or {}).get("mov_operacion_base", 30000000))
    salida, leidos, malos = {}, [], []
    for ruta in archivos:
        try:
            filas = _filas_de_archivo(ruta)
        except Exception as e:
            malos.append("%s (no lo pude leer: %s)" % (ruta.name, e))
            continue
        k, col = None, {}
        for i, fila in enumerate(filas[:15]):
            claves = {_clave_col(v): j for j, v in enumerate(fila) if v is not None and str(v).strip()}
            if "movoperacion" in claves and "valorbanco" in claves:
                k = i
                col = {campo: claves[_clave_col(n)] for campo, n in COLUMNAS_COMPARACION.items()
                       if _clave_col(n) in claves}
                break
        if k is None:
            malos.append("%s (no tiene las columnas mov_operacion y valor_banco)" % ruta.name)
            continue
        n = sin = 0
        for fila in filas[k + 1:]:
            def g(campo, fila=fila):
                j = col.get(campo)
                return fila[j] if j is not None and j < len(fila) else None
            m = _num_vm(g("mov"))
            if m is None or m <= base_mov:
                continue
            tran = str(int(m) - base_mov)
            pareo = not _sin_valor(g("valor_banco"))
            fondo = str(g("fondo") or "").strip().upper()
            fondo = fondo[-1] if fondo and fondo[-1] in "ABCDE" else fondo
            n += 1
            sin += 0 if pareo else 1
            previo = salida.get(tran)
            if previo is not None and previo["pareo"]:
                continue
            salida[tran] = dict(tran=tran, mov=int(m), pareo=pareo, fondo=fondo, archivo=ruta.name,
                                contraparte=str(g("contraparte") or "").strip(),
                                instrumento=str(g("instrumento") or "").strip(),
                                serie=str(g("serie") or "").strip(), trade_id=str(g("trade_id") or "").strip(),
                                fecha_venc=str(g("fecha_venc") or "").strip())
        leidos.append((ruta.name, n, sin))
    return salida, leidos, malos


def _diferencias_cargadas(s, so, c):
    """{campo: {"contraparte", "cartera", "cargado", "otro"}} de los datos en que la contraparte y la cartera
    no coinciden. s = fila del archivo cargado, so = la misma fila en el original de la contraparte."""
    difs = {}
    for campo in ("td", "sd", "md"):
        cart, carg = c.get(campo), s.get(campo)
        cpv = (so or {}).get(campo)
        if cart is None or carg is None:
            continue
        if cpv is None:
            cpv = carg if carg != cart else None
        if cpv is None or cpv == cart:
            continue
        cargado = "cartera" if carg == cart else ("contraparte" if carg == cpv else "otro")
        difs[campo] = dict(contraparte=cpv, cartera=cart, cargado=cargado, otro=carg)
    if s.get("tipo") != "FX" and c.get("nominal") is not None and s.get("nominal") is not None:
        cpv = (so or {}).get("nominal", s["nominal"])
        if abs(cpv - c["nominal"]) > 0.005:
            cargado = ("cartera" if abs(s["nominal"] - c["nominal"]) <= 0.005 else
                       "contraparte" if abs(s["nominal"] - cpv) <= 0.005 else "otro")
            difs["nominal"] = dict(contraparte=cpv, cartera=c["nominal"], cargado=cargado, otro=s["nominal"])
    tf = s["conf"].get("tasa_flotante")
    j = s["celdas"].get("tasa_flotante")
    if (tf and c.get("afp_paga_fija") and j is not None and so is not None
            and so["celdas"].get("tasa_flotante") is not None):
        carg = _num_vm(s["tabla"].hoja.valor(s["fila"], j))
        cpv = _num_vm(so["tabla"].hoja.valor(so["fila"], so["celdas"]["tasa_flotante"]))
        obj = float(tf.get("valor", 0) or 0)
        if cpv is not None and carg is not None and abs(cpv - obj) > 1e-9:
            cargado = ("cartera" if abs(carg - obj) <= 1e-9 else
                       "contraparte" if abs(carg - cpv) <= 1e-9 else "otro")
            difs["tasa_flotante"] = dict(contraparte=cpv, cartera=obj, cargado=cargado, otro=carg)
    return difs


def _dato_txt(v):
    return v.strftime("%d-%m-%Y") if isinstance(v, dt.date) else normalizar(v)


def _ops_originales(r, rep):
    origen = r.archivo
    conv = rep.get("convertir_formato_nuevo") or {}
    if conv and conv.get("activo", True):
        convertido, _ = convertir_formato_nuevo(r, Libro(r.archivo), conv)
        origen = convertido or origen
    return {(s["fondo"], s["id"]): s for s in operaciones_del_libro(Libro(origen), rep, r.fondo)}


def analizar_plan_b(ctx, ranuras, comp):
    """(lecciones nuevas, filas del informe, {ranura: [cambios a probar]})."""
    est = ctx.pareo
    pconf = ctx.conf.get("pareo") or {}
    lecciones = ctx.lecciones
    nuevas, filas, afectadas, vistos, cobertura = {}, [], {}, set(), set()
    hoy_txt = ctx.hoy.strftime("%d-%m")
    orden = [CAMPOS_POLITICA.get(str(x).strip().lower(), x) for x in
             (ctx.conf.get("plan_b") or {}).get("orden_datos") or PRIORIDAD_PLAN_B]
    orden = [x for x in orden if x in PRIORIDAD_PLAN_B] or list(PRIORIDAD_PLAN_B)
    for r in sorted(ranuras.values(), key=lambda x: (x.reporte.get("contraparte", ""), x.fondo)):
        rep = r.reporte
        conf = rep.get("pareo") or {}
        cp = conf.get("contraparte_vmetrix")
        if r.archivo is None or not cp or not conf.get("tipos"):
            continue
        salida = ctx.dir_cargar / nombre_de_salida(rep, r.archivo.name)
        if not salida.exists():
            continue
        try:
            cargadas = operaciones_del_libro(Libro(salida), rep, r.fondo)
            originales = _ops_originales(r, rep)
        except Exception as e:
            LOG.error("Plan B %s: %s\n%s", salida.name, e, traceback.format_exc())
            filas.append(dict(contraparte=rep.get("contraparte", ""), reporte=rep["id"], fondo=r.fondo,
                              archivo=salida.name, operacion="", tran="", mov="", referencia="", instrumento="",
                              situacion="No pude leer el archivo: %s" % e, hecho=""))
            continue
        fondos = {s["fondo"] for s in cargadas} | ({r.fondo} if len(rep.get("fondos", [])) > 1 else set("ABCDE"))
        for f in fondos:
            for tc in conf.get("tipos", []):
                cobertura.add((cp, f, tc.get("tipo")))
        cart = est["por_cp"].get(cp, [])
        pares, sin = parear_vm(cargadas, cart, pconf)
        pares = [(s, c) for s, c, d, amb in pares]
        if sin and pconf.get("pareo_forzado", True):
            usados = {id(c) for _, c in pares}
            libres = [c for c in cart if id(c) not in usados]
            for s, c, d, motivo, parecido in parear_forzado(sin, libres, pconf, est.get("memoria"),
                                                             lambda s: (rep["id"], s["fondo"], s["id"])):
                pares.append((s, c))
        for s, c in pares:
            tran = str(c["id"])
            info = comp.get(tran)
            if info is None:
                continue
            vistos.add(tran)
            difs = _diferencias_cargadas(s, originales.get((s["fondo"], s["id"])), c)
            base = dict(contraparte=rep.get("contraparte", ""), reporte=rep["id"], fondo=s["fondo"],
                        archivo=salida.name, operacion=s["id"], tran=tran, mov=info["mov"],
                        referencia=c.get("ref", ""), instrumento=info.get("instrumento", ""))
            if info["pareo"]:
                for campo, dif in difs.items():
                    clave = (rep["id"], s["fondo"], s["id"], campo)
                    lec = lecciones.get(clave)
                    if lec and lec.get("estado") == "probar" and lec.get("usar") == dif["cargado"]:
                        quien = "la contraparte" if dif["cargado"] == "contraparte" else "cartera"
                        nuevas[clave] = dict(lec, estado="confirmado", tran=tran, mov=info["mov"],
                                             motivo="parea en el aplicativo (comparacion del %s) con %s de %s (%s)"
                                                    % (hoy_txt, CAMPO_TEXTO.get(campo, campo).lower(), quien,
                                                       _dato_txt(dif[dif["cargado"]])))
                        lecciones[clave] = nuevas[clave]
                continue
            if c.get("td") is not None and c["td"] >= est["cob"]:
                filas.append(dict(base, situacion=SITB_NUEVA, hecho=""))
                continue
            hecho, notas = None, []
            for campo in orden:
                dif = difs.get(campo)
                if not dif:
                    continue
                clave = (rep["id"], s["fondo"], s["id"], campo)
                lec = lecciones.get(clave)
                texto = CAMPO_TEXTO.get(campo, campo)
                if dif["cargado"] == "otro":
                    notas.append("%s cargado %s (contraparte %s, cartera %s)" % (
                        texto, _dato_txt(dif["otro"]), _dato_txt(dif["contraparte"]), _dato_txt(dif["cartera"])))
                    continue
                if lec and lec.get("estado") == "sin_solucion":
                    notas.append("%s: ya se probo con ambos datos" % texto)
                    continue
                if lec and lec.get("estado") == "confirmado" and lec.get("usar") == dif["cargado"]:
                    notas.append("%s: confirmado antes con este dato" % texto)
                    continue
                if lec and lec.get("estado") == "probar" and lec.get("usar") == dif["cargado"]:
                    nuevas[clave] = dict(usar="sin_solucion", estado="sin_solucion", tran=tran, mov=info["mov"],
                                         valor_contraparte=dif["contraparte"], valor_cartera=dif["cartera"],
                                         motivo=SIT_SIN_SOLUCION % texto.lower())
                    lecciones[clave] = nuevas[clave]
                    notas.append("%s: ya se probo con ambos datos" % texto)
                    continue
                otro = "contraparte" if dif["cargado"] == "cartera" else "cartera"
                quien = {"contraparte": "la contraparte", "cartera": "cartera"}
                nuevas[clave] = dict(
                    usar=otro, estado="probar", tran=tran, mov=info["mov"], valor_contraparte=dif["contraparte"],
                    valor_cartera=dif["cartera"],
                    motivo="comparacion del %s: con %s de %s (%s) no pareo; se prueba con el de %s (%s)" % (
                        hoy_txt, texto.lower(), quien[dif["cargado"]], _dato_txt(dif[dif["cargado"]]), quien[otro],
                        _dato_txt(dif[otro])))
                lecciones[clave] = nuevas[clave]
                hecho = dict(campo=campo, antes=dif[dif["cargado"]], despues=dif[otro], usar=otro,
                             fondo=s["fondo"], operacion=s["id"], tran=tran)
                afectadas.setdefault(r.clave, []).append(hecho)
                break
            if hecho:
                sit = "Se cargo %s de %s (%s): ahora va el de %s (%s)" % (
                    CAMPO_TEXTO.get(hecho["campo"], hecho["campo"]).lower(),
                    "cartera" if hecho["usar"] == "contraparte" else "la contraparte", _dato_txt(hecho["antes"]),
                    "la contraparte" if hecho["usar"] == "contraparte" else "cartera", _dato_txt(hecho["despues"]))
            elif not difs:
                sit = SIT_COINCIDE
            else:
                sit = "No queda otro dato que probar: revisar en el aplicativo (%s)" % "; ".join(notas)
            filas.append(dict(base, situacion=sit, hecho=hecho or ""))
    ops = {str(c["id"]): c for c in est["ops"]}
    configurados = {(rep.get("pareo") or {}).get("contraparte_vmetrix") for rep in ctx.reportes}
    for tran, info in sorted(comp.items(), key=lambda kv: (kv[1]["contraparte"], kv[1]["fondo"], kv[0])):
        if tran in vistos or info["pareo"]:
            continue
        c = ops.get(tran)
        base = dict(contraparte=info["contraparte"], reporte="", fondo=info["fondo"], archivo="", operacion="",
                    tran=tran, mov=info["mov"], referencia=(c or {}).get("ref") or info.get("serie", ""),
                    instrumento=info.get("instrumento", ""))
        if c is None:
            sit = SITB_NO_VIGENTE
        elif c["cp"] not in configurados:
            sit = SITB_SIN_CONFIG
        elif c.get("td") is not None and c["td"] >= est["cob"]:
            sit = SITB_NUEVA
        elif (c["cp"], c["fondo"], c["tipo"]) in cobertura:
            sit = SIT_NO_ENVIADO + " (va en el correo de contratos faltantes)"
        else:
            sit = SIT_SIN_ARCHIVO
        filas.append(dict(base, situacion=sit, hecho=""))
    return nuevas, filas, afectadas


def _verificar_plan_b(ctx, ranuras, afectadas):
    """Relee cada archivo vuelto a preparar y confirma que el dato a probar quedo."""
    for clave, cambios in afectadas.items():
        r = ranuras.get(clave)
        if r is None or r.salida is None or not r.salida.exists():
            for h in cambios:
                h["verificado"] = "no se genero el archivo"
            continue
        try:
            ops = {(s["fondo"], s["id"]): s for s in operaciones_del_libro(Libro(r.salida), r.reporte, r.fondo)}
        except Exception as e:
            for h in cambios:
                h["verificado"] = "no pude releerlo: %s" % e
            continue
        for h in cambios:
            s = ops.get((h["fondo"], h["operacion"]))
            if s is None:
                h["verificado"] = "no encontre la operacion en el archivo nuevo"
                continue
            if h["campo"] == "tasa_flotante":
                j = s["celdas"].get("tasa_flotante")
                v = _num_vm(s["tabla"].hoja.valor(s["fila"], j)) if j is not None else None
                ok = v is not None and abs(v - float(h["despues"])) <= 1e-9
            elif h["campo"] == "nominal":
                ok = s.get("nominal") is not None and abs(s["nominal"] - float(h["despues"])) <= 0.005
            else:
                ok = s.get(h["campo"]) == h["despues"]
            h["verificado"] = "si" if ok else "NO: revisar el archivo"
        if r.estado == ESTADO_ERROR:
            for h in cambios:
                h["verificado"] += " - el archivo quedo con ERROR, ver Reporte/log"


def _excel_plan_b(ruta, filas, recargar, leidos, malos):
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill
    from openpyxl.utils import get_column_letter
    wb = Workbook()
    wb.remove(wb.active)

    def hoja(nombre, enc, datos):
        ws = wb.create_sheet(nombre)
        ws.append(enc)
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF")
            c.fill = PatternFill("solid", fgColor="1F3864")
        for f in datos:
            ws.append([v if isinstance(v, (int, float)) and not isinstance(v, bool) else
                       ("" if v is None else _dato_txt(v)) for v in f])
        for j in range(1, ws.max_column + 1):
            largo = max((len(str(ws.cell(row=i, column=j).value or "")) for i in range(1, min(ws.max_row, 300) + 1)),
                        default=8)
            ws.column_dimensions[get_column_letter(j)].width = min(max(10, largo + 2), 70)
        ws.freeze_panes = "A2"
        if ws.max_row > 1:
            ws.auto_filter.ref = ws.dimensions

    hoja("Sin parear", ["Contraparte", "Fondo", "mov_operacion", "Op. Vmetrix", "Instrumento", "Inst. Reference",
                        "Reporte", "Archivo", "N operacion contraparte", "Situacion", "Dato cargado", "Dato nuevo",
                        "Quedo en el archivo nuevo"],
         [[f["contraparte"], f["fondo"], f["mov"], f["tran"], f["instrumento"], f["referencia"], f["reporte"],
           f["archivo"], f["operacion"], f["situacion"], (f["hecho"] or {}).get("antes", "") if f["hecho"] else "",
           (f["hecho"] or {}).get("despues", "") if f["hecho"] else "",
           (f["hecho"] or {}).get("verificado", "") if f["hecho"] else ""] for f in filas])
    hoja("Recargar", ["Archivo", "Contratos que se prueban", "Ruta"], recargar)
    hoja("Comparaciones", ["Archivo", "Contratos", "Sin valor_banco"],
         [list(x) for x in leidos] + [[m, "", ""] for m in malos])
    wb.save(str(ruta))


def _mover_comparaciones(ctx, archivos, hora):
    destino = ctx.dir_comp / ("_usadas_%s" % hora)
    movidos = 0
    for a in archivos:
        try:
            ruta_larga(destino).mkdir(parents=True, exist_ok=True)
            shutil.move(str(ruta_larga(a)), str(ruta_larga(destino / a.name)))
            movidos += 1
        except Exception as e:
            LOG.warning("No pude mover %s: %s", a.name, e)
    return destino, movidos


def modo_plan_b(ctx, ruta_log):
    """--plan-b: contratos sin valor_banco en las Comparaciones del aplicativo -> se prueba con el otro dato."""
    decir("")
    decir("PLAN B con las Comparaciones del aplicativo")
    decir("  Carpeta: %s" % mostrar(ctx.dir_comp))
    archivos = archivos_comparacion(ctx.dir_comp)
    while not archivos and ctx.interactivo:
        decir("  No hay Comparaciones en esa carpeta. En el aplicativo descarga la Comparacion de cada contraparte y")
        decir("  fondo que tenga contratos sin valor_banco (CSV o Excel) y dejalas ahi, sin cambiarles nada.")
        try:
            os.startfile(mostrar(ctx.dir_comp))
        except Exception:
            pass
        r = preguntar("  Cuando esten, presiona Enter (o escribe n para salir): ", True, "n")
        if r.lower().startswith("n"):
            return 1
        archivos = archivos_comparacion(ctx.dir_comp)
    if not archivos:
        decir("  No hay Comparaciones que revisar.")
        return 1
    comp, leidos, malos = leer_comparaciones(ctx, archivos)
    for m in malos:
        decir("  Aviso: %s" % m)
    sin = [x for x in comp.values() if not x["pareo"]]
    decir("  %d archivo(s), %d contratos, %d sin valor_banco." % (len(leidos), len(comp), len(sin)))
    if not comp:
        return 1
    hora = dt.datetime.now().strftime("%H%M%S")
    candado = ctx.dia / "_EN_EJECUCION.txt"
    candado.write_text("Plan B en ejecucion por %s desde %s" % (ctx.login, dt.datetime.now().strftime("%H:%M:%S")),
                       encoding="utf-8")
    try:
        ranuras = crear_ranuras(ctx)
        manifiesto = cargar_manifiesto(ctx)
        asignar_existentes(ctx, ranuras, manifiesto)
        decir("")
        decir("1) Cartera Vmetrix del dia")
        cargar_cartera_vmetrix(ctx)
        if not ctx.pareo.get("ok"):
            decir("  Sin cartera no puedo saber que se cargo. Revisa el archivo de Vmetrix y vuelve a intentar.")
            return 1
        preparar_seguimiento(ctx)
        decir("")
        decir("2) Que dato se cargo en cada contrato sin valor_banco")
        nuevas, filas, afectadas = analizar_plan_b(ctx, ranuras, comp)
        try:
            guardar_lecciones(ctx, nuevas, "plan B (comparacion del %s)" % ctx.hoy.strftime("%d-%m-%Y"))
        except Exception as e:
            decir("  Aviso: no pude guardar Json\\%s (%s). Esta vez sigo igual." % (ARCHIVO_LECCIONES, e))
        cuenta = Counter(f["situacion"] if not f["hecho"] else "Se prueba con el otro %s" %
                         CAMPO_TEXTO.get(f["hecho"]["campo"], "").lower() for f in filas)
        for sit, n in sorted(cuenta.items(), key=lambda kv: -kv[1]):
            decir("  %4d  %s" % (n, sit))
        confirmadas = [v for v in nuevas.values() if v.get("estado") == "confirmado"]
        if confirmadas:
            decir("  %d dato(s) que se estaban probando ya parean: quedan confirmados." % len(confirmadas))
        recargar = []
        if afectadas:
            decir("")
            decir("3) Preparando de nuevo %d archivo(s) (el anterior queda en 02_Para_Cargar\\_respaldo)" % len(afectadas))
            ctx.forzar = set(afectadas)
            preparar_archivos(ctx, ranuras, manifiesto)
            _verificar_plan_b(ctx, ranuras, afectadas)
            carpeta = ctx.dir_cargar / ("_RECARGAR_PlanB_%s" % hora[:4])
            for clave, cambios in sorted(afectadas.items()):
                r = ranuras[clave]
                if r.salida is None or not r.salida.exists():
                    continue
                try:
                    ruta_larga(carpeta).mkdir(parents=True, exist_ok=True)
                    shutil.copy2(str(ruta_larga(r.salida)), str(ruta_larga(carpeta / r.salida.name)))
                except Exception as e:
                    LOG.warning("No pude copiar %s: %s", r.salida.name, e)
                recargar.append([r.salida.name, len(cambios), mostrar(r.salida)])
                malos_v = [h for h in cambios if h.get("verificado") != "si"]
                decir("  %-70s %d contrato(s)%s" % (r.salida.name[:70], len(cambios),
                                                   "" if not malos_v else "  ATENCION: %d no quedaron" % len(malos_v)))
            guardar_foto(ctx)
        else:
            decir("")
            decir("  No hay archivos que volver a preparar.")
        destino, movidos = _mover_comparaciones(ctx, archivos, hora[:4])
        ruta = ctx.dia / ("PlanB_Comparaciones_%s_%s.xlsx" % (ctx.hoy.strftime("%Y-%m-%d"), hora))
        try:
            _excel_plan_b(ruta, filas, recargar, leidos, malos)
        except Exception as e:
            decir("  No pude escribir el informe (%s)." % e)
            ruta = None
        decir("")
        if recargar:
            decir("CARGA DE NUEVO en el aplicativo solo estos %d archivo(s): %s" % (len(recargar), mostrar(carpeta)))
            decir("Despues descarga otra vez la Comparacion: si quedan sin valor_banco, deja las nuevas en")
            decir("04_Comparaciones y vuelve a ejecutar el plan B (prueba con el siguiente dato).")
        if ruta:
            decir("Detalle por contrato: %s" % mostrar(ruta))
        decir("Comparaciones usadas: %s (%d)" % (mostrar(destino), movidos))
        decir("Log: %s" % ruta_log)
        if ctx.conf.get("abrir_carpeta_al_terminar", True) and ctx.interactivo:
            try:
                os.startfile(mostrar(carpeta if recargar else ctx.dia))
            except Exception:
                pass
    finally:
        ctx.excel.cerrar()
        try:
            candado.unlink()
        except OSError:
            pass
    return 0


# =============================================================================
# Correo de contratos que la contraparte no envio (en ingles)
# =============================================================================
#   configuracion.json > correo_faltantes

FALTANTES_POR_DEFECTO = {"activo": True, "para": ["iperalta@cuprum.cl"], "enviar": True,
                         "excluir_trades_del_cierre": True, "firma": "Back Office - AFP Cuprum",
                         "aviso_liquidacion_dias": 3}
FONDOS_EN = {"A": "Pension Fund Type A", "B": "Pension Fund Type B", "C": "Pension Fund Type C",
             "D": "Pension Fund Type D", "E": "Pension Fund Type E"}


def conf_faltantes(ctx):
    conf = dict(FALTANTES_POR_DEFECTO)
    conf.update({k: v for k, v in (ctx.conf.get("correo_faltantes") or {}).items() if not str(k).startswith("_")})
    if isinstance(conf.get("para"), str):
        conf["para"] = [conf["para"]]
    return conf


def faltantes_por_contraparte(ctx):
    """{codigo Vmetrix: [operaciones de cartera vigentes que la contraparte no mando]} (solo contrapartes y tipos
    cuyo statement llego hoy). Sin las operaciones del mismo dia del cierre (normalmente llegan al dia siguiente)."""
    est = ctx.pareo
    if not est or not est.get("ok"):
        return {}
    conf = conf_faltantes(ctx)
    sin_stm, _ = _filas_sin_statement(ctx)
    salida = {}
    reales = est.get("cobertura_real") or set()
    for c in sin_stm:
        if conf.get("excluir_trades_del_cierre", True) and c.get("td") is not None and c["td"] >= est["cob"]:
            continue
        if (c["cp"], c["fondo"], c["tipo"]) not in reales:
            continue        # ese statement se armo con el de un cierre anterior: no se piden contratos
        salida.setdefault(c["cp"], []).append(c)
    return salida


def _monto(x):
    try:
        return format(float(x), ",.2f")
    except (TypeError, ValueError):
        return normalizar(x)


def _fecha_en(d):
    return "%02d-%s-%d" % (d.day, MESES_EN[d.month - 1], d.year) if d else ""


def html_faltantes(ctx, nombre, lista):
    """Cuerpo del correo en ingles para pedir los contratos a la contraparte."""
    import html as _h
    e = lambda v: _h.escape("" if v is None else str(v))
    conf = conf_faltantes(ctx)
    cob = ctx.pareo["cob"]
    inv = ctx.pareo.get("memoria_inv") or {}
    th = "border:1px solid #BFBFBF;padding:4px 8px;background:#1F3864;color:#FFFFFF;text-align:left;"
    td = "border:1px solid #BFBFBF;padding:4px 8px;"
    pronto = cob
    for _ in range(int(conf.get("aviso_liquidacion_dias", 3))):
        pronto = pronto + dt.timedelta(days=1)
        while not es_habil(pronto, FERIADOS):
            pronto = pronto + dt.timedelta(days=1)
    filas = []
    for c in sorted(lista, key=lambda x: (x["fondo"], x["tipo"], x.get("md") or dt.date.max, x["id"])):
        if c["tipo"] == "FX":
            otra = [m for m in c["patas"] if m != c["base"]]
            producto = "NDF" if c.get("ndf") else "FX Forward"
            par = "%s/%s" % (c["base"], otra[0] if otra else "")
            nominal = "%s %s" % (c["base"], _monto(c["patas"][c["base"]]))
            if otra:
                nominal += " / %s %s" % (otra[0], _monto(c["patas"][otra[0]]))
            tasa = ""           # forwards / NDF: la tasa no aplica (solo los swaps la llevan)
            lado = ""
            if c.get("compra_base") is not None and otra:
                lado = ("Cuprum buys %s / sells %s" % (c["base"], otra[0]) if c["compra_base"]
                        else "Cuprum sells %s / buys %s" % (c["base"], otra[0]))
        else:
            producto = "Interest Rate Swap"
            par = c.get("moneda", "")
            nominal = "%s %s" % (c.get("moneda", ""), _monto(c.get("nominal")))
            tasa = ("%s%%" % normalizar(c["tasa"])) if c.get("tasa") is not None else ""
            lado = "Cuprum pays fixed" if c.get("afp_paga_fija") else "Cuprum receives fixed"
        nota = ""
        if c.get("md") is not None and c["md"] <= pronto:
            nota = "Settles %s - please confirm if it was excluded because it already fixed" % _fecha_en(c["md"])
        suyo = inv.get(str(c["id"]))
        ref_cp = ("%s (in your statement of %s)" % (suyo[0], suyo[1])) if suyo else ""
        filas.append([FONDOS_EN.get(c["fondo"], c["fondo"]), producto, _fecha_en(c.get("td")), _fecha_en(c.get("md")),
                      par, nominal, tasa, lado, ref_cp, c["id"], nota])
    enc = ["Fund", "Product", "Trade Date", "Maturity / Value Date", "Currency", "Notional", "Rate", "Direction",
           "Your Trade ID", "Our Deal No.", "Comment"]
    if not any(f[6] for f in filas):        # solo forwards: sin columna Rate
        enc = enc[:6] + enc[7:]
        filas = [f[:6] + f[7:] for f in filas]
    tabla = ("<table style='border-collapse:collapse;font-family:Calibri,Arial;font-size:10pt;'><tr>%s</tr>%s</table>"
             % ("".join("<th style='%s'>%s</th>" % (th, e(x)) for x in enc),
                "".join("<tr>%s</tr>" % "".join("<td style='%s'>%s</td>" % (td, e(v)) for v in f) for f in filas)))
    return ("<div style='font-family:Calibri,Arial;font-size:11pt;'>"
            "<p>Dear %s team,</p>"
            "<p>While reconciling your MTM statement as of COB <b>%s</b> against our records, we noticed that the "
            "following %d trade(s) are not included in it. Could you please add them to your statement, or confirm "
            "their status (e.g. matured, unwound, fixed or novated)?</p>%s"
            "<p>Thank you in advance.</p><p>Kind regards,<br>%s</p></div>"
            % (e(nombre), _fecha_en(cob), len(filas), tabla, e(conf.get("firma", ""))))


def correo_faltantes(ctx, ranuras, manifiesto=None):
    """Un correo por contraparte (en ingles, para reenviarlo) con los contratos vigentes que no mando.
    Va solo a configuracion.json > correo_faltantes > para. No se repite si la lista no cambio."""
    conf = conf_faltantes(ctx)
    est = ctx.pareo
    try:
        guardar_faltantes_dia(ctx, manifiesto)
    except Exception as e:
        decir("  Aviso: no pude guardar %s (%s)." % (ARCHIVO_FALTANTES, e))
        LOG.warning(traceback.format_exc())
    if not conf.get("activo", True) or not est or not est.get("ok"):
        return
    por_cp = faltantes_por_contraparte(ctx)
    if not por_cp:
        decir("  Contratos que la contraparte no envio: ninguno.")
        return
    nombres = {}
    for rep in ctx.reportes:
        cp = (rep.get("pareo") or {}).get("contraparte_vmetrix")
        if cp and cp not in nombres:
            nombres[cp] = rep.get("contraparte", cp)
    enviados = (manifiesto or {}).setdefault("faltantes_enviados", {}) if manifiesto is not None else {}
    n_ok, n_falla = 0, 0
    decir("  Contratos que la contraparte no envio (vigentes al cierre %s):" % est["cob"].strftime("%d-%m-%Y"))
    for cp, lista in sorted(por_cp.items(), key=lambda kv: nombres.get(kv[0], kv[0])):
        nombre = nombres.get(cp, cp)
        html = html_faltantes(ctx, nombre, lista)
        archivo = ctx.dia / ("Faltantes_%s_%s.html" % (re.sub(r"[^A-Za-z0-9]+", "_", nombre).strip("_"),
                                                       est["cob"].strftime("%Y%m%d")))
        try:
            archivo.write_text(html, encoding="utf-8")
        except Exception:
            pass
        firma = ",".join(sorted("%s-%s" % (c["fondo"], c["id"]) for c in lista))
        decir("    %-20s %3d  (%s)" % (nombre, len(lista), ", ".join(sorted({c["fondo"] for c in lista}))))
        if not conf.get("para"):
            continue
        if enviados.get(cp) == firma:
            decir("      (el correo con esta misma lista ya se envio hoy; no se repite)")
            continue
        asunto = "%sAFP Cuprum - Missing trades in your MTM statement - COB %s - %s" % (
            "[PRUEBA] " if getattr(ctx.args, "prueba", False) else "", _fecha_en(est["cob"]), nombre)
        try:
            import win32com.client
            ol = win32com.client.Dispatch("Outlook.Application")
            correo = ol.CreateItem(0)
            correo.To = "; ".join(conf["para"])
            correo.Subject = asunto
            correo.HTMLBody = html
            if conf.get("enviar", True):
                correo.Send()
            else:
                correo.Display()
            enviados[cp] = firma
            n_ok += 1
        except Exception as e:
            n_falla += 1
            decir("      No pude crear el correo (%s). Queda en %s." % (e, archivo.name))
    if manifiesto is not None:
        guardar_manifiesto(ctx, manifiesto)
    if n_ok:
        decir("  %d correo(s) en ingles para pedir esos contratos %s a %s (para reenviar a cada contraparte)." % (
            n_ok, "enviados" if conf.get("enviar", True) else "abiertos en Outlook", ", ".join(conf["para"])))


ARCHIVO_FALTANTES = "faltantes_dia.json"
IDIOMA_FALTANTES = "en"


def _asunto_faltantes(ctx, nombre):
    return "AFP Cuprum - Missing trades in your MTM statement - COB %s - %s" % (_fecha_en(ctx.pareo["cob"]), nombre)


def _contrato_json(c, inv):
    """Operacion de Vmetrix que falta, con lo necesario para pedirla (sin objetos de Python)."""
    d = {"fondo": c.get("fondo"), "tipo": c.get("tipo"), "id": str(c.get("id")), "ref": normalizar(c.get("ref")),
         "td": c["td"].isoformat() if c.get("td") else None, "md": c["md"].isoformat() if c.get("md") else None}
    if c.get("tipo") == "FX":
        d.update(base=c.get("base"), ndf=bool(c.get("ndf")), compra_base=c.get("compra_base"),
                 patas={k: v for k, v in (c.get("patas") or {}).items()})
    else:
        d.update(moneda=c.get("moneda"), nominal=c.get("nominal"), tasa=c.get("tasa"),
                 afp_paga_fija=c.get("afp_paga_fija"))
    suyo = inv.get(str(c.get("id")))
    if suyo:
        d["su_id"] = [str(x) for x in suyo]
    return d


def guardar_faltantes_dia(ctx, manifiesto):
    """faltantes_dia.json en la carpeta del dia: por contraparte, los contratos vigentes que no mando, el texto
    del correo y con que correo(s) llego su statement de hoy. Lo usa bot_faltantes.py (no manda nada aqui)."""
    est = ctx.pareo
    datos = {"version": 1, "proceso": PROCESO_FALTANTES, "idioma": IDIOMA_FALTANTES,
             "dia": ctx.hoy.isoformat(), "generado": dt.datetime.now().isoformat(timespec="seconds"),
             "script": "colaterales %s" % VERSION, "ok": bool(est and est.get("ok")), "contrapartes": {}}
    if not datos["ok"]:
        datos["motivo"] = "sin pareo con Vmetrix: no se puede saber que contratos faltan"
    else:
        datos["cob"] = est["cob"].isoformat()
        inv = est.get("memoria_inv") or {}
        por_cp = faltantes_por_contraparte(ctx)
        reps_cp = {}
        for rep in ctx.reportes:
            cp = (rep.get("pareo") or {}).get("contraparte_vmetrix")
            if cp:
                reps_cp.setdefault(cp, []).append(rep)
        for cp, lista in por_cp.items():
            reps = reps_cp.get(cp, [])
            nombre = reps[0].get("contraparte", cp) if reps else cp
            dominios = set()
            for rep in reps:
                c_conf = rep.get("correo") or {}
                dominios |= {d.lower().lstrip("@") for d in c_conf.get("dominios") or []}
                dominios |= {r.lower().split("@")[-1] for r in c_conf.get("remitentes") or [] if "@" in r}
            ids = {rep["id"] for rep in reps}
            correos = []
            for archivo, info in sorted(((manifiesto or {}).get("archivos") or {}).items()):
                if info.get("reporte") in ids and info.get("correo_id"):
                    correos.append(dict(info["correo_id"], archivo=archivo, reporte=info.get("reporte"),
                                        fondo=info.get("fondo")))
            datos["contrapartes"][cp] = {
                "nombre": nombre, "reportes": sorted(ids), "dominios": sorted(dominios),
                "firma": ",".join(sorted("%s-%s" % (c["fondo"], c["id"]) for c in lista)),
                "contratos": [_contrato_json(c, inv) for c in
                              sorted(lista, key=lambda x: (x["fondo"], x["tipo"], x.get("md") or dt.date.max, x["id"]))],
                "asunto": _asunto_faltantes(ctx, nombre), "html": html_faltantes(ctx, nombre, lista),
                "correos": correos}
    destino = ctx.dia / ARCHIVO_FALTANTES
    tmp = destino.with_suffix(".tmp")
    tmp.write_text(json.dumps(datos, indent=1, ensure_ascii=False, default=str), encoding="utf-8")
    os.replace(str(tmp), str(destino))


def carpetas_manuales(ctx):
    """Carpetas donde se buscan BofA / Morgan Stanley. Por defecto: la carpeta del dia
    y su 01_Originales (configurable en configuracion.json)."""
    salida = []
    textos = ctx.conf.get("carpetas_archivos_manuales") or ["{DIA}", "{DIA}/01_Originales"]
    for texto in textos:
        t = texto.replace("{BASE}", str(ctx.base)).replace("{DIA}", mostrar(ctx.dia))
        p = ruta_larga(Path(os.path.expanduser(t)))
        if p.is_dir() and p not in salida:
            salida.append(p)
    return salida


def buscar_manuales(ctx, ranuras, manifiesto):
    """Busca los archivos que se descargan a mano (BofA, Morgan Stanley). Si los dejaste
    sueltos en la carpeta del dia, los mueve a 01_Originales."""
    faltantes = [r for r in ranuras.values()
                 if (r.archivo is None or r.arrastre) and r.reporte.get("origen") == "manual"]
    if not faltantes:
        return []
    claves = {r.clave: r for r in faltantes}
    for carpeta in carpetas_manuales(ctx):
        try:
            archivos = sorted(carpeta.iterdir(), key=lambda p: p.stat().st_mtime, reverse=True)
        except OSError:
            continue
        for ruta in archivos:
            if not ruta.is_file():
                continue
            rep, fondo, tipo, fecha = identificar_archivo(ctx, ruta.name)
            if rep is None or rep.get("origen") != "manual":
                continue
            r = claves.get((rep["id"], fondo))
            if r is None or (r.archivo is not None and not r.arrastre):
                continue
            if r.archivo is not None and mostrar(r.archivo).lower() == mostrar(ruta).lower():
                continue            # es el armado con el cierre anterior
            ok, problema = evaluar_fecha(tipo, fecha, ctx)
            if ok is False:
                continue
            ctx.dir_orig.mkdir(parents=True, exist_ok=True)
            armado = None
            if r.arrastre:
                armado = apartar_armado_html(ctx, r, manifiesto, "_cierre_anterior_reemplazado", ORIGEN_CIERRE)
            destino = ctx.dir_orig / ruta.name
            if mostrar(ruta).lower() != mostrar(destino).lower():
                if mostrar(carpeta).lower() == mostrar(ctx.dia).lower():
                    shutil.move(str(ruta), str(destino))      # suelto en la carpeta del dia
                else:
                    shutil.copy2(ruta, destino)
            r.archivo = destino
            r.estado = ESTADO_OK
            r.origen = "manual"
            manifiesto["archivos"][destino.name] = {"reporte": rep["id"], "fondo": fondo, "origen": "manual",
                                                    "copiado_desde": mostrar(ruta)}
            if armado is not None:
                reemplazo_de_cierre_anterior(ctx, r, armado, destino, manifiesto)
    guardar_manifiesto(ctx, manifiesto)
    return [r for r in faltantes if r.archivo is None]


def avisar_manuales(ctx, faltan, avisos_correo):
    decir("")
    decir("  Faltan archivos de descarga MANUAL:")
    por_rep = {}
    for r in faltan:
        por_rep.setdefault(r.reporte["id"], []).append(r)
    for rid, lista in por_rep.items():
        rep = lista[0].reporte
        ejemplo = rep.get("adjunto", {}).get("ejemplo", "")
        decir("   - %s: %d archivo(s) (fondos %s). Ej: %s" % (
            rep.get("contraparte"), len(lista), ", ".join(r.fondo for r in lista), ejemplo))
        llegados = avisos_correo.get(rid, [])
        if llegados:
            ultimo = max(getattr(x, "recibido", None) or x.correo.recibido for x in llegados)
            decir("     (el correo ya llego a Outlook: %s)" % ultimo.strftime("%d-%m %H:%M"))
    decir("  Guardalos en la carpeta de hoy: %s" % mostrar(ctx.dir_orig))


def pedir_manuales_al_final(ctx, ranuras, manifiesto, avisos_correo):
    """Se llama DESPUES de preparar todo lo demas, asi 02_Para_Cargar queda listo en la
    misma ejecucion. Si faltan BofA / Morgan Stanley pregunta; al guardarlos en la carpeta
    de hoy y presionar Enter, los procesa en el acto."""
    while True:
        faltan = buscar_manuales(ctx, ranuras, manifiesto)
        if faltan and paso("Cierre anterior", aplicar_cierre_anterior, ctx, ranuras, manifiesto):
            faltan = [r for r in faltan if r.archivo is None]
        paso("Preparacion", preparar_archivos, ctx, ranuras, manifiesto)    # solo procesa lo nuevo
        if not faltan:
            return
        avisar_manuales(ctx, faltan, avisos_correo)
        if not ctx.interactivo or not ctx.conf.get("pausar_por_archivos_manuales", True):
            for r in faltan:
                r.observaciones.append("Archivo manual no encontrado")
            return
        try:
            ctx.dir_orig.mkdir(parents=True, exist_ok=True)
            os.startfile(mostrar(ctx.dir_orig))
        except Exception:
            pass
        decir("  (todo lo demas ya quedo listo en 02_Para_Cargar)")
        decir("  (si no hay del dia, puedes dejar el del cierre anterior: queda con las fechas de hoy)")
        resp = preguntar("  [Enter] = ya los guarde, procesarlos   |   S = terminar sin ellos: ", ctx.interactivo, "S")
        if resp.upper().startswith("S"):
            for r in faltan:
                r.observaciones.append("Archivo manual no encontrado (se termino sin el)")
            return


def preparar_archivos(ctx, ranuras, manifiesto):
    """Genera 02_Para_Cargar a partir de 01_Originales. Lo que ya estaba preparado
    en una ejecucion anterior NO se toca (asi se conservan correcciones a mano) y
    el reporte muestra el estado que tuvo en esa ejecucion."""
    ctx.dir_cargar.mkdir(parents=True, exist_ok=True)
    resumen_ajustes = ctx.resumen_ajustes
    motor = ctx.conf.get("motor_excel", "excel")
    preparados = manifiesto.setdefault("preparados", {})
    for r in sorted(ranuras.values(), key=lambda x: (x.reporte.get("contraparte", ""), x.fondo)):
        if r.archivo is None or r.clave in ctx.hechos:
            continue
        ctx.hechos.add(r.clave)
        rep = r.reporte
        destino = ctx.dir_cargar / nombre_de_salida(rep, r.archivo.name)
        r.salida = destino
        ajustes = ajustes_del_reporte(ctx, rep, r.fondo)
        if destino.exists() and not ctx.args.reprocesar and r.clave not in ctx.forzar:
            previo = preparados.get(destino.name)
            if previo:
                r.estado = previo.get("estado", r.estado)
                r.observaciones = list(previo.get("observaciones", []))
                r.cambios = previo.get("cambios", 0)
                r.detalle_cambios = list(previo.get("cambios_detalle", []))
                for clave, estado in previo.get("ajustes", {}).items():
                    resumen_ajustes.setdefault(clave, tuple(estado))
                r.preparado_antes = previo.get("hora", "?")
            else:
                r.preparado_antes = "?"
            pareo_solo_lectura(ctx, r, destino)
            continue
        ctx.preparados_ahora += 1
        if destino.exists():
            respaldar(destino, ctx.dir_cargar / "_respaldo")
        res = None
        try:
            reglas = [x for x in rep.get("transformaciones", []) if x.get("activo", True)]
            referencia = buscar_referencia_anterior(ctx, rep, r.fondo)
            origen = r.archivo
            conv = rep.get("convertir_formato_nuevo") or {}
            nota_conv = None
            if conv and conv.get("activo", True):
                convertido, nota_conv = convertir_formato_nuevo(r, Libro(r.archivo), conv)
                if convertido:
                    origen = r.archivo_convertido = convertido
                    LOG.info("[%s] %s", rep["id"], nota_conv)
            con_pareo = bool(ctx.pareo and ctx.pareo.get("ok") and (rep.get("pareo") or {}).get("tipos"))
            if not reglas and not ajustes and referencia is None and not con_pareo:
                shutil.copy2(origen, destino)
                if nota_conv:
                    r.observaciones.append(nota_conv)
                    r.estado = ESTADO_OBS if r.estado == ESTADO_OK else r.estado
                continue
            libro = Libro(origen)
            res = aplicar_reglas(libro, rep, r.fondo, ajustes, referencia=referencia)
            if nota_conv:
                res.obs.insert(0, nota_conv)
            if con_pareo:
                # Al final: deja fechas, centavos y tasas iguales a la cartera de Vmetrix
                try:
                    pr = pareo_archivo(ctx, r, libro, res)
                except Exception as e:
                    pr = None
                    res.obs.append("No pude parear con Vmetrix: %s" % e)
                    LOG.error(traceback.format_exc())
                if pr:
                    cambios, n_ops, n_par, n_sin = pr
                    texto = "Vmetrix: %d de %d operaciones pareadas" % (n_par, n_ops)
                    if cambios:
                        texto += "; igualadas a cartera: " + ", ".join("%s %d" % kv for kv in sorted(cambios.items()))
                    if n_sin:
                        texto += "; %d sin pareja en cartera" % n_sin
                    if any(k.startswith(("Nominal", "Tasa")) for k in cambios):
                        res.obs.append(texto)
                    else:
                        res.info.append(texto)
            for clave, estado in res.ajustes.items():
                previo = resumen_ajustes.get(clave)
                if previo is None or previo[0] in ("no_encontrada", "ya_correcto", "no_evaluado"):
                    resumen_ajustes[clave] = estado
            if not res.ediciones:
                shutil.copy2(origen, destino)
            else:
                avisos_esc, fallas = escribir_y_verificar(ctx, libro, origen, destino, res.ediciones, motor)
                r.observaciones += avisos_esc
                if fallas:
                    r.estado = ESTADO_ERROR
                    r.observaciones.append("%d de %d correcciones NO quedaron en el archivo (ej. %s). No lo cargues "
                                           "sin revisarlo; detalle en el log" % (len(fallas), len(res.ediciones),
                                                                                 "; ".join(fallas[:2])))
                    LOG.error("[%s %s] correcciones que no quedaron: %s", rep["id"], r.fondo, fallas)
                r.cambios = len(res.ediciones)
                for e in res.ediciones:
                    LOG.info("[%s %s] %s", rep["id"], r.fondo, e.describir(libro))
                    r.detalle_cambios.append([libro.hojas[e.hoja].nombre, "%s%d" % (indice_a_letra(e.col), e.fila + 1),
                                              e.col_nombre, e.operacion, normalizar(e.anterior), normalizar(e.nuevo),
                                              e.regla, e.detalle])
            r.observaciones += res.obs + res.info
            if res.obs and r.estado == ESTADO_OK:
                r.estado = ESTADO_OBS
            if res.avisos and r.estado != ESTADO_ERROR:
                r.estado = ESTADO_REVISAR
                r.observaciones += res.avisos
        except Exception as e:
            r.estado = ESTADO_ERROR
            r.observaciones.append("Error al transformar: %s" % e)
            LOG.error(traceback.format_exc())
            try:
                shutil.copy2(r.archivo, destino)
                r.observaciones.append("se dejo una copia SIN corregir en 02_Para_Cargar")
            except Exception:
                pass
        finally:
            preparados[destino.name] = {
                "reporte": rep["id"], "fondo": r.fondo,
                "estado": r.estado, "observaciones": list(r.observaciones), "cambios": r.cambios,
                "hora": dt.datetime.now().strftime("%H:%M"),
                "ajustes": {k: list(v) for k, v in (res.ajustes.items() if res else [])},
                "cambios_detalle": r.detalle_cambios}
    guardar_manifiesto(ctx, manifiesto)
    return resumen_ajustes



# =============================================================================
# Conversion de formatos nuevos al formato que lee el aplicativo
# =============================================================================

SG_FX_COLUMNAS = ["Product Family", "Product", "Client", "Deal Id", "Client Way", "Trade Date", "Value Date",
                  "Maturity Date", "Client Id", "Notional Amount", "Currency", "Underlying", "Valuation Date",
                  "MID MtM", "MID MtM (USD)", "Spot Rate", "Forward Rate", "Revaluated Forward Rate",
                  "Notional2CCY", "Notional 2"]
SG_FX_PRODUCTO = {"FW": "Forward", "NDF": "Non deliverable forward", "FWFW": "Forward Forward",
                  "SW": "Swap", "SP": "Spot"}
SG_FX_ANCHOS = [1316, 5485, 11849, 20736, 4205, 2633, 6290, 6290, 6290, 5266, 7680, 3693, 4205, 5229, 7680, 7680,
                4608, 4608, 4608, 3693, 4608]


def es_sg_fx_nuevo(libro):
    """Formato que SG usa desde el 20-10-2026: 'Valuation of Fx Deals', agrupado por fondo,
    par de monedas y fecha de flujo (sin columnas Client, Maturity Date ni Notional 2)."""
    for h in libro.hojas:
        if h.nombre.lower() != "position":
            continue
        for fila in h.filas[:5]:
            if any(isinstance(v, str) and v.strip().lower().startswith("valuation of fx deals") for v in fila):
                return True
        encabezados = {normalizar_encabezado(v) for fila in h.filas[:60] for v in fila if isinstance(v, str)}
        return "deal type" in encabezados and "client" not in encabezados and "flow type (**)" in encabezados
    return False


def leer_sg_fx_nuevo(libro, conf):
    """Lee el formato nuevo y devuelve las operaciones con las columnas del formato anterior."""
    h = next(x for x in libro.hojas if x.nombre.lower() == "position")
    rx_fondo = re.compile(r"TIPO\s+([A-E])\b")
    fecha_val = None
    for fila in h.filas[:5]:
        for v in fila:
            m = re.search(r"(\d{1,2}-[A-Za-z]{3}-\d{4})", str(v or ""))
            if m and "valuation" in str(v).lower():
                fecha_val = fecha_desde_texto(m.group(1))
    ids_cliente = conf.get("id_cliente", {})
    cliente = fondo = par = flujo = None
    enc = None
    salida = {}
    for fila in h.filas:
        t0 = str(fila[0]).strip() if fila and fila[0] is not None else ""
        m = rx_fondo.search(t0)
        if m and "CUPRUM" in t0.upper():
            cliente, fondo, enc = t0, m.group(1), None
            continue
        m = re.match(r"^\d+\)\s*([A-Z]{3})\s*/\s*([A-Z]{3})", t0)
        if m:
            par, enc = (m.group(1), m.group(2)), None
            continue
        if t0.lower().startswith("flow date"):
            flujo = next((fecha_desde_texto(v) for v in fila[1:] if fecha_desde_texto(v)), None)
            continue
        if t0 == "Deal Id":
            enc = [normalizar_encabezado(v) for v in fila]
            continue
        if not enc or not t0:
            continue
        d = {enc[j]: fila[j] for j in range(min(len(enc), len(fila))) if enc[j]}
        via = str(d.get("client way (*)", "")).strip()
        if via not in ("B", "S"):
            continue
        tipo = str(d.get("deal type", "")).strip()
        flow = str(d.get("flow type (**)", "")).strip()
        nominal = d.get("notional amount")
        moneda = str(d.get("notional amount cur.", "")).strip()
        fwd = d.get("forward rate")
        n2 = c2 = None
        if par and isinstance(nominal, (int, float)) and isinstance(fwd, (int, float)) and fwd:
            if moneda == par[0]:
                n2, c2 = round(nominal * fwd, 2), par[1]
            else:
                n2, c2 = round(nominal / fwd, 2), par[0]
        fila_vieja = {
            "Product Family": "FOREX", "Product": SG_FX_PRODUCTO.get(tipo, tipo), "Client": cliente,
            "Deal Id": t0, "Client Way": via,
            "Trade Date": fecha_desde_texto(d.get("trade date")), "Value Date": fecha_desde_texto(d.get("value date")),
            "Maturity Date": flujo, "Client Id": ids_cliente.get(fondo, ""), "Notional Amount": nominal,
            "Currency": moneda, "Underlying": "%s/%s" % par if par else "", "Valuation Date": fecha_val,
            "MID MtM": d.get("mid mtm"), "MID MtM (USD)": d.get("mid mtm (usd)"), "Spot Rate": d.get("spot rate"),
            "Forward Rate": fwd, "Revaluated Forward Rate": d.get("revaluated forward rate"),
            "Notional2CCY": c2, "Notional 2": n2, "_fondo": fondo, "_flow": flow}
        # Un swap viene en dos filas (N = pata corta, F = pata larga): queda la larga, como antes
        previo = salida.get(t0)
        if previo is None or flow in ("F", "T"):
            salida[t0] = fila_vieja
    filas = sorted(salida.values(), key=lambda x: (x["Maturity Date"] or dt.date.max, x["Deal Id"]))
    return filas


def escribir_sg_fx_antiguo(libro_nuevo, filas, destino):
    """Escribe un .xls con el formato anterior de SG FX Cash (hoja Position plana)."""
    import xlwt
    wb = xlwt.Workbook(encoding="utf-8")
    base = "font: name Arial, height 200"
    st_txt = xlwt.easyxf(base)
    st_enc = xlwt.easyxf(base + ", bold on")
    st_fecha = xlwt.easyxf(base, num_format_str="dd-mmm-yyyy")
    st_monto = xlwt.easyxf(base, num_format_str="###,##0.00")
    st_tasa = xlwt.easyxf(base, num_format_str="#####0.00000000")
    st_gral = xlwt.easyxf(base)
    estilo = {"Trade Date": st_fecha, "Value Date": st_fecha, "Maturity Date": st_fecha, "Valuation Date": st_fecha,
              "Notional Amount": st_monto, "MID MtM": st_monto, "MID MtM (USD)": st_monto,
              "Spot Rate": st_tasa, "Forward Rate": st_tasa, "Revaluated Forward Rate": st_tasa, "Notional 2": st_gral}
    for h in libro_nuevo.hojas:              # portada y textos legales tal como vienen
        if h.nombre.lower() in ("position", "parameters"):
            continue
        ws = wb.add_sheet(h.nombre[:31])
        for i, fila in enumerate(h.filas):
            for j, v in enumerate(fila):
                if v is not None and v != "":
                    ws.write(i, j, v if not isinstance(v, (dt.datetime, dt.date)) else str(v), st_txt)
        ws.col(0).width = 30000 if h.nombre.lower().startswith("important") else ws.col(0).width
    ws = wb.add_sheet("Position")
    for j, ancho in enumerate(SG_FX_ANCHOS):
        ws.col(j).width = ancho
    ws.write_merge(1, 2, 1, 2, "SOCIETE GENERALE\nCorporate & Investment Banking\n", st_enc)
    ws.write_merge(6, 6, 1, 5, "Please note that the valuation is from YOUR PERSPECTIVE", st_txt)
    for j, nombre in enumerate(SG_FX_COLUMNAS, 1):
        ws.write(8, j, nombre, st_enc)
    base_fecha = dt.datetime(1899, 12, 30)
    for i, f in enumerate(filas, 9):
        for j, nombre in enumerate(SG_FX_COLUMNAS, 1):
            v = f.get(nombre)
            if v is None or v == "":
                continue
            if isinstance(v, (dt.datetime, dt.date)):
                d = v if isinstance(v, dt.datetime) else dt.datetime(v.year, v.month, v.day)
                v = float((d - base_fecha).days)
            ws.write(i, j, v, estilo.get(nombre, st_txt))
    wb.save(str(destino))


def convertir_formato_nuevo(r, libro, conf):
    """Si la contraparte mando el formato nuevo, lo convierte al anterior en una carpeta temporal.
    Devuelve (ruta convertida, nota) o (None, None) si no hacia falta."""
    tipo = conf.get("tipo")
    if tipo != "sg_fx_deals" or not es_sg_fx_nuevo(libro):
        return None, None
    try:
        import xlwt  # noqa: F401
    except ImportError:
        raise RuntimeError("SG mando el FX en el formato nuevo y para convertirlo falta la libreria xlwt. "
                           "Instala con: pip install xlwt")
    filas = leer_sg_fx_nuevo(libro, conf)
    if not filas:
        raise RuntimeError("SG mando el FX en un formato nuevo que no pude leer (0 operaciones)")
    destino = carpeta_temporal() / r.archivo.name
    escribir_sg_fx_antiguo(libro, filas, destino)
    por_fondo = Counter(f["_fondo"] for f in filas)
    nota = ("SG mando el FX en el formato nuevo (Valuation of Fx Deals); se convirtio al formato anterior: "
            "%d operaciones (%s)" % (len(filas), ", ".join("F%s %d" % kv for kv in sorted(por_fondo.items()))))
    return destino, nota


RX_FONDO_FILA = re.compile(r"(?:\bTIPO|\bFUND|\bTY|\bTYPE|\bFONDO)\s+([A-E])\b|\bAFP([A-E])\b|\bCUPF([A-E])\b"
                           r"|\bCUPRUM\s+([A-E])\b", re.IGNORECASE)
RX_ID_OPERACION = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._/\-]{3,39}$")
RX_NUMERO_TEXTO = re.compile(r"^\(?[-+]?[\d,]*\.?\d+\)?%?$")


def fondo_en_texto(texto):
    m = RX_FONDO_FILA.search(texto or "")
    return next(g for g in m.groups() if g).upper() if m else None


def es_dato(v):
    """Numero o fecha (aunque venga como texto, ej. '2,250,000.00' o '09 Apr 2026')."""
    if isinstance(v, (int, float, dt.datetime, dt.date)) and not isinstance(v, bool):
        return True
    t = str(v).strip()
    return bool(RX_NUMERO_TEXTO.match(t)) or fecha_desde_texto(t) is not None


def contar_instrumentos(libro, rep, fondo):
    """Operaciones que trae el archivo, por fondo: {fondo: set(N operacion)}.
    Una operacion con varias filas (patas) cuenta una vez. No cuenta totales, notas ni
    tablas de otro tipo que vengan debajo (ej. el colateral en Deutsche)."""
    salida = {}
    unico = fondo if len(rep.get("fondos", [])) > 1 else None
    for t in detectar_tablas(libro, rep.get("tabla")):
        if t.ji is None:
            continue
        seccion = None          # fondo indicado en el titulo de la tabla (ej. SG IRD)
        for k in range(t.fila_enc - 1, max(t.fila_enc - 10, -1), -1):
            seccion = fondo_en_texto(" ".join(str(v) for v in t.hoja.filas[k] if isinstance(v, str)))
            if seccion:
                break
        for i in t.filas_datos():
            fila = [v for v in t.hoja.filas[i] if v is not None and str(v).strip() != ""]
            if len(fila) >= 5 and not any(es_dato(v) for v in fila):
                break           # fila de titulos de otra tabla: termina esta
            ident = normalizar(t.hoja.valor(i, t.ji))
            if len(fila) < 3 or not RX_ID_OPERACION.match(ident) or fecha_desde_texto(ident) is not None:
                continue
            fd = unico or fondo_en_texto(" ".join(str(v) for v in t.hoja.filas[i] if isinstance(v, str))) or seccion or "?"
            salida.setdefault(fd, set()).add(ident)
    return salida


def contar_todos(ctx, ranuras):
    """Cuenta los instrumentos de cada archivo recibido (sobre el original de 01_Originales)."""
    for r in ranuras.values():
        r.conteo = {}
        if r.archivo is None:
            continue
        # El convertido (o el de 02_Para_Cargar) tiene el formato que lee el aplicativo
        for ruta in (r.archivo_convertido, r.salida, r.archivo):
            if ruta is None:
                continue
            try:
                if not Path(ruta).exists():
                    continue
                r.conteo = contar_instrumentos(Libro(ruta), r.reporte, r.fondo)
            except Exception as e:
                LOG.info("no pude contar instrumentos de %s: %s", ruta, e)
            if r.conteo:
                break


def tabla_conteo(ranuras):
    """Filas por contraparte y fondo: instrumentos en sus archivos (union de todos sus reportes)."""
    por = {}
    for r in ranuras.values():
        for fd, ids in (getattr(r, "conteo", None) or {}).items():
            clave = (r.reporte.get("contraparte", ""), fd)
            d = por.setdefault(clave, {"ids": set(), "detalle": {}})
            d["ids"] |= ids
            d["detalle"][r.reporte["id"]] = d["detalle"].get(r.reporte["id"], 0) + len(ids)
    return [(c, fd, len(d["ids"]), " | ".join("%s %d" % kv for kv in sorted(d["detalle"].items())))
            for (c, fd), d in sorted(por.items())]


def buscar_referencia_anterior(ctx, rep, fondo):
    """Ultimo archivo de 02_Para_Cargar de dias anteriores para el mismo reporte y fondo
    (el que ya se cargo en el aplicativo, incluidas las correcciones a mano)."""
    conf = rep.get("copiar_de_anterior")
    if not conf or not conf.get("activo", True):
        return None
    sub = ctx.conf.get("subcarpetas_dia", {}).get("para_cargar", "02_Para_Cargar")
    limite = ctx.hoy - dt.timedelta(days=int(conf.get("dias_atras", 10)))
    try:
        dias = sorted((p for p in ctx.raiz_descargas.iterdir() if p.is_dir()), key=lambda p: p.name, reverse=True)
    except OSError:
        return None
    varios = len(rep.get("fondos", [])) > 1
    for d in dias:
        f = fecha_desde_texto(d.name)
        if f is None or not (limite <= f < ctx.hoy):
            continue
        carpeta = d / sub
        if not carpeta.is_dir():
            continue
        for archivo in sorted(carpeta.iterdir()):
            if not archivo.is_file() or archivo.name.startswith("~$"):
                continue
            r2, f2, _, _ = identificar_archivo(ctx, archivo.name)
            if r2 is None:
                r2, f2 = identificar_por_contenido(ctx, rep, archivo)
            if r2 is not None and r2["id"] == rep["id"] and (not varios or f2 == fondo):
                return archivo, f
    return False


def identificar_por_contenido(ctx, rep, archivo):
    """Archivo con nombre corto (ej. EXPOSU_1.XLS): busca en sus primeras filas un texto que,
    con la extension del nombre estandar, calce con el patron del reporte."""
    plantilla = (rep.get("adjunto") or {}).get("nombre_estandar")
    if not plantilla or not re.fullmatch(r"[^.]{1,8}\.[A-Za-z0-9]{1,4}", archivo.name):
        return None, None
    ext = os.path.splitext(plantilla)[1]
    try:
        libro = Libro(archivo)
        for hoja in libro.hojas[:1]:
            for fila in hoja.filas[:15]:
                for v in fila[:10]:
                    if isinstance(v, str) and len(v) > 10:
                        r2, f2, _, _ = identificar_archivo(ctx, v.strip() + ext)
                        if r2 is not None:
                            return r2, f2
    except Exception as e:
        LOG.info("no pude leer %s para identificarlo: %s", archivo, e)
    return None, None


def paso(nombre, funcion, *argumentos):
    """Ejecuta un paso; si falla, lo informa y el proceso sigue con el siguiente."""
    try:
        return funcion(*argumentos)
    except Exception as e:
        decir("  ERROR en el paso '%s': %s. Sigo con el siguiente paso." % (nombre, e))
        LOG.error(traceback.format_exc())
        return None


def valor_escrito_ok(leido, nuevo):
    """El valor que quedo en el archivo es el que se quiso escribir (mismo valor y tipo)."""
    if coincide(leido, nuevo):
        return True
    if isinstance(nuevo, (dt.datetime, dt.date)) and isinstance(leido, (int, float)) and not isinstance(leido, bool):
        base = dt.datetime(1899, 12, 30)
        d = nuevo if isinstance(nuevo, dt.datetime) else dt.datetime(nuevo.year, nuevo.month, nuevo.day)
        return abs(leido - (d - base).total_seconds() / 86400.0) < 1e-6
    if isinstance(nuevo, str) and isinstance(leido, str):
        return leido.strip() == nuevo.strip()
    return False


def verificar_salida(destino, ediciones):
    """Relee el archivo que quedo en 02_Para_Cargar y devuelve las celdas que NO quedaron
    con su valor nuevo (lista vacia = todo bien)."""
    try:
        leido = Libro(destino)
    except Exception as e:
        return ["no pude releer el archivo (%s)" % e]
    fallas = []
    for e in ediciones:
        if e.hoja >= len(leido.hojas):
            fallas.append("falta la hoja %d" % (e.hoja + 1))
            continue
        v = leido.hojas[e.hoja].valor(e.fila, e.col)
        if not valor_escrito_ok(v, e.nuevo):
            fallas.append("%s%d: esperaba %r y quedo %r" % (indice_a_letra(e.col), e.fila + 1,
                                                             valor_para_json(e.nuevo), valor_para_json(v)))
    return fallas


def escribir_y_verificar(ctx, libro, origen, destino, ediciones, motor):
    """Escribe el archivo y confirma, releyendolo, que cada correccion quedo guardada.
    Si con Excel no quedo (y es .xlsx), reintenta con openpyxl. Devuelve (avisos, fallas)."""
    avisos = []
    aviso = escribir_libro(ctx, libro, origen, destino, ediciones, motor)
    if aviso:
        avisos.append(aviso)
    # Si una celda se cambio dos veces (regla y luego pareo), se verifica el valor final
    ediciones = list(OrderedDict(((e.hoja, e.fila, e.col), e) for e in ediciones).values())
    fallas = verificar_salida(destino, ediciones)
    if fallas and libro.formato == "xlsx" and not aviso:
        LOG.warning("Excel no dejo guardadas %d correcciones en %s (%s); reintento con openpyxl",
                    len(fallas), destino.name, fallas[:3])
        libro.guardar_xlsx_openpyxl(destino, ediciones)
        fallas2 = verificar_salida(destino, ediciones)
        if not fallas2:
            avisos.append("Excel no guardo las correcciones; se guardo con openpyxl y se verifico")
        fallas = fallas2
    return avisos, fallas


def escribir_libro(ctx, libro, origen, destino, ediciones, motor):
    """CSV: como texto. Excel: con Excel instalado (motor 'excel', igual que a mano);
    si Excel no esta disponible, los .xlsx se escriben con openpyxl y se avisa."""
    if libro.formato == "csv":
        libro.guardar_csv(destino, ediciones)
        return ""
    if libro.formato == "xlsx" and motor == "auto":
        libro.guardar_xlsx_openpyxl(destino, ediciones)
        return ""
    nombres = [h.nombre for h in libro.hojas]
    try:
        ctx.excel.aplicar(origen, destino, ediciones, nombres, libro.formato)
        return ""
    except Exception as e:
        if libro.formato != "xlsx":
            raise
        LOG.warning("Excel no disponible (%s); uso openpyxl", e)
        libro.guardar_xlsx_openpyxl(destino, ediciones)
        return "guardado con openpyxl porque Excel no respondio (%s)" % e


