def escribir_reporte(ctx, ranuras, resumen_ajustes, inicio):
    lineas = []
    hora = dt.datetime.now()
    lineas.append("REPORTE COLATERALES %s  (generado %s por %s)" % (ctx.hoy, hora.strftime("%d-%m-%Y %H:%M"), ctx.login))
    lineas.append("Fecha de cierre esperada: %s" % " o ".join(str(c) for c in ctx.cobs))
    lineas.append("")
    conteo = {}
    for r in ranuras.values():
        conteo[r.estado] = conteo.get(r.estado, 0) + 1
    lineas.append("RESUMEN: " + " | ".join("%s: %d" % (k, v) for k, v in sorted(conteo.items())))
    lineas.append("")
    filas_csv = [["Contraparte", "Reporte", "Fondo", "Estado", "Origen", "Archivo original", "Archivo para cargar",
                  "Cambios", "Preparado en ejecucion anterior", "Correo", "Observaciones"]]
    for r in sorted(ranuras.values(), key=lambda x: (x.estado == ESTADO_OK, x.reporte.get("contraparte", ""), x.fondo)):
        if r.estado == ESTADO_FALTA and not r.observaciones:
            r.observaciones.append("No llego, o no lo encontre en las carpetas de Outlook configuradas")
        marca ={ESTADO_OK: "[OK]", ESTADO_OBS: "[OK*]", ESTADO_REVISAR: "[!!]", ESTADO_FALTA: "[--]",
                 ESTADO_ERROR: "[XX]"}.get(r.estado, "[??]")
        lineas.append("%-6s %-18s %-16s fondo %-5s %s%s" % (
            marca, r.reporte.get("contraparte", "")[:18], r.reporte["id"][:16], r.fondo,
            r.salida.name if r.salida else "",
            "   [preparado a las %s, no se volvio a tocar]" % r.preparado_antes if r.preparado_antes else ""))
        for o in r.observaciones:
            lineas.append("         - %s" % o)
        for c in r.candidatos_revisar:
            lineas.append("         ? candidato: %s" % c)
        filas_csv.append([r.reporte.get("contraparte", ""), r.reporte["id"], r.fondo, r.estado, r.origen,
                          r.archivo.name if r.archivo else "", r.salida.name if r.salida else "", str(r.cambios),
                          r.preparado_antes, r.correo, " | ".join(r.observaciones + r.candidatos_revisar)])
    if ctx.no_usados:
        lineas.append("")
        lineas.append("ARCHIVOS EN 01_Originales QUE NO SE USARON")
        for n in ctx.no_usados:
            lineas.append("  - %s" % n)
    if ctx.ajustes:
        lineas.append("")
        lineas.append("RESULTADO ESPERADO POR OPERACION (ajustes_operaciones.json)")
        cuenta = {}
        for a in ctx.ajustes:
            if not a.get("activo", True):
                continue
            estado, detalle = resumen_ajustes.get(id_ajuste(a), ("no_evaluado", ""))
            cuenta[estado] = cuenta.get(estado, 0) + 1
            if estado in ("forzado", "valor_distinto", "no_encontrada"):
                lineas.append("  %-15s %s fondo %s op %s col '%s' %s" % (
                    estado, a.get("reporte"), a.get("fondo", ""), a.get("operacion"), a.get("columna"), detalle))
        lineas.append("  Totales: " + " | ".join("%s: %d" % kv for kv in sorted(cuenta.items())))
        lineas.append("  aplicado = venia con el error conocido y se corrigio | ya_correcto = ya venia como debe quedar | "
                      "forzado = venia con otro valor y se dejo el esperado (mira por que cambio) | "
                      "no_encontrada = la operacion no vino (vencida?) | no_evaluado = el archivo falta o ya estaba preparado")
    if ctx.pareo is not None:
        est = ctx.pareo
        lineas.append("")
        lineas.append("PAREO CON VMETRIX")
        if not est.get("ok"):
            lineas.append("  No se hizo: %s" % est.get("error"))
        else:
            sin_stm, sin_archivo = _filas_sin_statement(ctx)
            lineas.append("  Cartera %s: %d operaciones vigentes al %s" % (est["origen"], len(est["ops"]),
                                                                          est["cob"].strftime("%d-%m-%Y")))
            lineas.append("  Cambios: %d (nominal o tasa: %d) | sin corregir: %d | en cartera y no enviados: %d"
                          % (len(est["cambios"]), sum(1 for x in est["cambios"] if x["rojo"]),
                             len(est["no_corregidos"]), len(sin_stm)))
            n_forz = len(est.get("forzados", []))
            if n_forz:
                lineas.append("  Pareo forzado (no calzaban exacto; por historial o por nominal y fechas): %d" % n_forz)
            resp = est.get("respetados", [])
            if resp:
                cuenta = Counter((x["contraparte"], x["campo"], x["regla"]) for x in resp)
                lineas.append("  Datos que se dejaron como los manda la contraparte (el aplicativo los parea asi): %d"
                              % len(resp))
                for (cp, campo, regla), n in sorted(cuenta.items()):
                    lineas.append("    %-20s %-14s %4d  (%s)" % (cp, campo, n, "politica reportes.json" if regla == "politica"
                                                                  else "aprendido del aplicativo"))
            for c in sin_stm[:40]:
                lineas.append("    no enviado: %-9s F%s %s (Tran %s)" % (c["cp"], c["fondo"], c["ref"][:45], c["id"]))
            if len(sin_stm) > 40:
                lineas.append("    ... y %d mas (hoja 'No lo envia la contraparte' del Excel de pareo)" % (len(sin_stm) - 40))
            for (cp, f, tp), n in sorted(sin_archivo.items()):
                lineas.append("    sin statement %s hoy: %s F%s (%d operaciones en cartera)" % (tp, cp, f, n))
            for T, n, texto, info in getattr(ctx, "seguimiento_resumen", []):
                lineas.append("  Aplicativo, cierre %s: %d contratos sin valor de la contraparte (%s)"
                              % (T.strftime("%d-%m-%Y"), n, texto or "-"))
    filas_conteo = tabla_conteo(ranuras)
    if filas_conteo:
        lineas.append("")
        lineas.append("INSTRUMENTOS EN LOS ARCHIVOS (compara con la columna 'Contraparte' del aplicativo)")
        for c, fd, n, det in filas_conteo:
            lineas.append("  %-20s F%-2s %4d   (%s)" % (c[:20], fd, n, det))
    lineas.append("")
    lineas.append("Duracion: %.0f segundos" % (time.time() - inicio))
    texto = "\n".join(lineas)
    # Un reporte por ejecucion (no se pisan): Reporte_AAAA-MM-DD_HHMMSS
    sufijo = "%s_%s" % (ctx.hoy.strftime("%Y-%m-%d"), hora.strftime("%H%M%S"))
    ruta_txt = ctx.dia / ("Reporte_%s.txt" % sufijo)
    ruta_xlsx = ctx.dia / ("Reporte_%s.xlsx" % sufijo)
    try:
        ruta_txt.write_text(texto, encoding="utf-8")
    except Exception as e:
        decir("No pude escribir el reporte de texto: %s" % e)
    # Hoja "Cambios": cada celda modificada (incluye lo preparado en ejecuciones anteriores de hoy)
    filas_cambios = [["Contraparte", "Reporte", "Fondo", "Archivo para cargar", "Hoja", "Celda", "Columna",
                      "N operacion", "Valor original", "Valor nuevo", "Que se hizo", "Detalle"]]
    for r in sorted(ranuras.values(), key=lambda x: (x.reporte.get("contraparte", ""), x.fondo)):
        for d in r.detalle_cambios:
            hoja, celda, columna, operacion, antes, despues, regla, detalle = (list(d) + [""] * 8)[:8]
            filas_cambios.append([r.reporte.get("contraparte", ""), r.reporte["id"], r.fondo,
                                  r.salida.name if r.salida else "", hoja, celda, columna, operacion, antes, despues,
                                  DESCRIPCION_REGLAS.get(regla, regla), detalle])
    filas_aj = [["Reporte", "Fondo", "N operacion", "Fila (si hay varias)", "Columna", "Error conocido de la contraparte",
                 "Valor esperado", "Tipo", "Formato", "Estado", "Detalle", "Comentario"]]
    for a in ctx.ajustes:
        if not a.get("activo", True):
            continue
        estado, detalle = resumen_ajustes.get(id_ajuste(a), ("no_evaluado", ""))
        cond = ", ".join("%s=%s" % kv for kv in (a.get("condicion") or {}).items())
        if a.get("ocurrencia"):
            cond = (cond + " #%s" % a["ocurrencia"]).strip()
        filas_aj.append([a.get("reporte"), a.get("fondo", ""), a.get("operacion"), cond, a.get("columna"),
                         normalizar(a.get("valor_contraparte")), normalizar(a.get("valor_correcto")),
                         a.get("tipo", ""), a.get("formato", ""), estado, detalle, a.get("comentario", "")])
    try:
        filas_cnt = [["Contraparte", "Fondo", "Instrumentos en el archivo", "Detalle por reporte",
                      "Cartera (aplicativo: cuprum)", "Leidos por el aplicativo (Contraparte)",
                      "No los envia la contraparte", "Enviados pero no leidos"]]
        for n, (c, fd, cant, det) in enumerate(tabla_conteo(ranuras), 2):
            filas_cnt.append([c, "F" + fd, cant, det, "", "",
                              '=IF(E%d="","",MAX(0,E%d-C%d))' % (n, n, n),
                              '=IF(OR(E%d="",F%d=""),"",MAX(0,MIN(C%d,E%d)-F%d))' % (n, n, n, n, n)])
        escribir_excel_reporte(ruta_xlsx, [("Resumen", filas_csv), ("Cambios", filas_cambios),
                                           ("Resultado esperado", filas_aj), ("Conteo", filas_cnt)])
        return texto, ruta_xlsx
    except Exception as e:
        decir("No pude escribir el reporte Excel (%s); queda el de texto." % e)
        return texto, ruta_txt


