def cargar_json_opcional(ruta, por_defecto, avisos):
    """Si falta un JSON que no es indispensable, sigue con valores por defecto y lo avisa."""
    if not Path(ruta).is_file():
        avisos.append("No encontre %s; sigo con valores por defecto. Copia ese archivo de la carpeta compartida."
                      % Path(ruta).name)
        return por_defecto
    return cargar_json(ruta)


def guardar_json(ruta, datos):
    tmp = ruta.with_suffix(ruta.suffix + ".tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(datos, f, ensure_ascii=False, indent=2)
    os.replace(tmp, ruta)


def respaldar(ruta, carpeta_respaldo):
    """Copia un archivo a una carpeta de respaldo con marca de tiempo."""
    if not ruta.exists():
        return None
    carpeta_respaldo.mkdir(parents=True, exist_ok=True)
    destino = carpeta_respaldo / ("%s_%s%s" % (ruta.stem, dt.datetime.now().strftime("%Y%m%d_%H%M%S"), ruta.suffix))
    shutil.copy2(ruta, destino)
    return destino


# =============================================================================
# Fechas
# =============================================================================

MESES = {
    "jan": 1, "ene": 1, "feb": 2, "mar": 3, "apr": 4, "abr": 4, "may": 5,
    "jun": 6, "jul": 7, "aug": 8, "ago": 8, "sep": 9, "set": 9, "oct": 10,
    "nov": 11, "dec": 12, "dic": 12,
}


def _fecha(y, m, d):
    try:
        return dt.date(int(y), int(m), int(d))
    except (TypeError, ValueError):
        return None


def fecha_desde_texto(valor):
    """Convierte textos como 20261013, 13-Oct-2026, Oct 13 2026, 13Oct2026."""
    if valor is None:
        return None
    if isinstance(valor, dt.datetime):
        return valor.date()
    if isinstance(valor, dt.date):
        return valor
    t = str(valor).strip()
    m = re.fullmatch(r"(\d{4})[-/_]?(\d{2})[-/_]?(\d{2})", t)
    if m:
        return _fecha(*m.groups())
    m = re.fullmatch(r"(\d{1,2})[\s_\-/.]*([A-Za-z]{3,9})\.?[\s_\-/.,]*(\d{4}|\d{2})", t)
    if m:
        y = int(m.group(3))
        return _fecha(y + 2000 if y < 100 else y, MESES.get(m.group(2)[:3].lower()), m.group(1))
    m = re.fullmatch(r"([A-Za-z]{3,9})\.?[\s_\-/.]*(\d{1,2})(?:st|nd|rd|th)?[\s_\-/.,]*(\d{4})", t)
    if m:
        return _fecha(m.group(3), MESES.get(m.group(1)[:3].lower()), m.group(2))
    m = re.fullmatch(r"(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})", t)
    if m:
        return _fecha(m.group(3), m.group(2), m.group(1))
    return None


def es_habil(d, feriados):
    return d.weekday() < 5 and d not in feriados


def dia_habil_anterior(d, feriados):
    d = d - dt.timedelta(days=1)
    while not es_habil(d, feriados):
        d -= dt.timedelta(days=1)
    return d


def fechas_cob_validas(hoy, feriados):
    """Fechas de cierre aceptables: desde el habil anterior (Chile) hasta ayer,
    solo dias de semana. La mas reciente va primero."""
    minimo = dia_habil_anterior(hoy, feriados)
    salida, d = [], hoy - dt.timedelta(days=1)
    while d >= minimo:
        if d.weekday() < 5:
            salida.append(d)
        d -= dt.timedelta(days=1)
    return salida


# =============================================================================
# Valores: comparacion y conversion
# =============================================================================

_NUM = re.compile(r"^-?\d+(\.\d+)?$")


def normalizar(v):
    """Representacion de texto estable para comparar valores de distintos formatos."""
    if v is None:
        return ""
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, dt.datetime):
        if (v.hour, v.minute, v.second) == (0, 0, 0):
            return v.strftime("%Y-%m-%d")
        return v.strftime("%Y-%m-%d %H:%M:%S")
    if isinstance(v, dt.date):
        return v.strftime("%Y-%m-%d")
    if isinstance(v, float):
        if v.is_integer():
            return str(int(v))
        return repr(round(v, 8))
    if isinstance(v, int):
        return str(v)
    return str(v).strip()


def iguales(a, b):
    na, nb = normalizar(a), normalizar(b)
    if na == nb:
        return True
    if _NUM.match(na) and _NUM.match(nb):
        try:
            return abs(float(na) - float(nb)) < 1e-7
        except ValueError:
            return False
    return False


def valor_para_json(v):
    if isinstance(v, (dt.datetime, dt.date)):
        return normalizar(v)
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v


def convertir_como(original, nuevo):
    """Convierte 'nuevo' al mismo tipo de dato que tenia la celda original."""
    if isinstance(original, (dt.datetime, dt.date)) and not isinstance(nuevo, (dt.datetime, dt.date)):
        f = fecha_desde_texto(nuevo)
        if f is not None:
            return dt.datetime(f.year, f.month, f.day)
        return nuevo
    if isinstance(original, (int, float)) and not isinstance(original, bool):
        try:
            n = float(str(nuevo).replace(",", ""))
            if isinstance(original, int) and n.is_integer():
                return int(n)
            return n
        except ValueError:
            return nuevo
    if isinstance(original, str) or original is None:
        if isinstance(nuevo, float) and nuevo.is_integer():
            return str(int(nuevo))
        return nuevo if isinstance(nuevo, str) else normalizar(nuevo)
    return nuevo


def normalizar_encabezado(v):
    return re.sub(r"\s+", " ", str(v)).strip().lower() if v is not None else ""


def letra_a_indice(letra):
    n = 0
    for ch in letra.strip().upper():
        n = n * 26 + (ord(ch) - 64)
    return n - 1


def indice_a_letra(i):
    i += 1
    s = ""
    while i:
        i, r = divmod(i - 1, 26)
        s = chr(65 + r) + s
    return s


def ruta_larga(p):
    """En Windows antepone \\\\?\\ para poder usar rutas de mas de 260 caracteres
    (la ruta de Diario + nombres como los de Deutsche Bank superan ese limite)."""
    p = Path(p)
    if os.name != "nt":
        return p
    s = str(p.absolute())
    if s.startswith("\\\\?\\"):
        return Path(s)
    if s.startswith("\\\\"):
        return Path("\\\\?\\UNC\\" + s[2:])
    return Path("\\\\?\\" + s)


def mostrar(p):
    """Ruta legible (sin el prefijo de rutas largas)."""
    s = str(p)
    if s.startswith("\\\\?\\UNC\\"):
        return "\\\\" + s[8:]
    return s[4:] if s.startswith("\\\\?\\") else s


def carpeta_temporal():
    return Path(tempfile.mkdtemp(prefix="col_"))


def nombre_seguro(nombre):
    return re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", nombre).strip().rstrip(".")


def sha1_archivo(ruta):
    h = hashlib.sha1()
    with open(ruta, "rb") as f:
        for bloque in iter(lambda: f.read(1 << 16), b""):
            h.update(bloque)
    return h.hexdigest()


# =============================================================================
# Lectura y escritura de archivos (CSV, XLSX, XLS)
# =============================================================================

class Hoja:
    def __init__(self, nombre, filas, tipos=None):
        self.nombre = nombre
        self.filas = filas          # lista de listas (indices desde 0)
        self.tipos = tipos          # solo XLS: tipo de celda de xlrd

    def valor(self, f, c):
        if f < len(self.filas) and c < len(self.filas[f]):
            return self.filas[f][c]
        return None

    def poner(self, f, c, v):
        while len(self.filas) <= f:
            self.filas.append([])
        fila = self.filas[f]
        while len(fila) <= c:
            fila.append(None)
        fila[c] = v


class Libro:
    """Contenido de un archivo en memoria, independiente del formato."""

    def __init__(self, ruta):
        self.ruta = Path(ruta)
        self.formato = formato_real(self.ruta)
        if self.formato is None:
            raise ValueError("Formato no soportado: %s" % self.ruta.suffix)
        self.hojas = []
        self._csv = None
        if self.formato == "csv":
            self._leer_csv()
        elif self.formato == "xlsx":
            self._leer_xlsx()
        elif self.formato == "xml2003":
            leer_xml2003(self)
        else:
            self._leer_xls()

    # ---------------------------------------------------------------- CSV
    def _leer_csv(self):
        datos = self.ruta.read_bytes()
        bom = datos.startswith(b"\xef\xbb\xbf")
        try:
            texto = datos.decode("utf-8-sig")
            codificacion = "utf-8"
        except UnicodeDecodeError:
            texto = datos.decode("cp1252")
            codificacion = "cp1252"
        primera = texto.split("\n", 1)[0]
        sep = ";" if primera.count(";") > primera.count(",") else ","
        registros = tokenizar_csv(texto, sep)
        self._csv = {"bom": bom, "codificacion": codificacion, "sep": sep, "registros": registros}
        filas = [[valor_token(t) for t in tokens] for tokens, _ in registros]
        self.hojas = [Hoja("csv", filas)]

    def guardar_csv(self, destino, ediciones):
        info = self._csv
        registros = [(list(tokens), fin) for tokens, fin in info["registros"]]
        for e in ediciones:
            while len(registros) <= e.fila:
                registros.append(([""], "\r\n"))
            tokens, fin = registros[e.fila]
            while len(tokens) <= e.col:
                tokens.append("")
            tokens[e.col] = token_con_formato(tokens[e.col], e.nuevo, info["sep"])
            registros[e.fila] = (tokens, fin)
        texto = "".join(info["sep"].join(t) + fin for t, fin in registros)
        datos = texto.encode(info["codificacion"])
        if info["bom"]:
            datos = b"\xef\xbb\xbf" + datos
        Path(destino).write_bytes(datos)

    # ---------------------------------------------------------------- XLSX
    def _leer_xlsx(self):
        import io
        import openpyxl
        # Se lee desde memoria: asi funciona aunque la extension diga .XLS
        self._wb = openpyxl.load_workbook(io.BytesIO(self.ruta.read_bytes()))
        for ws in self._wb.worksheets:
            filas = [list(r) for r in ws.iter_rows(values_only=True)]
            self.hojas.append(Hoja(ws.title, filas))

    def guardar_xlsx_openpyxl(self, destino, ediciones):
        for e in ediciones:
            ws = self._wb[self.hojas[e.hoja].nombre]
            celda = ws.cell(row=e.fila + 1, column=e.col + 1)
            celda.value = e.nuevo
            formato = getattr(e, "formato", None)
            if formato == MANTENER_FORMATO:
                formato = celda.number_format if isinstance(e.nuevo, str) and celda.data_type == "s" else None
            elif formato is None and isinstance(e.nuevo, str) and parece_convertible(e.nuevo):
                formato = "@"           # igual que con Excel
            if formato is not None and celda.number_format != formato:
                celda.number_format = formato
        self._wb.save(destino)

    # ---------------------------------------------------------------- XLS
    def _leer_xls(self):
        import xlrd
        with open(os.devnull, "w") as nulo:
            try:
                wb = xlrd.open_workbook(str(self.ruta), logfile=nulo, ignore_workbook_corruption=True)
            except TypeError:
                wb = xlrd.open_workbook(str(self.ruta), logfile=nulo)
        for sh in wb.sheets():
            filas, tipos = [], []
            for r in range(sh.nrows):
                fila, tfila = [], []
                for c in range(sh.ncols):
                    celda = sh.cell(r, c)
                    v = celda.value
                    if celda.ctype in (0, 6) or v == "":
                        v = None
                    elif celda.ctype == 3:
                        try:
                            v = dt.datetime(*xlrd.xldate_as_tuple(v, wb.datemode))
                        except Exception:
                            pass
                    fila.append(v)
                    tfila.append(celda.ctype)
                filas.append(fila)
                tipos.append(tfila)
            self.hojas.append(Hoja(sh.name, filas, tipos))


def formato_real(ruta):
    """Formato segun el contenido del archivo, no solo la extension."""
    try:
        with open(ruta, "rb") as f:
            cab = f.read(8)
    except OSError:
        cab = b""
    if cab.startswith(b"PK"):
        return "xlsx"
    if cab.startswith(b"\xd0\xcf\x11\xe0"):
        return "xls"
    if cab.lstrip().startswith((b"<?xml", b"\xef\xbb\xbf<?xml", b"<Workb", b"<ss:")):
        try:
            with open(ruta, "rb") as f:
                inicio = f.read(4096)
        except OSError:
            inicio = b""
        if b"urn:schemas-microsoft-com:office:spreadsheet" in inicio:
            return "xml2003"
    return {".csv": "csv", ".txt": "csv", ".xlsx": "xlsx", ".xlsm": "xlsx", ".xls": "xls"}.get(Path(ruta).suffix.lower())


# ---------------------------------------------------------------- Excel XML 2003 (ej. BancoEstado RPT_INFORME .xls)
RX_XML_FILA = re.compile(r"<(?:ss:)?Row\b[^>]*?(?:/>|>.*?</(?:ss:)?Row>)", re.S)
RX_XML_CELDA = re.compile(r"<(?:ss:)?Cell\b[^>]*?(?:/>|>.*?</(?:ss:)?Cell>)", re.S)
RX_XML_HOJA = re.compile(r"<(?:ss:)?Worksheet\b.*?</(?:ss:)?Worksheet>", re.S)
RX_XML_INDICE = re.compile(r'\bss:Index="(\d+)"')
RX_XML_DATO = re.compile(r"(<(?:ss:)?Data\b([^>]*)>)(.*?)(</(?:ss:)?Data>)", re.S)


def _xml_texto(t):
    import html as _h
    return _h.unescape(re.sub(r"<[^>]+>", "", t))


def _xml_valor(atributos, texto):
    tipo = re.search(r'ss:Type="(\w+)"', atributos or "")
    tipo = tipo.group(1) if tipo else "String"
    t = _xml_texto(texto)
    if tipo == "Number":
        try:
            x = float(t)
            return int(x) if x.is_integer() and "." not in t and "e" not in t.lower() else x
        except ValueError:
            return t
    if tipo == "DateTime":
        try:
            return dt.datetime.strptime(t[:19], "%Y-%m-%dT%H:%M:%S")
        except ValueError:
            return t
    return t if t != "" else None


def _xml_celdas(fila_xml):
    """[(columna, inicio, fin, atributos_data, texto_data)] de una fila (las columnas saltadas con ss:Index)."""
    salida, col = [], 0
    for m in RX_XML_CELDA.finditer(fila_xml):
        idx = RX_XML_INDICE.search(m.group(0).split(">", 1)[0])
        col = int(idx.group(1)) - 1 if idx else col
        d = RX_XML_DATO.search(m.group(0))
        salida.append((col, m.start(), m.end(), d.group(2) if d else None, d.group(3) if d else None, d))
        span = re.search(r'\bss:MergeAcross="(\d+)"', m.group(0).split(">", 1)[0])
        col += 1 + (int(span.group(1)) if span else 0)
    return salida


def leer_xml2003(libro):
    texto = libro.ruta.read_bytes().decode("utf-8", errors="replace")
    libro._xml = texto
    for k, mh in enumerate(RX_XML_HOJA.finditer(texto)):
        nombre = re.search(r'ss:Name="([^"]*)"', mh.group(0)[:400])
        filas, fila_n = [], 0
        for mf in RX_XML_FILA.finditer(mh.group(0)):
            idx = RX_XML_INDICE.search(mf.group(0).split(">", 1)[0])
            fila_n = int(idx.group(1)) - 1 if idx else fila_n
            while len(filas) < fila_n:
                filas.append([])
            fila = []
            for col, a, b, atr, txt, d in _xml_celdas(mf.group(0)):
                while len(fila) < col:
                    fila.append(None)
                fila.append(_xml_valor(atr, txt) if d else None)
            filas.append(fila)
            fila_n += 1
        libro.hojas.append(Hoja(nombre.group(1) if nombre else "Hoja%d" % (k + 1), filas))


def _xml_dato(nuevo, atributos):
    """Texto del dato y tipo (Number/String/DateTime) para escribir 'nuevo' en una celda XML 2003."""
    from xml.sax.saxutils import escape
    if isinstance(nuevo, (dt.datetime, dt.date)):
        d = nuevo if isinstance(nuevo, dt.datetime) else dt.datetime(nuevo.year, nuevo.month, nuevo.day)
        return d.strftime("%Y-%m-%dT%H:%M:%S.000"), "DateTime"
    if isinstance(nuevo, (int, float)) and not isinstance(nuevo, bool):
        return normalizar(nuevo), "Number"
    return escape(str(nuevo)), "String"


def guardar_xml2003(libro, destino, ediciones):
    """Escribe las ediciones en el mismo XML (todo lo demas queda byte a byte igual)."""
    texto = libro._xml
    cambios = {}
    for e in ediciones:
        cambios.setdefault(e.hoja, {})[(e.fila, e.col)] = e.nuevo
    reemplazos = []
    for k, mh in enumerate(RX_XML_HOJA.finditer(texto)):
        if k not in cambios:
            continue
        pendientes = dict(cambios[k])
        base_h = mh.start()
        fila_n = 0
        for mf in RX_XML_FILA.finditer(mh.group(0)):
            idx = RX_XML_INDICE.search(mf.group(0).split(">", 1)[0])
            fila_n = int(idx.group(1)) - 1 if idx else fila_n
            for col, a, b, atr, txt, d in _xml_celdas(mf.group(0)):
                if (fila_n, col) not in pendientes:
                    continue
                if d is None:
                    raise ValueError("la celda %s%d no tiene dato" % (indice_a_letra(col), fila_n + 1))
                valor, tipo = _xml_dato(pendientes.pop((fila_n, col)), atr)
                abre = re.sub(r'ss:Type="\w+"', 'ss:Type="%s"' % tipo, d.group(1))
                ini = base_h + mf.start() + a + d.start()
                fin = base_h + mf.start() + a + d.end()
                reemplazos.append((ini, fin, abre + valor + d.group(4)))
            fila_n += 1
        if pendientes:
            raise ValueError("no encontre %d celda(s) en la hoja %d" % (len(pendientes), k + 1))
    for ini, fin, nuevo in sorted(reemplazos, reverse=True):
        texto = texto[:ini] + nuevo + texto[fin:]
    Path(destino).write_bytes(texto.encode("utf-8"))


def tokenizar_csv(texto, sep):
    """Separa el CSV en registros y campos SIN perder las comillas originales,
    para poder reescribir el archivo identico salvo las celdas corregidas."""
    registros, tokens, buf = [], [], []
    en_comillas = False
    i, n = 0, len(texto)
    while i < n:
        c = texto[i]
        if en_comillas:
            buf.append(c)
            if c == '"':
                if i + 1 < n and texto[i + 1] == '"':
                    buf.append('"')
                    i += 1
                else:
                    en_comillas = False
        elif c == '"':
            en_comillas = True
            buf.append(c)
        elif c == sep:
            tokens.append("".join(buf))
            buf = []
        elif c in "\r\n":
            fin = c
            if c == "\r" and i + 1 < n and texto[i + 1] == "\n":
                fin = "\r\n"
                i += 1
            tokens.append("".join(buf))
            buf = []
            registros.append((tokens, fin))
            tokens = []
        else:
            buf.append(c)
        i += 1
    if buf or tokens:
        tokens.append("".join(buf))
        registros.append((tokens, ""))
    return registros


def valor_token(token):
    t = token
    if len(t) >= 2 and t.startswith('"') and t.endswith('"'):
        return t[1:-1].replace('""', '"')
    return t


def token_con_formato(token_original, nuevo, sep):
    texto = normalizar(nuevo) if not isinstance(nuevo, str) else nuevo
    if token_original.startswith('"') or any(ch in texto for ch in (sep, '"', "\n", "\r")):
        return '"' + texto.replace('"', '""') + '"'
    return texto


# =============================================================================
# Excel por automatizacion (para .xls, o para todo si motor_excel = "excel")
# =============================================================================

class ExcelCOM:
    def __init__(self):
        self.app = None

    def _iniciar(self):
        if self.app is None:
            import win32com.client
            self.app = win32com.client.DispatchEx("Excel.Application")
            self.app.Visible = False
            self.app.DisplayAlerts = False
            try:
                self.app.AskToUpdateLinks = False
            except Exception:
                pass
        return self.app

    def aplicar(self, origen, destino, ediciones, nombres_hojas, formato=None):
        """Copia el archivo a una carpeta temporal local, aplica los cambios con
        Excel (asi se conserva el formato exacto) y lo deja en 'destino'."""
        app = self._iniciar()
        tmp_dir = carpeta_temporal()           # ruta corta: Excel no abre rutas largas
        ext = {"xlsx": ".xlsx", "xls": ".xls"}.get(formato, Path(destino).suffix)
        tmp = tmp_dir / ("archivo" + ext)
        shutil.copy2(origen, tmp)
        wb = app.Workbooks.Open(str(tmp), 0, False)
        try:
            for e in ediciones:
                ws = wb.Worksheets(nombres_hojas[e.hoja])
                escribir_celda_com(ws.Cells(e.fila + 1, e.col + 1), e.nuevo, getattr(e, "formato", None))
            try:
                wb.CheckCompatibility = False
            except Exception:
                pass
            wb.Save()
        finally:
            wb.Close(False)
        shutil.copy2(tmp, destino)
        try:
            tmp.unlink()
            tmp_dir.rmdir()
        except OSError:
            pass

    def cerrar(self):
        if self.app is not None:
            try:
                self.app.Quit()
            except Exception:
                pass
            self.app = None


def parece_convertible(texto):
    """Textos que Excel convertiria solo en numero, fecha o formula si se escriben tal cual."""
    t = str(texto)
    return bool(re.fullmatch(r"[\d\s.,:/\-+]+", t)) or fecha_desde_texto(t) is not None or t.startswith(("=", "'"))


MANTENER_FORMATO = "__mantener__"     # escribe el valor sin tocar el formato de la celda (pareo Vmetrix)


def escribir_celda_com(celda, valor, formato=None):
    """Escribe como lo haria una persona en Excel, sin cambiar el formato de la celda
    salvo que el resultado esperado indique otro (ej. '@' = Texto)."""
    if formato == MANTENER_FORMATO:
        if isinstance(valor, str) and parece_convertible(valor) and str(celda.NumberFormat) != "@":
            valor = "'" + valor         # queda como texto, igual que venia, sin cambiar el formato
            celda.Value2 = valor
            return
        formato = None
        if isinstance(valor, str):
            celda.Value2 = valor
            return
    if formato is not None and str(celda.NumberFormat) != str(formato):
        celda.NumberFormat = formato
    if isinstance(valor, (dt.datetime, dt.date)):
        base = dt.datetime(1899, 12, 30)
        if not isinstance(valor, dt.datetime):
            valor = dt.datetime(valor.year, valor.month, valor.day)
        celda.Value2 = (valor - base).total_seconds() / 86400.0
    elif isinstance(valor, (int, float)) and not isinstance(valor, bool):
        celda.Value2 = float(valor)
    elif valor is None:
        celda.Value2 = None
    else:
        texto = str(valor)
        if parece_convertible(texto):
            # Sin formato esperado: Texto ('@'), como en los archivos corregidos a mano.
            if formato is None and str(celda.NumberFormat) != "@":
                celda.NumberFormat = "@"
            # Con otro formato esperado (ej. General): el apostrofo lo deja como texto sin tocar el formato.
            if str(celda.NumberFormat) != "@":
                texto = "'" + texto
        celda.Value2 = texto


# =============================================================================
# Motor de transformaciones
# =============================================================================

class Edicion:
    def __init__(self, hoja, fila, col, anterior, nuevo, regla, detalle="", col_nombre="", operacion="", formato=None):
        self.hoja, self.fila, self.col = hoja, fila, col
        self.anterior, self.nuevo = anterior, nuevo
        self.regla, self.detalle = regla, detalle
        self.col_nombre, self.operacion = col_nombre, operacion
        self.formato = formato      # formato numerico que debe quedar (None = el que tenga la celda)

    def describir(self, libro):
        return "%s!%s%d: %r -> %r (%s%s)" % (
            libro.hojas[self.hoja].nombre, indice_a_letra(self.col), self.fila + 1,
            self.anterior, self.nuevo, self.regla, (", " + self.detalle) if self.detalle else "")


class Tabla:
    def __init__(self, hoja_idx, hoja, fila_enc, fin):
        self.hoja_idx, self.hoja = hoja_idx, hoja
        self.fila_enc, self.fin = fila_enc, fin
        self.ji = None        # columna del N de operacion
        self.cols = {}
        for j, v in enumerate(hoja.filas[fila_enc]):
            n = normalizar_encabezado(v)
            if n and n not in self.cols:
                self.cols[n] = j

    def col(self, nombre):
        j = self.cols.get(normalizar_encabezado(nombre))
        if j is not None or nombre is None:
            return j
        # La contraparte cambio el encabezado (mayusculas, espacios, puntos, guiones): se busca sin signos,
        # y luego con los sinonimos de configuracion.json > sinonimos_columnas
        if not hasattr(self, "_claves"):
            self._claves = {}
            for n, k in self.cols.items():
                self._claves.setdefault(_clave_col(n), k)
        j = self._claves.get(_clave_col(nombre))
        if j is not None:
            return j
        for sin in SINONIMOS_COLUMNAS.get(_clave_col(nombre), []):
            j = self.cols.get(normalizar_encabezado(sin))
            if j is None:
                j = self._claves.get(_clave_col(sin))
            if j is not None:
                return j
        return None

    def filas_datos(self):
        for i in range(self.fila_enc + 1, self.fin):
            fila = self.hoja.filas[i]
            if any(v is not None and str(v).strip() != "" for v in fila):
                yield i


SINONIMOS_COLUMNAS = {}     # configuracion.json > sinonimos_columnas (se carga en preparar_contexto)


def cargar_sinonimos(conf):
    """{"Maturity Date": ["Maturity", "End Date"]} -> {clave_sin_signos: [sinonimos]} (en ambos sentidos)."""
    SINONIMOS_COLUMNAS.clear()
    for nombre, lista in (conf.get("sinonimos_columnas") or {}).items():
        if str(nombre).startswith("_") or not isinstance(lista, list):
            continue
        grupo = [nombre] + [x for x in lista if isinstance(x, str)]
        for n in grupo:
            SINONIMOS_COLUMNAS.setdefault(_clave_col(n), [])
            SINONIMOS_COLUMNAS[_clave_col(n)] += [x for x in grupo if x != n]


def _encabezado_en(clave, enc, enc_claves):
    if clave in enc or _clave_col(clave) in enc_claves:
        return True
    return any(normalizar_encabezado(x) in enc or _clave_col(x) in enc_claves
               for x in SINONIMOS_COLUMNAS.get(_clave_col(clave), []))


def detectar_tablas(libro, conf_tabla):
    """Una tabla empieza en cada fila que contiene todos los encabezados
    indicados y termina en el siguiente encabezado o al final de la hoja."""
    if not conf_tabla:
        return []
    claves = [normalizar_encabezado(x) for x in conf_tabla.get("encabezado_contiene", [])]
    hoja_buscada = conf_tabla.get("hoja")
    tablas = []
    for h_idx, hoja in enumerate(libro.hojas):
        if hoja_buscada and hoja.nombre.lower() != str(hoja_buscada).lower():
            continue
        inicios = []
        for i, fila in enumerate(hoja.filas):
            enc = {normalizar_encabezado(v) for v in fila}
            if claves and all(k in enc for k in claves):
                inicios.append(i)
            elif claves and len(enc) > len(claves):
                enc_claves = {_clave_col(v) for v in enc if v}
                if all(_encabezado_en(k, enc, enc_claves) for k in claves):
                    inicios.append(i)
        for k, ini in enumerate(inicios):
            fin = inicios[k + 1] if k + 1 < len(inicios) else len(hoja.filas)
            t = Tabla(h_idx, hoja, ini, fin)
            if conf_tabla.get("columna_id"):
                t.ji = t.col(conf_tabla["columna_id"])
            tablas.append(t)
    return tablas


# Reglas que corrigen datos de una operacion. No se aplican a operaciones que ya tienen
# su resultado esperado en ajustes_operaciones.json (ahi manda el valor mapeado).
REGLAS_DE_OPERACION = {"mapear_valores", "intercambiar_columnas", "truncar_producto",
                       "fecha_fin_de_semana", "copiar_de_anterior", "desplazar_fecha",
                       "tasa_desde_nominales", "fijar_valor", "vencimiento_desde_inicio"}
# Reglas que corrigen un patron conocido de la contraparte todos los dias (no piden aprobacion).
REGLAS_PATRON = {"desplazar_fecha", "tasa_desde_nominales", "fijar_valor", "vencimiento_desde_inicio"}


class Resultado:
    def __init__(self):
        self.ediciones = []
        self.avisos = []
        self.info = []      # notas informativas
        self.obs = []       # observaciones: el archivo queda [OK*] (listo, pero conviene mirarlo)
        self.ajustes = {}   # id ajuste -> (estado, detalle)
        self.protegidas = set()   # (hoja, fila, columna) con resultado esperado mapeado

    def editar(self, tabla, fila, col, nuevo, regla, detalle="", formato=None):
        if regla in REGLAS_DE_OPERACION and (tabla.hoja_idx, fila, col) in self.protegidas:
            return
        anterior = tabla.hoja.valor(fila, col)
        if type(anterior) == type(nuevo) and (anterior == nuevo if isinstance(nuevo, str) else iguales(anterior, nuevo)):
            return
        celda = (tabla.hoja_idx, fila, col)
        previas = [e for e in self.ediciones if (e.hoja, e.fila, e.col) == celda]
        if previas:
            original = previas[0].anterior
            if type(original) == type(nuevo) and (original == nuevo if isinstance(nuevo, str) else iguales(original, nuevo)):
                # Una regla la cambio y el pareo la deja como venia (ej. desplazar_fecha vs Vmetrix): sin cambio
                tabla.hoja.poner(fila, col, original)
                self.ediciones = [e for e in self.ediciones if (e.hoja, e.fila, e.col) != celda]
                return
        enc = tabla.hoja.valor(tabla.fila_enc, col)
        col_nombre = str(enc).strip() if enc is not None and fila != tabla.fila_enc else "(encabezado)"
        operacion = normalizar(tabla.hoja.valor(fila, tabla.ji)) if tabla.ji is not None and fila != tabla.fila_enc else ""
        tabla.hoja.poner(fila, col, nuevo)
        self.ediciones.append(Edicion(tabla.hoja_idx, fila, col, anterior, nuevo, regla, detalle, col_nombre, operacion,
                                      formato))


def aplicar_reglas(libro, reporte, fondo, ajustes, res=None, referencia=None):
    """Aplica reglas generales y luego ajustes por operacion. Modifica el libro
    en memoria y devuelve las ediciones para escribirlas en el archivo."""
    res = res or Resultado()
    tablas = detectar_tablas(libro, reporte.get("tabla"))
    reglas = [r for r in reporte.get("transformaciones", []) if r.get("activo", True)]
    if (reglas or ajustes) and not tablas:
        res.avisos.append("No encontre la tabla (encabezados %s). El formato pudo cambiar; "
                          "el archivo se copia sin cambios." % reporte.get("tabla", {}).get("encabezado_contiene"))
        return res
    # 1. Celdas con resultado esperado mapeado: las reglas no las tocan (las demas columnas de la
    #    misma operacion si reciben las reglas, ej. la tasa de SC aunque el Expiry este mapeado)
    col_id = (reporte.get("tabla") or {}).get("columna_id")
    ubicaciones = {}
    for a in ajustes:
        ubicaciones[id_ajuste(a)] = ubicar_ajuste(tablas, a, col_id)
        for t, i, j in ubicaciones[id_ajuste(a)]:
            res.protegidas.add((t.hoja_idx, i, j))
    # 2. Reglas generales (encabezados, textos y operaciones nuevas)
    for regla in reglas:
        tipo = regla.get("tipo")
        try:
            funcion = REGLAS[tipo]
        except KeyError:
            res.avisos.append("Regla desconocida '%s' en reportes.json" % tipo)
            continue
        if tipo == "alertar_si_valor":
            funcion(tablas, regla, res, col_id)
        else:
            funcion(tablas, regla, res)
    # Reglas de patron (se aplican todos los dias por diseno): solo se informan
    for nombre_regla in sorted(REGLAS_PATRON):
        eds = [e for e in res.ediciones if e.regla == nombre_regla]
        if eds:
            ops = sorted({e.operacion or "fila %d" % (e.fila + 1) for e in eds})
            res.info.append("%s (%s): %d celda(s) en %s" % (nombre_regla, eds[0].col_nombre, len(eds),
                            ", ".join(ops[:10]) + (" ..." if len(ops) > 10 else "")))
    nuevas = sorted({e.operacion for e in res.ediciones
                     if e.regla in REGLAS_DE_OPERACION and e.regla not in REGLAS_PATRON and e.operacion})
    if nuevas:
        res.obs.append("%d operacion(es) sin resultado esperado mapeado, corregidas con reglas generales: %s. "
                        "Revisalas; cuando las apruebes, --aprender las agrega al mapa"
                        % (len(nuevas), ", ".join(nuevas[:8]) + (" ..." if len(nuevas) > 8 else "")))
    # 3. Resultado esperado por operacion (manda sobre todo lo anterior)
    aplicar_ajustes(tablas, reporte, fondo, ajustes, res, ubicaciones)
    if referencia:
        aplicar_copia_anterior(tablas, reporte, referencia, res)
    elif referencia is False:
        conf = reporte.get("copiar_de_anterior") or {}
        res.info.append("%s: no hay archivo aprobado de dias anteriores en 02_Para_Cargar (ultimos %s dias); "
                        "solo se aplican los ajustes de ajustes_operaciones.json"
                        % (", ".join(conf.get("columnas", [])), conf.get("dias_atras", 10)))
    return res


def fecha_como_texto(ejemplo, fecha):
    """Escribe 'fecha' con el mismo formato de texto que 'ejemplo' (ej. 24/09/2031, 14-Oct-2036)."""
    e = str(ejemplo).strip()
    if re.fullmatch(r"\d{1,2}/\d{1,2}/\d{4}", e):
        return fecha.strftime("%d/%m/%Y")
    if re.fullmatch(r"\d{1,2}-[A-Za-z]{3}-\d{4}", e):
        return "%02d-%s-%d" % (fecha.day, ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct",
                                           "Nov", "Dec"][fecha.month - 1], fecha.year)
    if re.fullmatch(r"\d{1,2} [A-Za-z]{3} \d{4}", e):
        return "%02d %s %d" % (fecha.day, ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct",
                                           "Nov", "Dec"][fecha.month - 1], fecha.year)
    return fecha.strftime("%Y-%m-%d")


def aplicar_copia_anterior(tablas, reporte, referencia, res):
    """Copia columnas (ej. Maturity Date de BNP) desde el ultimo archivo aprobado, buscando
    cada operacion por su N. Solo toca operaciones que existian en ese archivo."""
    ruta_ref, fecha_ref = referencia
    conf = reporte["copiar_de_anterior"]
    col_id = (reporte.get("tabla") or {}).get("columna_id")
    try:
        anterior = Libro(ruta_ref)
    except Exception as e:
        res.avisos.append("No pude leer el archivo anterior %s: %s" % (ruta_ref.name, e))
        return
    mapa = {}
    for t in detectar_tablas(anterior, reporte.get("tabla")):
        ji = t.col(col_id)
        for nombre in conf["columnas"]:
            jc = t.col(nombre)
            if ji is None or jc is None:
                continue
            for i in t.filas_datos():
                op, v = normalizar(t.hoja.valor(i, ji)), t.hoja.valor(i, jc)
                if op and v is not None and str(v).strip() != "":
                    mapa.setdefault(nombre, {}).setdefault(op, v)
    copiados = 0
    for t in tablas:
        ji = t.col(col_id)
        for nombre in conf["columnas"]:
            jc = t.col(nombre)
            ref = mapa.get(nombre, {})
            if ji is None or jc is None or not ref:
                continue
            for i in t.filas_datos():
                op = normalizar(t.hoja.valor(i, ji))
                if op not in ref or (t.hoja_idx, i, jc) in res.protegidas:
                    continue
                actual, nuevo = t.hoja.valor(i, jc), ref[op]
                if isinstance(actual, str) and isinstance(nuevo, (dt.datetime, dt.date)):
                    nuevo = fecha_como_texto(actual, nuevo)
                else:
                    nuevo = convertir_como(actual, nuevo)
                if not iguales(actual, nuevo):
                    res.editar(t, i, jc, nuevo, "copiar_de_anterior", "desde archivo del %s" % fecha_ref)
                    copiados += 1
    res.info.append("%s: %d valor(es) copiados desde el archivo aprobado del %s" % (
        "/".join(conf["columnas"]), copiados, fecha_ref))


def regla_renombrar_encabezado(tablas, regla, res):
    desde, hacia = regla["desde"], regla["hacia"]
    hechos = 0
    for t in tablas:
        if t.col(hacia) is not None:
            hechos += 1
            continue
        j = t.col(desde)
        if j is not None:
            res.editar(t, t.fila_enc, j, hacia, "renombrar_encabezado")
            t.cols[normalizar_encabezado(hacia)] = j
            hechos += 1
    if not hechos:
        res.avisos.append("No encontre el encabezado '%s' (ni '%s')." % (desde, hacia))


def regla_fijar_encabezado(tablas, regla, res):
    j = letra_a_indice(regla["columna"]) if isinstance(regla["columna"], str) else int(regla["columna"]) - 1
    valor = regla["valor"]
    for t in tablas:
        actual = t.hoja.valor(t.fila_enc, j)
        if actual is None or str(actual).strip() == "":
            res.editar(t, t.fila_enc, j, valor, "fijar_encabezado")
            t.cols[normalizar_encabezado(valor)] = j
        elif not iguales(actual, valor):
            res.avisos.append("La columna %s del encabezado dice '%s' y esperaba vacia o '%s'. No se modifico."
                              % (indice_a_letra(j), actual, valor))


def regla_mapear_valores(tablas, regla, res):
    mapa = {str(k): v for k, v in regla["mapa"].items()}
    encontrada = False
    raros = set()
    for t in tablas:
        j = t.col(regla["columna"])
        if j is None:
            continue
        encontrada = True
        for i in t.filas_datos():
            v = t.hoja.valor(i, j)
            if v is None or str(v).strip() == "":
                continue
            clave = str(v).strip()
            if clave in mapa:
                res.editar(t, i, j, mapa[clave], "mapear_valores")
            elif regla.get("avisar_si_otro_valor", True):
                raros.add(clave)
    if not encontrada:
        res.avisos.append("No encontre la columna '%s' para invertir/mapear valores." % regla["columna"])
    if raros:
        res.avisos.append("Columna '%s' trae valores no contemplados %s; no se tocaron. Revisar."
                          % (regla["columna"], sorted(raros)))


def regla_reemplazar_texto(tablas, regla, res):
    buscar, reemplazar = regla["buscar"], regla["reemplazar"]
    encontrada = False
    for t in tablas:
        j = t.col(regla["columna"])
        if j is None:
            continue
        encontrada = True
        for i in t.filas_datos():
            v = t.hoja.valor(i, j)
            if isinstance(v, str) and buscar in v:
                res.editar(t, i, j, v.replace(buscar, reemplazar), "reemplazar_texto")
    if not encontrada:
        res.avisos.append("No encontre la columna '%s' para reemplazar texto." % regla["columna"])


VACIOS = ("", "NA", "N/A", "-", "NULL", "NONE")


def regla_intercambiar_columnas(tablas, regla, res):
    """Intercambia dos columnas en las filas que cumplen las condiciones. Las condiciones aceptan
    listas (ej. "Fixed Rate 2": [".000000", "NA", ""]). "vacio_como": lo que se escribe en la primera
    columna cuando lo que llega desde la segunda viene vacio o NA (ej. ".000000")."""
    a, b = regla["columnas"]
    condiciones = regla.get("condiciones", {})
    vacio_como = regla.get("vacio_como")
    alguna = False
    for t in tablas:
        ja, jb = t.col(a), t.col(b)
        if ja is None or jb is None or any(t.col(k) is None for k in condiciones):
            continue
        alguna = True
        for i in t.filas_datos():
            if _cumple(t, i, condiciones):
                if (t.hoja_idx, i, ja) in res.protegidas or (t.hoja_idx, i, jb) in res.protegidas:
                    continue        # una de las dos esta mapeada: no se intercambia a medias
                va, vb = t.hoja.valor(i, ja), t.hoja.valor(i, jb)
                if vacio_como is not None and str(vb if vb is not None else "").strip().upper() in VACIOS:
                    vb = vacio_como
                res.editar(t, i, ja, vb, "intercambiar_columnas")
                res.editar(t, i, jb, va, "intercambiar_columnas")
    if not alguna:
        res.avisos.append("No encontre las columnas %s / %s con las condiciones %s." % (a, b, list(condiciones)))


def regla_ordenar_filas(tablas, regla, res):
    for t in tablas:
        j = t.col(regla["columna"])
        if j is None:
            continue
        bloque = []
        for i in range(t.fila_enc + 1, t.fin):
            fila = t.hoja.filas[i]
            if not any(v is not None and str(v).strip() != "" for v in fila):
                break
            bloque.append(i)
        filas = [list(t.hoja.filas[i]) for i in bloque]
        ordenadas = sorted(filas, key=lambda f: normalizar(f[j] if j < len(f) else None),
                           reverse=bool(regla.get("descendente")))
        ancho = max([len(f) for f in filas] or [0])
        for i, nueva in zip(bloque, ordenadas):
            for c in range(ancho):
                v = nueva[c] if c < len(nueva) else None
                if t.hoja.valor(i, c) != v:
                    res.editar(t, i, c, v, "ordenar_filas")


def _numero(v):
    if isinstance(v, bool) or v is None:
        return None
    if isinstance(v, (int, float)):
        return v
    try:
        return float(str(v).replace(",", "").strip())
    except ValueError:
        return None


def regla_truncar_producto(tablas, regla, res):
    """Recalcula una columna como (factor1 x factor2) truncado, sin decimales.
    Ej. HSBC: nominal JPY de la pata 2 = nominal USD x Contract Rate, truncado.
    Solo corrige si la diferencia con lo que trae el archivo es <= diferencia_maxima."""
    from decimal import Decimal, ROUND_DOWN
    destino = regla["columna"]
    f1, f2 = regla["factores"]
    condiciones = regla.get("condiciones", {})
    maxima = float(regla.get("diferencia_maxima", 1))
    alguna = False
    for t in tablas:
        jd, j1, j2 = t.col(destino), t.col(f1), t.col(f2)
        jc = {t.col(k): str(v).strip().upper() for k, v in condiciones.items()}
        if None in (jd, j1, j2) or None in jc:
            continue
        alguna = True
        for i in t.filas_datos():
            if not all(str(t.hoja.valor(i, c) or "").strip().upper() == v for c, v in jc.items()):
                continue
            a, b, actual = _numero(t.hoja.valor(i, j1)), _numero(t.hoja.valor(i, j2)), _numero(t.hoja.valor(i, jd))
            if None in (a, b, actual):
                continue
            nuevo = int((Decimal(repr(float(a))) * Decimal(repr(float(b)))).to_integral_value(ROUND_DOWN))
            if nuevo == actual:
                continue
            if abs(nuevo - actual) <= maxima:
                original = t.hoja.valor(i, jd)
                res.editar(t, i, jd, convertir_como(original, nuevo), "truncar_producto")
            else:
                res.avisos.append("Fila %d: %s = %s pero %s x %s da %s (diferencia > %s). No se modifico."
                                  % (i + 1, destino, actual, f1, f2, nuevo, regla.get("diferencia_maxima", 1)))
    if not alguna:
        res.avisos.append("No encontre las columnas %s / %s / %s." % (destino, f1, f2))


def regla_fecha_fin_de_semana(tablas, regla, res):
    """Si una fecha cae sabado o domingo la mueve al lunes siguiente,
    conservando el formato del archivo (ej. 2036-08-10 domingo -> 2036-08-11)."""
    encontrada = False
    for t in tablas:
        j = t.col(regla["columna"])
        if j is None:
            continue
        encontrada = True
        for i in t.filas_datos():
            v = t.hoja.valor(i, j)
            f = fecha_desde_texto(v)
            if f is None or f.weekday() < 5:
                continue
            nueva = f + dt.timedelta(days=7 - f.weekday())
            if isinstance(v, (dt.datetime, dt.date)):
                nuevo = dt.datetime(nueva.year, nueva.month, nueva.day)
            elif re.fullmatch(r"\s*\d{4}-\d{2}-\d{2}\s*", str(v)):
                nuevo = nueva.strftime("%Y-%m-%d")
            else:
                res.avisos.append("Fila %d: fecha '%s' cae en fin de semana pero su formato no es AAAA-MM-DD; no se modifico."
                                  % (i + 1, v))
                continue
            res.editar(t, i, j, nuevo, "fecha_fin_de_semana")
    if not encontrada:
        res.avisos.append("No encontre la columna '%s' para revisar fines de semana." % regla["columna"])


def regla_alertar_si_valor(tablas, regla, res, col_id=None):
    """No modifica nada: marca REVISAR si alguna operacion trae alguno de los valores indicados."""
    valores = [str(v) for v in regla["valores"]]
    patrones = [re.compile(r"(?<![A-Za-z0-9])%s(?![A-Za-z0-9])" % re.escape(v)) for v in valores]
    hallazgos = []
    for t in tablas:
        ji = t.col(col_id) if col_id else None
        cols = [t.col(c) for c in regla.get("columnas", [])] or list(range(len(t.hoja.filas[t.fila_enc])))
        for i in t.filas_datos():
            if ji is not None and not normalizar(t.hoja.valor(i, ji)):
                continue    # filas sin N de operacion (totales, textos legales)
            for c in cols:
                if c is None:
                    continue
                texto = str(t.hoja.valor(i, c) or "")
                if any(p.search(texto) for p in patrones):
                    ident = normalizar(t.hoja.valor(i, ji)) if ji is not None else "fila %d" % (i + 1)
                    hallazgos.append("%s (%s)" % (ident, texto[:40]))
                    break
    if hallazgos:
        res.avisos.append("%s: %s" % (regla.get("mensaje", "Valores a revisar"), ", ".join(hallazgos[:15])))


def _cumple(t, i, condiciones):
    """Condiciones de una regla: {"columna": valor} o {"columna": [valor1, valor2]}.
    Compara numeros como numeros (0 = 0.0) y textos sin distinguir mayusculas."""
    for nombre, esperado in condiciones.items():
        j = t.col(nombre)
        if j is None:
            return False
        actual = t.hoja.valor(i, j)
        if isinstance(esperado, dict):          # rango: {"desde": "2026-08-01", "hasta": ...}
            if not _en_rango(actual, esperado):
                return False
            continue
        opciones = esperado if isinstance(esperado, list) else [esperado]
        ok = False
        for e in opciones:
            na, ne = _numero(actual), _numero(e)
            if na is not None and ne is not None:
                ok = abs(na - ne) < 1e-12
            else:
                ok = str(actual if actual is not None else "").strip().upper() == str(e).strip().upper()
            if ok:
                break
        if not ok:
            return False
    return True


def _en_rango(actual, rango):
    """{"desde": x, "hasta": y, "distinto": z}: fechas (cualquier formato del archivo) o numeros."""
    if "distinto" in rango and str(actual).strip().upper() == str(rango["distinto"]).strip().upper():
        return False
    fa = fecha_desde_texto(actual) if not isinstance(actual, (int, float)) else None
    for clave, signo in (("desde", 1), ("hasta", -1)):
        if clave not in rango:
            continue
        lim = rango[clave]
        fl = fecha_desde_texto(lim) if isinstance(lim, str) else None
        if fl is not None:
            if fa is None or (fa - fl).days * signo < 0:
                return False
        else:
            na, nl = _numero(actual), _numero(lim)
            if na is None or nl is None or (na - nl) * signo < 0:
                return False
    return True


def _es_fila_de_operacion(t, i, condiciones):
    """Con condiciones basta que se cumplan (Deutsche deja algunos NDF sin Trade ID); sin condiciones
    se exige N de operacion para no tocar totales ni textos legales."""
    if condiciones:
        return _cumple(t, i, condiciones)
    return t.ji is None or bool(normalizar(t.hoja.valor(i, t.ji)))


def _columnas_faltantes(t, regla, nombres):
    return [n for n in list(nombres) + list(regla.get("condiciones", {})) if t.col(n) is None]


FERIADOS = set()    # se llena en preparar_contexto (configuracion.json)


def _pascua(y):
    a, b, c = y % 19, y // 100, y % 100
    d, e = b // 4, b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = c // 4, c % 4
    l = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l) // 451
    return dt.date(y, (h + l - 7 * m + 114) // 31, ((h + l - 7 * m + 114) % 31) + 1)


def _enesimo(y, mes, dia_semana, n):
    d = dt.date(y, mes, 1)
    d += dt.timedelta((dia_semana - d.weekday()) % 7)
    return d + dt.timedelta(7 * (n - 1))


def _ultimo(y, mes, dia_semana):
    d = (dt.date(y, mes + 1, 1) if mes < 12 else dt.date(y + 1, 1, 1)) - dt.timedelta(1)
    return d - dt.timedelta((d.weekday() - dia_semana) % 7)


def _observado(d):
    return d - dt.timedelta(1) if d.weekday() == 5 else (d + dt.timedelta(1) if d.weekday() == 6 else d)


_CAL = {}


def feriados_calendario(y, calendario):
    """US: feriados de la Reserva Federal (SOFR). CL: feriados de configuracion.json mas los fijos
    y Semana Santa de cada ano (los moviles por ley se aproximan a su fecha fija)."""
    clave = (y, tuple(calendario))
    if clave not in _CAL:
        s = set()
        if "US" in calendario:
            s |= {_observado(dt.date(y, 1, 1)), _enesimo(y, 1, 0, 3), _enesimo(y, 2, 0, 3), _ultimo(y, 5, 0),
                  _observado(dt.date(y, 6, 19)), _observado(dt.date(y, 7, 4)), _enesimo(y, 9, 0, 1),
                  _enesimo(y, 10, 0, 2), _observado(dt.date(y, 11, 11)), _enesimo(y, 11, 3, 4),
                  _observado(dt.date(y, 12, 25))}
        if "CL" in calendario:
            p = _pascua(y)
            s |= {dt.date(y, m, d) for m, d in ((1, 1), (5, 1), (5, 21), (6, 21), (6, 29), (7, 16), (8, 15), (9, 18),
                                                (9, 19), (10, 12), (10, 31), (11, 1), (12, 8), (12, 25))}
            s |= {p - dt.timedelta(2), p - dt.timedelta(1)}
            s |= {f for f in FERIADOS if f.year == y}
        _CAL[clave] = s
    return _CAL[clave]


def ajustar_habil(d, calendario, convencion="siguiente"):
    """siguiente: si cae sabado, domingo o feriado, pasa al siguiente dia habil.
    siguiente_modificado: igual, salvo que se pase de mes; entonces va al habil anterior."""
    n = d
    while n.weekday() >= 5 or n in feriados_calendario(n.year, calendario):
        n += dt.timedelta(1)
    if convencion == "siguiente_modificado" and n.month != d.month:
        n = d
        while n.weekday() >= 5 or n in feriados_calendario(n.year, calendario):
            n -= dt.timedelta(1)
    return n
_MES_TXT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def _leer_fecha(v, orden="dmy"):
    """Fecha de una celda. 'orden' solo importa en textos tipo 6/3/2026 (dmy o mdy)."""
    if isinstance(v, (dt.datetime, dt.date)):
        return v.date() if isinstance(v, dt.datetime) else v
    m = re.fullmatch(r"\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*", str(v or ""))
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        d, mes = (b, a) if orden == "mdy" else (a, b)
        try:
            return dt.date(y, mes, d)
        except ValueError:
            return None
    return fecha_desde_texto(v)


def _escribir_fecha(original, f, orden="dmy"):
    """Devuelve la fecha 'f' con el mismo tipo y formato de texto que 'original'."""
    if isinstance(original, dt.datetime):
        return dt.datetime(f.year, f.month, f.day)
    if isinstance(original, dt.date):
        return f
    s = str(original).strip()
    m = re.fullmatch(r"(\d{1,2})/(\d{1,2})/(\d{4})", s)
    if m:
        p1, p2 = (f.month, f.day) if orden == "mdy" else (f.day, f.month)
        a = ("%02d" if len(m.group(1)) == 2 else "%d") % p1
        b = ("%02d" if len(m.group(2)) == 2 else "%d") % p2
        return "%s/%s/%d" % (a, b, f.year)
    if re.fullmatch(r"\d{1,2}-[A-Za-z]{3}-\d{4}", s):
        return "%02d-%s-%d" % (f.day, _MES_TXT[f.month - 1], f.year)
    if re.fullmatch(r"\d{1,2} [A-Za-z]{3} \d{4}", s):
        return "%02d %s %d" % (f.day, _MES_TXT[f.month - 1], f.year)
    if re.fullmatch(r"[A-Za-z]{3}-\d{1,2}-\d{4}", s):          # Scotia: Sep-23-2035
        return "%s-%02d-%d" % (_MES_TXT[f.month - 1], f.day, f.year)
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
        return f.strftime("%Y-%m-%d")
    if re.fullmatch(r"\d{4}/\d{2}/\d{2}", s):
        return f.strftime("%Y/%m/%d")
    m = re.fullmatch(r"(\d{1,2})([-.])(\d{1,2})[-.](\d{4})", s)
    if m:
        a = ("%02d" if len(m.group(1)) == 2 else "%d") % f.day
        b = ("%02d" if len(m.group(3)) == 2 else "%d") % f.month
        return "%s%s%s%s%d" % (a, m.group(2), b, m.group(2), f.year)
    if re.fullmatch(r"\d{8}", s):
        return f.strftime("%Y%m%d")
    return None


def regla_desplazar_fecha(tablas, regla, res):
    """Mueve una fecha N dias (o N dias habiles de Chile) en las filas que cumplen las condiciones,
    conservando el formato. Ej. Deutsche registra los NDF en PHP con fecha de trade un dia
    despues que la cartera: {"columna": "Trade Date", "dias_habiles": -1, "condiciones": {"Not.Ccy2": "PHP"}}."""
    nombre = regla["columna"]
    orden = regla.get("orden", "dmy")
    habiles = regla.get("dias_habiles")
    dias = int(habiles if habiles is not None else regla.get("dias", 0))
    condiciones = regla.get("condiciones", {})
    alguna = False
    for t in tablas:
        if _columnas_faltantes(t, regla, [nombre]):
            continue
        alguna = True
        j = t.col(nombre)
        for i in t.filas_datos():
            if not _es_fila_de_operacion(t, i, condiciones):
                continue
            v = t.hoja.valor(i, j)
            f = _leer_fecha(v, orden)
            if f is None:
                continue
            if habiles is not None:
                n = f
                for _ in range(abs(dias)):
                    n = n + dt.timedelta(days=1 if dias > 0 else -1)
                    while not es_habil(n, FERIADOS):
                        n = n + dt.timedelta(days=1 if dias > 0 else -1)
            else:
                n = f + dt.timedelta(days=dias)
            nuevo = _escribir_fecha(v, n, orden)
            if nuevo is None:
                res.avisos.append("Fila %d: no reconozco el formato de la fecha '%s'; no se modifico." % (i + 1, v))
                continue
            res.editar(t, i, j, nuevo, "desplazar_fecha", regla.get("_nota", ""))
    if not alguna:
        res.avisos.append("No encontre las columnas %s para desplazar fechas." % ([nombre] + list(condiciones)))


def regla_vencimiento_desde_inicio(tablas, regla, res):
    """Vencimiento = aniversario de la fecha de inicio en el ano del vencimiento, llevado al siguiente
    dia habil si cae fin de semana o feriado (calendario US, CL o ambos). Ej. BNP/SC informan la fecha
    de pago (vencimiento + 2 dias habiles) y la cartera el vencimiento: inicio 22/10/2026, BNP
    25/10/2056, cartera 23/10/2056 (22/10/2056 es domingo). Solo cambia si la fecha del archivo esta a
    'tolerancia_dias' o menos del resultado, para no tocar operaciones que no siguen el patron."""
    destino, inicio = regla["columna"], regla["inicio"]
    calendario = regla.get("calendario", ["US"])
    convencion = regla.get("convencion", "siguiente_modificado")
    tolerancia = int(regla.get("tolerancia_dias", 7))
    orden = regla.get("orden", "dmy")
    condiciones = regla.get("condiciones", {})
    alguna = False
    for t in tablas:
        if _columnas_faltantes(t, regla, [destino, inicio]):
            continue
        alguna = True
        jd, ji = t.col(destino), t.col(inicio)
        for i in t.filas_datos():
            if not _es_fila_de_operacion(t, i, condiciones):
                continue
            v = t.hoja.valor(i, jd)
            venc, ini = _leer_fecha(v, orden), _leer_fecha(t.hoja.valor(i, ji), orden)
            if venc is None or ini is None or venc <= ini:
                continue
            mejor = None
            for y in (venc.year, venc.year - 1):
                try:
                    aniv = ini.replace(year=y)
                except ValueError:          # 29 de febrero
                    aniv = dt.date(y, 2, 28)
                n = ajustar_habil(aniv, calendario, convencion)
                if abs((venc - n).days) <= tolerancia:
                    mejor = n
                    break
            if mejor is None or mejor == venc:
                continue
            nuevo = _escribir_fecha(v, mejor, orden)
            if nuevo is None:
                continue
            res.editar(t, i, jd, nuevo, "vencimiento_desde_inicio", "inicio %s" % ini.strftime("%d-%m-%Y"))
    if not alguna:
        res.avisos.append("No encontre las columnas %s." % ([destino, inicio] + list(condiciones)))


def regla_tasa_desde_nominales(tablas, regla, res):
    """Recalcula una tasa como numerador / denominador (ej. SG: cuando un NDF ya fijo, 'Forward Rate'
    trae la tasa de fijacion y la cartera tiene la tasa pactada = Notional 2 / Notional Amount)."""
    destino = regla["columna"]
    num, den = regla["numerador"], regla["denominador"]
    dec = int(regla.get("decimales", 7))
    condiciones = regla.get("condiciones", {})
    alguna = False
    for t in tablas:
        if _columnas_faltantes(t, regla, [destino, num, den]):
            continue
        alguna = True
        jd, jn, jm = t.col(destino), t.col(num), t.col(den)
        for i in t.filas_datos():
            if not _cumple(t, i, condiciones):
                continue
            a, b, actual = _numero(t.hoja.valor(i, jn)), _numero(t.hoja.valor(i, jm)), _numero(t.hoja.valor(i, jd))
            if a is None or not b or actual is None:
                continue
            nuevo = round(abs(a) / abs(b), dec)
            if abs(nuevo - actual) < 10 ** -(dec + 1):
                continue
            res.editar(t, i, jd, convertir_como(t.hoja.valor(i, jd), nuevo), "tasa_desde_nominales",
                       "%s / %s" % (num, den))
    if not alguna:
        res.avisos.append("No encontre las columnas %s." % ([destino, num, den] + list(condiciones)))


def regla_fijar_valor(tablas, regla, res):
    """Deja un valor fijo en una columna para las filas que cumplen las condiciones."""
    nombre, valor = regla["columna"], regla["valor"]
    condiciones = regla.get("condiciones", {})
    alguna = False
    for t in tablas:
        if _columnas_faltantes(t, regla, [nombre]):
            continue
        alguna = True
        j = t.col(nombre)
        for i in t.filas_datos():
            if not _es_fila_de_operacion(t, i, condiciones):
                continue
            res.editar(t, i, j, convertir_como(t.hoja.valor(i, j), valor), "fijar_valor", regla.get("_nota", ""))
    if not alguna:
        res.avisos.append("No encontre las columnas %s." % ([nombre] + list(condiciones)))


REGLAS = {
    "vencimiento_desde_inicio": regla_vencimiento_desde_inicio,
    "desplazar_fecha": regla_desplazar_fecha,
    "tasa_desde_nominales": regla_tasa_desde_nominales,
    "fijar_valor": regla_fijar_valor,
    "truncar_producto": regla_truncar_producto,
    "fecha_fin_de_semana": regla_fecha_fin_de_semana,
    "alertar_si_valor": regla_alertar_si_valor,
    "renombrar_encabezado": regla_renombrar_encabezado,
    "fijar_encabezado": regla_fijar_encabezado,
    "mapear_valores": regla_mapear_valores,
    "reemplazar_texto": regla_reemplazar_texto,
    "intercambiar_columnas": regla_intercambiar_columnas,
    "ordenar_filas": regla_ordenar_filas,
}


def id_ajuste(a):
    base = "%s|%s|%s|%s" % (a.get("reporte"), a.get("fondo", ""), a.get("operacion"), a.get("columna"))
    if a.get("condicion"):
        base += "|" + ",".join("%s=%s" % (k, normalizar(v)) for k, v in sorted(a["condicion"].items()))
    if a.get("ocurrencia"):
        base += "|#%s" % a["ocurrencia"]
    return base


def tipo_de_valor(v):
    """texto / numero / fecha (None si la celda esta vacia)."""
    if v is None or (isinstance(v, str) and v.strip() == ""):
        return None
    if isinstance(v, bool):
        return "texto"
    if isinstance(v, (dt.datetime, dt.date)):
        return "fecha"
    if isinstance(v, (int, float)):
        return "numero"
    return "texto"


def a_tipo(valor, tipo, actual):
    """Convierte un valor de ajustes_operaciones.json al tipo de celda que debe quedar."""
    if tipo == "fecha":
        f = fecha_desde_texto(valor)
        return dt.datetime(f.year, f.month, f.day) if f else valor
    if tipo == "numero":
        if isinstance(valor, (int, float)) and not isinstance(valor, bool):
            return valor
        try:
            n = float(str(valor).replace(",", ""))
            return int(n) if n.is_integer() and isinstance(actual, int) else n
        except ValueError:
            return valor
    if tipo == "texto":
        if isinstance(valor, float) and valor.is_integer():
            return str(int(valor))
        return valor if isinstance(valor, str) else normalizar(valor)
    return convertir_como(actual, valor)


def coincide(actual, esperado):
    """Mismo valor y mismo tipo de dato (un texto debe ser identico, ej. 5.235000 no es 5.235)."""
    if tipo_de_valor(actual) != tipo_de_valor(esperado):
        return False
    if isinstance(esperado, str):
        return str(actual).strip() == esperado.strip()
    return iguales(actual, esperado)


def ubicar_ajuste(tablas, a, col_id):
    """Filas (tabla, fila, columna) de la operacion. Si la operacion tiene varias filas
    (ej. las dos patas de un swap), 'condicion' dice cual: {"Fix/Float": "Fixed"}."""
    salida = []
    if not col_id or not a.get("operacion") or not a.get("columna"):
        return salida
    cond = a.get("condicion") or {}
    for t in tablas:
        ji, jc = t.col(col_id), t.col(a["columna"])
        jcond = {k: t.col(k) for k in cond}
        if ji is None or jc is None or any(j is None for j in jcond.values()):
            continue
        n = 0
        for i in t.filas_datos():
            if not iguales(t.hoja.valor(i, ji), a["operacion"]):
                continue
            if any(normalizar(t.hoja.valor(i, jcond[k])) != normalizar(v) for k, v in cond.items()):
                continue
            n += 1
            if a.get("ocurrencia") and n != int(a["ocurrencia"]):
                continue
            salida.append((t, i, jc))
    return salida


def aplicar_ajustes(tablas, reporte, fondo, ajustes, res, ubicaciones=None):
    """Resultado esperado por operacion: cada valor mapeado debe quedar exactamente asi
    (valor, tipo de dato y formato). Si ya esta asi, no se toca. Si no, se cambia, aunque
    la contraparte mande un valor distinto del error conocido (queda como observacion)."""
    col_id = (reporte.get("tabla") or {}).get("columna_id")
    for a in ajustes:
        clave = id_ajuste(a)
        if not col_id:
            res.ajustes[clave] = ("revisar", "reporte sin columna_id definida")
            continue
        ub = ubicaciones.get(clave) if ubicaciones is not None else ubicar_ajuste(tablas, a, col_id)
        if not ub:
            res.ajustes[clave] = ("no_encontrada", "")
            continue
        estados = []
        for t, i, jc in ub:
            actual = t.hoja.valor(i, jc)
            esperado = a_tipo(a.get("valor_correcto"), a.get("tipo"), actual)
            if coincide(actual, esperado):
                estados.append(("ya_correcto", ""))
                continue
            conocido = a.get("valor_contraparte")
            if conocido is not None and iguales(actual, a_tipo(conocido, tipo_de_valor(actual), actual)):
                estado = ("aplicado", "")
            else:
                estado = ("forzado", "venia %r (el error conocido era %r); quedo %r" % (
                    valor_para_json(actual), conocido, a.get("valor_correcto")))
            res.editar(t, i, jc, esperado, "valor_esperado",
                       "op %s%s" % (a["operacion"], (", formato %s" % a["formato"]) if a.get("formato") else ""),
                       formato=a.get("formato"))
            estados.append(estado)
        for prioridad in ("forzado", "aplicado", "ya_correcto"):
            hit = [e for e in estados if e[0] == prioridad]
            if hit:
                res.ajustes[clave] = hit[0]
                break
        if res.ajustes[clave][0] == "forzado":
            res.obs.append("Op %s (%s): %s" % (a["operacion"], a["columna"], res.ajustes[clave][1]))


def ajustes_del_reporte(ctx, reporte, fondo):
    salida = []
    varios_fondos = len(reporte.get("fondos", [])) > 1
    for a in ctx.ajustes:
        if not a.get("activo", True) or a.get("reporte") != reporte["id"]:
            continue
        if varios_fondos and a.get("fondo") and fondo and a["fondo"] != fondo:
            continue
        salida.append(a)
    return salida


def nombre_de_salida(reporte, nombre):
    regla = reporte.get("nombre_salida")
    if not regla:
        return nombre
    return re.sub(regla["buscar"], regla["reemplazar"], nombre)


# =============================================================================
# Identificacion de archivos y correos
# =============================================================================

class Ranura:
    """Un archivo esperado: reporte + fondo."""

    def __init__(self, reporte, fondo):
        self.reporte, self.fondo = reporte, fondo
        self.estado = ESTADO_FALTA
        self.archivo = None          # ruta en 01_Originales
        self.salida = None           # ruta en 02_Para_Cargar
        self.origen = ""
        self.correo = ""
        self.observaciones = []
        self.candidatos_revisar = []
        self.cambios = 0
        self.preparado_antes = ""     # hora de la ejecucion anterior que lo preparo
        self.detalle_cambios = []     # [hoja, celda, columna, operacion, antes, despues, regla, detalle]
        self.archivo_convertido = None  # si la contraparte cambio de formato y se convirtio al anterior
        self.armado_html = False        # el original se armo con los correos HTML (aun no llegaba el Excel)
        self.arrastre = None            # el original se armo con el statement del cierre anterior (dict)

    @property
    def clave(self):
        return (self.reporte["id"], self.fondo)


_REGEX_INVALIDAS = set()


def compilar(patron):
    """Compila una expresion de reportes.json. Si esta mal escrita avisa una vez
    y devuelve None (ese reporte no calza con nada, pero el proceso sigue)."""
    if not patron:
        return None
    try:
        return re.compile(patron, re.IGNORECASE)
    except re.error as e:
        if patron not in _REGEX_INVALIDAS:
            _REGEX_INVALIDAS.add(patron)
            decir("  Aviso: expresion invalida en reportes.json (%s): %s" % (e, patron[:90]))
        return None


def mapear_fondo(reporte, valor):
    if valor is None:
        return None
    mapa = reporte.get("mapa_fondos", {})
    v = str(valor).strip()
    return mapa.get(v, mapa.get(v.upper(), v.upper()))


def fecha_de_grupos(grupos):
    """Devuelve (tipo, fecha) priorizando la fecha de cierre (cob)."""
    for tipo in ("cob", "emision"):
        if grupos.get(tipo):
            f = fecha_desde_texto(grupos[tipo])
            if f:
                return tipo, f
    return None, None


def evaluar_fecha(tipo, fecha, ctx):
    if fecha is None:
        return None, "sin fecha en nombre/asunto"
    if tipo == "cob":
        if fecha in ctx.cobs:
            return True, ""
        return False, "fecha de cierre %s; se esperaba %s" % (fecha, " o ".join(str(c) for c in ctx.cobs))
    if fecha == ctx.hoy:
        return True, ""
    return False, "fecha de emision %s; se esperaba %s" % (fecha, ctx.hoy)


def identificar_archivo(ctx, nombre):
    """Busca a que reporte y fondo corresponde un nombre de archivo."""
    for rep in ctx.reportes:
        rx = compilar(rep.get("adjunto", {}).get("patron"))
        if not rx:
            continue
        m = rx.fullmatch(nombre)
        if not m:
            continue
        grupos = m.groupdict()
        fondos = rep.get("fondos", [])
        fondo = fondos[0] if len(fondos) == 1 else mapear_fondo(rep, grupos.get("fondo"))
        tipo, fecha = fecha_de_grupos(grupos)
        return rep, fondo, tipo, fecha
    return None, None, None, None


class Candidato:
    def __init__(self, reporte, fondo, correo, adjunto_idx, adjunto_nombre):
        self.reporte, self.fondo = reporte, fondo
        self.por_contenido = False    # banco reconocido por su dominio; el adjunto se revisa por contenido
        self.correo, self.adjunto_idx, self.adjunto_nombre = correo, adjunto_idx, adjunto_nombre
        self.nombre_destino = None    # nombre con que se guarda si el adjunto vino con nombre corto
        self.criterios = {}
        self.problemas = []
        self.puntaje = 0
        self.clase = ESTADO_REVISAR

    def resumen(self):
        return "%s | %s | %s | adjunto: %s | %s" % (
            self.correo.recibido.strftime("%d-%m %H:%M"), self.correo.remitente_principal,
            self.correo.asunto[:90], self.adjunto_nombre, "; ".join(self.problemas) or "ok")


def evaluar_candidatos(ctx, correo):
    """Compara un correo con todos los reportes y devuelve candidatos."""
    salida = []
    asunto = correo.asunto or ""
    for rep in ctx.reportes:
        conf = rep.get("correo") or {}
        if not conf:
            continue
        dominios = [d.lower().lstrip("@") for d in conf.get("dominios", [])]
        remitentes = [r.lower() for r in conf.get("remitentes", [])]
        dominio_ok = any(dir_.endswith("@" + d) or dir_.endswith("." + d)
                         for dir_ in correo.remitentes for d in dominios) if dominios else True
        remitente_ok = any(r in correo.remitentes for r in remitentes) if remitentes else dominio_ok
        rx_asunto = compilar(conf.get("asunto"))
        m_asunto = rx_asunto.search(asunto) if rx_asunto else None
        asunto_ok = bool(m_asunto)
        if not (dominio_ok or asunto_ok):
            continue
        g_asunto = m_asunto.groupdict() if m_asunto else {}
        rx_adj = compilar(rep.get("adjunto", {}).get("patron"))
        extensiones = [e.lower() for e in rep.get("extensiones", [".xlsx", ".xls", ".csv"])]
        fondos = rep.get("fondos", [])
        for idx, nombre in correo.adjuntos:
            m_adj = rx_adj.fullmatch(nombre) if rx_adj else None
            adjunto_ok = bool(m_adj)
            nombre_destino = None
            por_contenido = False
            if not adjunto_ok:
                # adjunto con nombre distinto: si viene del @corporativo del banco, se revisa su contenido
                ext = Path(nombre).suffix.lower()
                por_contenido = (dominio_ok and bool(dominios) and ext in extensiones
                                 and bool((rep.get("tabla") or {}).get("encabezado_contiene")))
                if not por_contenido and not (dominio_ok and asunto_ok and
                                              (ext in extensiones or ext in (".xls", ".xlsx", ".csv"))):
                    continue
                if not por_contenido and len(fondos) > 1 and not g_asunto.get("fondo"):
                    continue
                # Nombre corto tipo 8.3 (ej. EXPOSU~1.XLS): si el reporte define un nombre
                # estandar, se acepta y se guarda con ese nombre
                plantilla = rep.get("adjunto", {}).get("nombre_estandar")
                if plantilla and re.fullmatch(r"[^.]{1,8}\.[A-Za-z0-9]{1,4}", nombre):
                    try:
                        datos = dict(g_asunto)
                        datos["fondo"] = mapear_fondo(rep, g_asunto.get("fondo")) or ""
                        nombre_destino = plantilla.format(**datos)
                        adjunto_ok = bool(rx_adj.fullmatch(nombre_destino)) if rx_adj else True
                    except (KeyError, IndexError, ValueError):
                        nombre_destino = None
            g_adj = m_adj.groupdict() if m_adj else {}
            if len(fondos) == 1:
                fondo = fondos[0]
                fondo_ok = True
            else:
                f_adj = mapear_fondo(rep, g_adj.get("fondo"))
                f_asu = mapear_fondo(rep, g_asunto.get("fondo"))
                validos = [f for f in (f_adj, f_asu) if f in fondos]
                fondo = validos[0] if validos else (f_adj or f_asu)
                fondo_ok = bool(validos) and not (f_adj in fondos and f_asu in fondos and f_adj != f_asu)
            cand = Candidato(rep, fondo, correo, idx, nombre)
            cand.por_contenido = por_contenido
            if nombre_destino and adjunto_ok:
                cand.nombre_destino = nombre_destino
                g_adj = rx_adj.fullmatch(nombre_destino).groupdict() if rx_adj else {}
                cand.problemas.append("adjunto con nombre corto '%s', guardado como nombre estandar" % nombre)
            tipo, fecha = fecha_de_grupos(g_adj)
            if fecha is None:
                tipo, fecha = fecha_de_grupos(g_asunto)
            fecha_ok, problema_fecha = evaluar_fecha(tipo, fecha, ctx)
            cand.sin_fecha = fecha is None      # si el reporte lo dice, la fecha se lee en el archivo
            recibido_hoy = correo.recibido.date() == ctx.hoy
            if fecha_ok is None:
                fecha_ok = recibido_hoy
                problema_fecha = "" if recibido_hoy else "sin fecha y no fue recibido hoy"
            # El statement de la fecha anterior (ej. el de ayer) no es un candidato
            # dudoso: simplemente todavia no llega el de hoy.
            antiguo = fecha is not None and fecha_ok is False and (
                fecha < min(ctx.cobs) if tipo == "cob" else fecha < ctx.hoy)
            cand.criterios = dict(adjunto=adjunto_ok, fondo=fondo_ok, fecha=fecha_ok, dominio=dominio_ok,
                                  asunto=asunto_ok, remitente=remitente_ok, recibido_hoy=recibido_hoy)
            pesos = dict(adjunto=40, fondo=20, fecha=20, dominio=10, asunto=5, remitente=3, recibido_hoy=2)
            cand.puntaje = sum(p for k, p in pesos.items() if cand.criterios[k])
            if not adjunto_ok:
                cand.problemas.append("nombre de adjunto no reconocido")
            if not fondo_ok:
                cand.problemas.append("fondo no reconocido (%s)" % fondo)
            if not fecha_ok:
                cand.problemas.append(problema_fecha)
            if not dominio_ok:
                cand.problemas.append("remitente fuera de los dominios esperados")
            criticos = adjunto_ok and fondo_ok and fecha_ok and dominio_ok
            if criticos:
                cand.clase = ESTADO_OK
                if not asunto_ok:
                    cand.problemas.append("asunto distinto al configurado")
            elif antiguo and adjunto_ok and fondo_ok:
                cand.clase = "ANTIGUO"
            salida.append(cand)
    return salida


