# Modo aprender: compara originales vs corregidos y propone ajustes
# =============================================================================

def filas_por_id(tabla, col_id):
    salida = {}
    j = tabla.col(col_id)
    if j is None:
        return salida
    for i in tabla.filas_datos():
        v = normalizar(tabla.hoja.valor(i, j))
        if v:
            salida.setdefault(v, []).append(i)
    return salida


def fondo_de_fila(rep, tabla, i):
    col = rep.get("columna_fondo")
    if not col or tabla.col(col) is None:
        return ""
    v = str(tabla.hoja.valor(i, tabla.col(col)) or "")
    m = re.search(r"(?:TIPO\s+|CUPRUM\s+|CUPF|FUND\s+|TY\s+)([A-E])\b", v, re.IGNORECASE)
    return m.group(1).upper() if m else ""


class FormatosCeldas:
    """Formato numerico de cada celda de un Excel (para saber si un texto quedo como Texto '@' o General)."""

    def __init__(self, ruta):
        self.tipo, self.wb = "csv", None
        if Path(str(ruta)).suffix.lower() == ".csv":
            return
        try:
            if formato_real(ruta) == "xlsx":
                import io
                import openpyxl
                self.wb = openpyxl.load_workbook(io.BytesIO(Path(ruta).read_bytes()))
                self.tipo = "xlsx"
            else:
                import xlrd
                with open(os.devnull, "w") as nulo:
                    self.wb = xlrd.open_workbook(str(ruta), formatting_info=True, logfile=nulo)
                self.tipo = "xls"
        except Exception as e:
            LOG.info("sin formatos de %s: %s", ruta, e)
            self.tipo = "csv"

    def formato(self, hoja, fila, col):
        try:
            if self.tipo == "xlsx":
                return self.wb[hoja].cell(row=fila + 1, column=col + 1).number_format
            if self.tipo == "xls":
                sh = self.wb.sheet_by_name(hoja)
                xf = self.wb.xf_list[sh.cell_xf_index(fila, col)]
                f = self.wb.format_map.get(xf.format_key)
                return f.format_str if f else None
        except Exception:
            return None
        return None


def condicion_de_fila(to, tm, filas_o, fo, fm_de, col_id, j_obj):
    """Si una operacion tiene varias filas, busca una columna de texto que las distinga
    y que no cambie entre el original y el corregido (ej. Fix/Float = Fixed / Float)."""
    for nombre, j in sorted(to.cols.items(), key=lambda x: x[1]):
        if j == j_obj or nombre == normalizar_encabezado(col_id):
            continue
        vals = [to.hoja.valor(i, j) for i in filas_o]
        if not all(isinstance(v, str) and v.strip() for v in vals):
            continue
        if len({normalizar(v) for v in vals}) != len(vals):
            continue
        jm = tm.col(nombre)
        if jm is None or any(normalizar(to.hoja.valor(i, j)) != normalizar(tm.hoja.valor(fm_de[i], jm)) for i in filas_o):
            continue
        return {str(to.hoja.filas[to.fila_enc][j]).strip(): to.hoja.valor(fo, j).strip()}
    return None


def emparejar_filas(to, tm, filas_o, filas_m):
    """Empareja las filas de una misma operacion (original vs corregido) por parecido."""
    pares, libres = {}, list(filas_m)
    for fo in filas_o:
        if not libres:
            break
        mejor = min(libres, key=lambda fm: sum(
            1 for nombre, j in to.cols.items()
            if tm.col(nombre) is not None and normalizar(to.hoja.valor(fo, j)) != normalizar(tm.hoja.valor(fm, tm.col(nombre)))))
        pares[fo] = mejor
        libres.remove(mejor)
    return pares


def comparar_par(ctx, rep, fondo, ruta_orig, ruta_mod):
    """Compara el archivo original de la contraparte con el corregido/aprobado y devuelve el
    resultado esperado de cada celda corregida: valor, tipo de dato y formato."""
    lo = Libro(ruta_orig)
    t_o = detectar_tablas(lo, rep.get("tabla"))
    # Encabezados y textos generales los resuelven las reglas de reportes.json
    res0 = Resultado()
    for regla in rep.get("transformaciones", []):
        if regla.get("activo", True) and regla.get("tipo") in ("renombrar_encabezado", "fijar_encabezado", "reemplazar_texto"):
            REGLAS[regla["tipo"]](t_o, regla, res0)
    mod = Libro(ruta_mod)
    t_m = detectar_tablas(mod, rep.get("tabla"))
    formatos = FormatosCeldas(ruta_mod)
    col_id = (rep.get("tabla") or {}).get("columna_id")
    propuestas, avisos = [], []
    if not t_o or not t_m or not col_id:
        avisos.append("sin tabla/columna_id configurada: no se puede comparar por operacion")
        return propuestas, avisos
    if len(t_o) != len(t_m):
        avisos.append("cantidad de tablas distinta (%d vs %d)" % (len(t_o), len(t_m)))
    for to, tm in zip(t_o, t_m):
        enc_o = [normalizar(v) for v in to.hoja.filas[to.fila_enc]]
        enc_m = [normalizar(v) for v in tm.hoja.filas[tm.fila_enc]]
        while enc_o and not enc_o[-1]:
            enc_o.pop()
        while enc_m and not enc_m[-1]:
            enc_m.pop()
        if enc_o != enc_m:
            dif = [(indice_a_letra(j), a, b) for j, (a, b) in enumerate(zip(enc_o + [""] * 50, enc_m + [""] * 50))
                   if a != b]
            avisos.append("encabezado distinto en fila %d: %s" % (to.fila_enc + 1, dif[:6]))
        io_, im_ = filas_por_id(to, col_id), filas_por_id(tm, col_id)
        solo_o = [k for k in io_ if k not in im_]
        solo_m = [k for k in im_ if k not in io_]
        if solo_o:
            avisos.append("operaciones eliminadas a mano: %s" % solo_o[:10])
        if solo_m:
            avisos.append("operaciones agregadas a mano: %s" % solo_m[:10])
        for op, filas_o in io_.items():
            filas_m = im_.get(op, [])
            if not filas_m:
                continue
            pares = emparejar_filas(to, tm, filas_o, filas_m)
            for fo, fm in pares.items():
                for nombre, jo in to.cols.items():
                    jm = tm.col(nombre)
                    if jm is None or nombre == normalizar_encabezado(col_id):
                        continue
                    vo, vm = to.hoja.valor(fo, jo), tm.hoja.valor(fm, jm)
                    if tipo_de_valor(vo) is None and tipo_de_valor(vm) is None:
                        continue
                    if coincide(vo, vm):
                        continue
                    p = {
                        "reporte": rep["id"],
                        "fondo": fondo if len(rep.get("fondos", [])) > 1 else (fondo_de_fila(rep, to, fo) or fondo),
                        "operacion": op,
                        "columna": str(to.hoja.filas[to.fila_enc][jo]).strip(),
                        "valor_contraparte": valor_para_json(vo),
                        "valor_correcto": valor_para_json(vm),
                        "tipo": tipo_de_valor(vm),
                    }
                    if len(filas_o) > 1:
                        cond = condicion_de_fila(to, tm, filas_o, fo, pares, col_id, jo)
                        if cond:
                            p["condicion"] = cond
                        else:
                            p["ocurrencia"] = filas_o.index(fo) + 1
                    if p["tipo"] == "texto" and formatos.tipo != "csv":
                        f = formatos.formato(tm.hoja.nombre, fm, jm)
                        if f:
                            p["formato"] = f
                    p.update({"comentario": "Resultado esperado tomado de %s" % Path(str(ruta_mod)).name[:60],
                              "desde": ctx.hoy.strftime("%Y-%m-%d"), "activo": True})
                    propuestas.append(p)
    return propuestas, avisos


def modo_aprender(ctx, carpeta_orig, carpeta_mod):
    carpeta_orig, carpeta_mod = ruta_larga(carpeta_orig), ruta_larga(carpeta_mod)
    decir("Comparando %s contra %s" % (mostrar(carpeta_orig), mostrar(carpeta_mod)))
    todas = []
    for ruta in sorted(carpeta_orig.iterdir()):
        if not ruta.is_file():
            continue
        rep, fondo, _, _ = identificar_archivo(ctx, ruta.name)
        if rep is None:
            decir("  ?  %s: no corresponde a ningun reporte configurado" % ruta.name)
            continue
        par = carpeta_mod / nombre_de_salida(rep, ruta.name)
        if not par.exists():
            par = carpeta_mod / ruta.name
        if not par.exists():
            decir("  ?  %s: no tiene archivo corregido" % ruta.name)
            continue
        try:
            propuestas, avisos = comparar_par(ctx, rep, fondo, ruta, par)
        except Exception as e:
            decir("  XX %s: %s" % (ruta.name, e))
            continue
        actuales = {id_ajuste(a): a for a in ctx.ajustes}
        nuevas = []
        for prop in propuestas:
            previo = actuales.get(id_ajuste(prop))
            if previo is None:
                prop["_que"] = "nuevo"
            elif (normalizar(previo.get("valor_correcto")) != normalizar(prop["valor_correcto"])
                  or previo.get("tipo") not in (None, prop.get("tipo"))
                  or previo.get("formato") not in (None, prop.get("formato"))):
                prop["_que"] = "cambia"
            elif previo.get("tipo") is None or (prop.get("formato") and previo.get("formato") is None):
                prop["_que"] = "completa"       # mismo valor; agrega tipo/formato
            else:
                continue
            nuevas.append(prop)
        estado = "ok" if not nuevas and not avisos else "%d valor(es) esperado(s) nuevo(s) o distinto(s)" % len(nuevas)
        decir("  %-4s %-16s fondo %-5s %s" % ("." if estado == "ok" else "+", rep["id"], fondo, estado))
        for a in avisos:
            decir("        aviso: %s" % a)
        for prop in nuevas:
            decir("        %-8s op %s%s | %s: %r -> %r (%s%s)" % (
                prop["_que"], prop["operacion"],
                (" [%s]" % ", ".join("%s=%s" % kv for kv in prop["condicion"].items())) if prop.get("condicion") else "",
                prop["columna"], prop["valor_contraparte"], prop["valor_correcto"], prop.get("tipo"),
                (", formato %s" % prop["formato"]) if prop.get("formato") else ""))
        todas += nuevas
    if not todas:
        decir("No hay nada nuevo: el resultado esperado mapeado ya cubre los archivos corregidos.")
        return
    ruta_prop = ctx.dir_json / ("propuestas_ajustes_%s.json" % dt.datetime.now().strftime("%Y%m%d_%H%M%S"))
    guardar_json(ruta_prop, {"ajustes": todas})
    decir("")
    decir("%d propuesta(s) guardadas en %s" % (len(todas), ruta_prop.name))
    resp = preguntar("Agregarlas/actualizarlas en ajustes_operaciones.json? (s/n): ", ctx.interactivo, "n")
    if resp.lower().startswith("s"):
        ruta_aj = ctx.dir_json / "ajustes_operaciones.json"
        respaldo = respaldar(ruta_aj, ctx.dir_json / "_respaldos")
        datos = cargar_json(ruta_aj)
        lista = datos.setdefault("ajustes", [])
        indice = {id_ajuste(a): n for n, a in enumerate(lista) if isinstance(a, dict)}
        agregadas = actualizadas = 0
        for prop in todas:
            prop = {k: v for k, v in prop.items() if not k.startswith("_")}
            n = indice.get(id_ajuste(prop))
            if n is None:
                lista.append(prop)
                agregadas += 1
            else:
                previo = lista[n]
                for k in ("valor_correcto", "tipo", "formato", "valor_contraparte"):
                    if k in prop:
                        previo[k] = prop[k]
                previo["comentario"] = (previo.get("comentario", "") + " | actualizado %s" % ctx.hoy.strftime("%Y-%m-%d")).strip(" |")
                actualizadas += 1
        guardar_json(ruta_aj, datos)
        decir("Agregadas %d, actualizadas %d. Respaldo del archivo anterior: %s" % (agregadas, actualizadas, respaldo))


