# =============================================================================
# INSTALACION
# =============================================================================
SCRIPTS_BO = ["descarga_mtm.py", "colaterales.py", "colaterales_nacional.py", "bot_faltantes.py", "informe_diario.py",
              "DESCARGA_MTM.bat", "PLAN_B_MTM.bat", "BOT_FALTANTES.bat", "BOT_CONTACTOS.bat", "INFORME_DIARIO.bat",
              "LEEME_MTM.txt"]
SCRIPTS_D216 = ["informe_diario.py", "colaterales.py", "colaterales_nacional.py", "INFORME_DIARIO.bat",
                "LEEME_INFORME_DIARIO.txt", "MANUAL_INFORME_DIARIO.docx"]


def preguntar(texto, defecto="n"):
    try:
        r = input(texto).strip()
    except (EOFError, KeyboardInterrupt):
        return defecto
    return r or defecto


def firma_json(obj):
    return hashlib.sha1(json.dumps(obj, sort_keys=True, ensure_ascii=True, separators=(",", ":")).encode()).hexdigest()


def _leer(ruta):
    return json.loads(ruta.read_text(encoding="utf-8-sig"))


def _volcar(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def combinar_configuracion(destino, nuevo_txt):
    """configuracion.json: se mantienen tus valores; se agregan opciones y feriados nuevos."""
    try:
        actual, nuevo = _leer(destino), json.loads(nuevo_txt)
    except Exception:
        return None, "no lo pude leer: se mantiene el tuyo (revisalo)"
    agregado = [k for k in nuevo if k not in actual]
    for k in agregado:
        actual[k] = nuevo[k]
    for k, v in nuevo.items():
        if k in agregado or not isinstance(v, dict) or not isinstance(actual.get(k), dict):
            continue
        for k2, v2 in v.items():
            if k2 not in actual[k]:
                actual[k][k2] = v2
                agregado.append("%s.%s" % (k, k2))
    feriados = [f for f in nuevo.get("feriados", []) if f not in actual.get("feriados", [])]
    if feriados:
        actual["feriados"] = sorted(set(actual.get("feriados", [])) | set(feriados))
    partes = (["%s" % ", ".join(agregado)] if agregado else []) + (["%d feriado(s)" % len(feriados)] if feriados else [])
    # v3.2: el bot ya no deja borradores; "borrador" pasa a "enviar" (pregunta antes de enviar). Notas al dia.
    bot = actual.get("bot_faltantes")
    if isinstance(bot, dict):
        if str(bot.get("modo", "")).strip().lower() == "borrador":
            bot["modo"] = "enviar"
            partes.append("bot_faltantes.modo = enviar")
        bot["_nota"] = NOTA_BOT
    cf = actual.get("correo_faltantes")
    if isinstance(cf, dict) and "_nota_v3" in cf:
        cf["_nota_v3"] = NOTA_V3
    return _volcar(actual), "se mantienen tus valores" + (" y se agrega %s" % " y ".join(partes) if partes else "")


def combinar_reportes_nac(destino, nuevo_txt):
    """reportes.json de nacionales: si no lo editaste, se reemplaza. Si lo editaste, cada banco que siga igual al
    publicado se actualiza (ej. Scotiabank Chile) y se agregan los bancos nuevos; tus cambios se conservan."""
    try:
        actual, nuevo = _leer(destino), json.loads(nuevo_txt)
    except Exception:
        return None, "no lo pude leer: se mantiene el tuyo (revisalo)"
    if firma_json(actual) in REPORTES_NAC_PUBLICADOS:
        return nuevo_txt, "no lo habias editado: se reemplaza (Falabella con fecha de cierre)"
    nuevos = {r.get("id"): r for r in nuevo.get("reportes", [])}
    cambios = []
    lista = actual.setdefault("reportes", [])
    for i, r in enumerate(lista):
        rid = r.get("id") if isinstance(r, dict) else None
        if rid in nuevos and firma_json(r) in REPORTE_NAC_PUBLICADO_POR_ID.get(rid, set()) and \
                firma_json(r) != firma_json(nuevos[rid]):
            lista[i] = nuevos[rid]
            cambios.append("se actualiza %s" % rid)
        elif isinstance(r, dict) and rid == "FALABELLA_MTM":
            # editaste Falabella: solo se corrige la fecha del nombre (cierre, no envio)
            adj = r.get("adjunto")
            if isinstance(adj, dict) and adj.get("patron") == FALABELLA_PATRON_VIEJO:
                adj["patron"] = FALABELLA_PATRON_NUEVO
                cambios.append("Falabella con fecha de cierre")
    ids = {r.get("id") for r in lista if isinstance(r, dict)}
    for rid, r in nuevos.items():
        if rid not in ids:
            lista.append(r)
            cambios.append("se agrega %s" % rid)
    return _volcar(actual), "lo habias editado: se conservan tus cambios; %s" % (", ".join(cambios) or "nada nuevo")


def contenido_bytes(clave):
    c = ARCHIVOS[clave]
    if clave.endswith(".docx"):
        return base64.b64decode("".join(c.split()))
    return c.encode("utf-8")


def escribir(destino, clave, raiz, respaldo, combinar=None):
    """Crea o actualiza un archivo (respalda el anterior). combinar: funcion para JSON existentes."""
    datos = contenido_bytes(clave)
    if destino.suffix.lower() == ".bat":
        datos = datos.replace(b"\r\n", b"\n").replace(b"\n", b"\r\n")
    estado = "creado"
    if destino.exists():
        actual = destino.read_bytes()
        if actual.replace(b"\r\n", b"\n") == datos.replace(b"\r\n", b"\n"):
            return "sin cambios"
        estado = "actualizado (respaldo en _respaldos)"
        if combinar is not None:
            txt, resumen = combinar(destino, datos.decode("utf-8"))
            if txt is None:
                return resumen
            datos = txt.encode("utf-8")
            if actual.replace(b"\r\n", b"\n") == datos.replace(b"\r\n", b"\n"):
                return "sin cambios"
            estado = resumen + " (respaldo en _respaldos)"
        try:
            copia = respaldo / destino.relative_to(raiz)
        except ValueError:
            copia = respaldo / destino.name
        copia.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(str(destino), str(copia))
    destino.parent.mkdir(parents=True, exist_ok=True)
    tmp = destino.with_name(destino.name + ".instalando")
    tmp.write_bytes(datos)
    tmp.replace(destino)
    return estado


def preparar_correos(scripts, bo):
    """Json\\correos_contrapartes.json de cada proceso (lo crea bot_faltantes.py si no existe)."""
    try:
        spec = importlib.util.spec_from_file_location("bot_faltantes", str(scripts / "bot_faltantes.py"))
        bot = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(bot)
    except Exception as e:
        print("   No pude cargar bot_faltantes.py (%s): el archivo lo crea el bot la primera vez." % e)
        return []
    salida = []
    for sub, clave, nombre in (("Nacional", "nacional", "Nacionales"), ("Colaterales", "extranjero", "Extranjeros")):
        j = bo / sub / "Json"
        if not (j / "reportes.json").is_file():
            continue
        try:
            estado = bot.preparar_archivo_correos(j, clave, nombre)
        except Exception as e:
            estado = "no lo pude crear (%s): lo crea el bot la primera vez" % e
        print("   %-40s %s" % (sub + "\\Json\\correos_contrapartes.json", estado))
        salida.append(j / "correos_contrapartes.json")
    return salida


def verificar(rutas):
    errores = []
    for ruta in rutas:
        if not ruta.exists():
            continue
        try:
            if ruta.suffix == ".json":
                json.loads(ruta.read_text(encoding="utf-8-sig"))
            elif ruta.suffix == ".py":
                compile(ruta.read_text(encoding="utf-8"), str(ruta), "exec")
        except Exception as e:
            errores.append("%s: %s" % (ruta, e))
    return errores


def dependencias_faltantes():
    faltan = []
    for modulo, paquete in (("openpyxl", "openpyxl"), ("xlrd", "xlrd"), ("xlwt", "xlwt"), ("requests", "requests"),
                            ("win32com.client", "pywin32")):
        try:
            __import__(modulo)
        except Exception:
            faltan.append(paquete)
    return faltan


def main():
    ap = argparse.ArgumentParser(description="Actualizador Colaterales v3.2 (uso unico)")
    ap.add_argument("--scripts", help="carpeta de las scripts de Back Office (por defecto OneDrive\\Script\\Garantias)")
    ap.add_argument("--bo", help="carpeta ...\\Control Colaterales\\Diario de Back Office")
    ap.add_argument("--d216", help="carpeta D2.16 compartida con el Informe Diario")
    ap.add_argument("--si", action="store_true", help="no pide confirmaciones")
    args = ap.parse_args()
    scripts = Path(args.scripts.strip('"')) if args.scripts else RUTA_SCRIPTS
    bo = Path(args.bo.strip('"')) if args.bo else BO
    d216 = Path(args.d216.strip('"')) if args.d216 else D216
    print("=" * 76)
    print("ACTUALIZADOR COLATERALES v%s - uso unico (usuario %s)" % (VERSION, CASA.name))
    print("=" * 76)
    if not d216.parent.is_dir() and not args.d216:
        print("No encontre la carpeta compartida del Informe Diario:\n  %s" % d216.parent)
        t = preguntar("Pega la ruta de la carpeta D2.16 (Enter = no instalar esa parte): ", "").strip('"')
        d216 = Path(t) if t else None
    print("")
    print("Se va a crear o actualizar:")
    print("  Scripts de Back Office:      %s" % scripts)
    print("  Back Office extranjeros:     %s%s" % (bo / "Colaterales", "" if (bo / "Colaterales").is_dir() else "  (NO EXISTE: se omite)"))
    print("  Back Office nacionales:      %s%s" % (bo / "Nacional", "" if (bo / "Nacional").is_dir() else "  (NO EXISTE: se omite)"))
    print("  Informe Diario (D2.16):      %s" % (d216 or "(se omite)"))
    if VIEJO_NACIONAL.is_dir():
        print("  Nacionales (carpeta antigua): %s (solo colaterales_nacional.py)" % VIEJO_NACIONAL)
    print("No se borra nada; lo que cambia se respalda en _respaldos.")
    if not args.si and preguntar("Continuar? (s/n): ").lower() != "s":
        print("Cancelado. No se hizo ningun cambio.")
        return 1
    marca = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    revisar = []

    print("")
    print("1) Scripts de Back Office")
    for nombre in SCRIPTS_BO:
        d = scripts / nombre
        print("   %-28s %s" % (nombre, escribir(d, "scripts/" + nombre, scripts, scripts / "_respaldos" / marca)))
        revisar.append(d)

    for sub, motor, extra in (("Colaterales", "colaterales.py", []),
                              ("Nacional", "colaterales_nacional.py", ["reportes.json"])):
        raiz = bo / sub
        print("")
        print("2) Back Office %s: %s" % ("extranjeros" if sub == "Colaterales" else "nacionales", raiz))
        if not raiz.is_dir():
            print("   NO EXISTE: se omite (revisa que la carpeta compartida este sincronizada)")
            continue
        resp = raiz / "_respaldos" / marca
        d = raiz / "Script" / motor
        print("   %-28s %s" % ("Script\\" + motor, escribir(d, "scripts/" + motor, raiz, resp)))
        revisar.append(d)
        clave_json = "json_ext" if sub == "Colaterales" else "json_nac"
        d = raiz / "Json" / "configuracion.json"
        print("   %-28s %s" % ("Json\\configuracion.json", escribir(d, clave_json + "/configuracion.json", raiz, resp,
                                                                     combinar_configuracion)))
        revisar.append(d)
        for nombre in extra:
            d = raiz / "Json" / nombre
            print("   %-28s %s" % ("Json\\" + nombre, escribir(d, clave_json + "/" + nombre, raiz, resp,
                                                             combinar_reportes_nac)))
            revisar.append(d)

    print("")
    print("3) Correos de cada banco")
    revisar += preparar_correos(scripts, bo)

    if VIEJO_NACIONAL.is_dir() and (VIEJO_NACIONAL / "colaterales_nacional.py").exists():
        print("")
        print("3b) Carpeta antigua de nacionales: %s" % VIEJO_NACIONAL)
        d = VIEJO_NACIONAL / "colaterales_nacional.py"
        print("   %-28s %s" % ("colaterales_nacional.py", escribir(d, "scripts/colaterales_nacional.py", VIEJO_NACIONAL,
                                                                   VIEJO_NACIONAL / "_respaldos" / marca)))

    if d216 is not None:
        print("")
        print("4) Informe Diario: %s" % d216)
        try:
            for sub in ("Nacional", "Extranjero", "Excel", "Script"):
                (d216 / sub).mkdir(parents=True, exist_ok=True)
            resp = d216 / "Script" / "_respaldos" / marca
            for nombre in SCRIPTS_D216:
                clave = ("d216/" + nombre) if ("d216/" + nombre) in ARCHIVOS else ("scripts/" + nombre)
                d = d216 / "Script" / nombre
                print("   %-28s %s" % ("Script\\" + nombre, escribir(d, clave, d216, resp)))
                revisar.append(d)
            # JSON que usa la script del Informe Diario: copia de los de Back Office (los mantiene al dia DESCARGA_MTM)
            for sub_bo, sub, clave_json in (("Colaterales", "Extranjero", "json_ext"), ("Nacional", "Nacional", "json_nac")):
                for nombre in ("reportes.json", "configuracion.json"):
                    destino = d216 / "Script" / "Json" / sub / nombre
                    origen = bo / sub_bo / "Json" / nombre
                    destino.parent.mkdir(parents=True, exist_ok=True)
                    if origen.is_file():
                        if destino.is_file() and destino.read_bytes() == origen.read_bytes():
                            estado = "sin cambios"
                        else:
                            shutil.copy2(str(origen), str(destino))
                            estado = "copiado de Back Office"
                    elif (clave_json + "/" + nombre) in ARCHIVOS:
                        estado = escribir(destino, clave_json + "/" + nombre, d216, resp)
                    else:
                        estado = "FALTA: ejecuta DESCARGA_MTM.bat para copiarlo"
                    print("   %-28s %s" % ("Script\\Json\\%s\\%s" % (sub, nombre), estado))
                    revisar.append(destino)
        except Exception as e:
            print("   No pude crear la carpeta del Informe Diario: %s" % e)

    errores = verificar(revisar)
    print("")
    if errores:
        print("ATENCION, hay archivos con errores:")
        for e in errores:
            print("  - " + e)
    else:
        print("Verificacion OK: JSON validos y scripts sin errores de sintaxis.")
    faltan = dependencias_faltantes()
    if faltan:
        print("Faltan librerias de Python: %s" % ", ".join(faltan))
        if not args.si and preguntar("Instalarlas ahora? (s/n): ").lower() == "s":
            subprocess.call([sys.executable, "-m", "pip", "install"] + faltan)
    print("")
    print("LISTO. Desde ahora:")
    print("  1. Cada dia: %s (nacionales y extranjeros, y copia a D2.16)." % (scripts / "DESCARGA_MTM.bat"))
    print("     Banco Falabella se descarga con el archivo que manda la tarde anterior (como BTG).")
    print("  2. Al final te pide los correos de los bancos que falten, muestra a quien va cada correo de")
    print("     contratos faltantes y pregunta si los envia por Outlook (s/N).")
    print("     Correos de cada banco: Json\\correos_contrapartes.json (editable) o %s." % (scripts / "BOT_CONTACTOS.bat"))
    if d216 is not None:
        print("  3. Equipo del Informe Diario: Excel en %s y doble clic en %s." % (d216 / "Excel", d216 / "Script" / "INFORME_DIARIO.bat"))
    print("  Esta script era de uso unico: ya la puedes borrar.")
    print("  Detalle: %s" % (scripts / "LEEME_MTM.txt"))
    if not args.si:
        preguntar("\nEnter para cerrar...", "")
    return 0


if __name__ == "__main__":
    sys.exit(main())
